INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b1aad8-2965-4a60-a7ec-e60ed7939858', '小遊仙詩九十八首 三十九', '小游仙诗九十八首 三十九', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["暘谷先生下宴時，月光初冷紫瓊枝。","淒清金石揭天地，事在世間人不知。"]', '["暘谷先生下宴时，月光初冷紫瓊枝。","淒清金石揭天地，事在世间人不知。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十九 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0551bafa-0526-40b8-b386-f720f45dacef', '小遊仙詩九十八首 四十', '小游仙诗九十八首 四十', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["共愛初平住九霞，焚香不出閉金華。","白羊成隊難收拾，喫盡溪頭巨勝花。"]', '["共愛初平住九霞，焚香不出閉金华。","白羊成隊难收拾，喫尽溪头巨勝花。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d9aaf41-bddd-4040-907b-73b56b50c5c5', '小遊仙詩九十八首 四十一', '小游仙诗九十八首 四十一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["酒盡香殘夜欲分，青童拜問紫陽君。","月光悄悄笙歌遠，馬影龍聲歸五雲。"]', '["酒尽香殘夜欲分，青童拜问紫陽君。","月光悄悄笙歌远，马影龙声归五云。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e2a94c-085c-4e17-b692-c1e1df917969', '小遊仙詩九十八首 四十二', '小游仙诗九十八首 四十二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["海樹靈風吹彩煙，丹陵朝客欲昇天。","無央公子停鸞轡，笑泥嬌妃索玉鞭。"]', '["海樹靈风吹彩煙，丹陵朝客欲昇天。","無央公子停鸾轡，笑泥嬌妃索玉鞭。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f62a50-57a2-4498-89d1-a02779a5ee4d', '小遊仙詩九十八首 四十三', '小游仙诗九十八首 四十三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["八景風回五鳳車，崑崙山上看桃花。","若教使者沽春酒，須覓餘杭阿母家。"]', '["八景风回五鳳车，崑崙山上看桃花。","若教使者沽春酒，須覓餘杭阿母家。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3271e9a2-4151-4f86-9c51-5620d7200fe2', '小遊仙詩九十八首 四十四', '小游仙诗九十八首 四十四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["叔卿遍覽九天春，不見人間故舊人。","怪得蓬萊山下水，半成沙土半成塵。"]', '["叔卿遍覽九天春，不见人间故旧人。","怪得蓬萊山下水，半成沙土半成塵。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c93c7466-1efd-4d93-968b-611e5e834804', '小遊仙詩九十八首 四十五', '小游仙诗九十八首 四十五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["欲飲尊中雲母漿，月明花裏合笙簧。","更教小奈將龍去，便向金壇取阮郎。"]', '["欲饮尊中云母漿，月明花裏合笙簧。","更教小奈將龙去，便向金壇取阮郎。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74ca9a56-bf9d-46f9-bc8a-9d429126eea4', '小遊仙詩九十八首 四十六', '小游仙诗九十八首 四十六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["海上桃花千樹開，麻姑一去不知來。","遼東老鶴應慵惰，教探桑田便不回。"]', '["海上桃花千樹开，麻姑一去不知来。","遼东老鹤應慵惰，教探桑田便不回。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737be5ea-05d2-4717-bbe4-1b70f2a5d81e', '小遊仙詩九十八首 四十七', '小游仙诗九十八首 四十七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["昨夜相邀宴杏壇，等閑乘醉走青鸞。","紅雲塞路東風緊，吹破芙蓉碧玉冠。"]', '["昨夜相邀宴杏壇，等闲乘醉走青鸾。","紅云塞路东风緊，吹破芙蓉碧玉冠。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5082b4ad-b21a-4e64-8df2-182c8fcfbcd8', '小遊仙詩九十八首 四十八', '小游仙诗九十八首 四十八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["雲鶴冥冥去不分，落花流水恨空存。","不知玉女無期信，道與留門却閉門。"]', '["云鹤冥冥去不分，落花流水恨空存。","不知玉女無期信，道與留门却閉门。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十八 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67960cbc-c0e6-49f0-a82f-96ed3a4e949e', '小遊仙詩九十八首 四十九', '小游仙诗九十八首 四十九', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["采女平明受事回，暗交丹契錦囊開。","欲書密詔防人見，佯喝青虬使莫來。"]', '["采女平明受事回，暗交丹契錦囊开。","欲书密詔防人见，佯喝青虬使莫来。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四十九 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93068034-b24f-4844-9284-0e92270d2e50', '小遊仙詩九十八首 五十', '小游仙诗九十八首 五十', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["太一元君昨夜過，碧雲高髻綰婆娑。","手擡玉策紅於火，敲斷金鸞使唱歌。"]', '["太一元君昨夜過，碧云高髻綰婆娑。","手擡玉策紅於火，敲斷金鸾使唱歌。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b54bed-582a-4fe6-bcdb-8bf68ecfa570', '小遊仙詩九十八首 五十一', '小游仙诗九十八首 五十一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["碧瓦彤軒月殿開，九天花落瑞風來。","玉皇欲著紅龍衮，親喚金妃下手裁。"]', '["碧瓦彤軒月殿开，九天花落瑞风来。","玉皇欲著紅龙衮，親喚金妃下手裁。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c86aa8-af41-4458-9466-dae65e447ebd', '小遊仙詩九十八首 五十二', '小游仙诗九十八首 五十二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["長房自貴解飛飜，五色雲中獨閉門。","看却桑田欲成海，不知還往幾人存。"]', '["长房自貴解飞飜，五色云中独閉门。","看却桑田欲成海，不知還往幾人存。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6176e93a-b752-4649-a999-d98e87b26d5d', '小遊仙詩九十八首 五十三', '小游仙诗九十八首 五十三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["赤龍停步彩雲飛，共道真王海上歸。","千歲紅桃香破鼻，玉盤盛出與金妃。"]', '["赤龙停步彩云飞，共道真王海上归。","千歲紅桃香破鼻，玉盤盛出與金妃。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ebf232b-96ef-4ff5-8a3d-bbcb7e6cd88a', '小遊仙詩九十八首 五十四', '小游仙诗九十八首 五十四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["碧海靈童夜到時，徒老相喚上瓊池。","因循天子能閑事，縱與青龍不解騎。"]', '["碧海靈童夜到时，徒老相喚上瓊池。","因循天子能闲事，縱與青龙不解騎。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('583a34b8-e946-4472-927e-32baf51f348d', '小遊仙詩九十八首 五十五', '小游仙诗九十八首 五十五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["且欲留君飲桂漿，九天無事莫推忙。","青龍舉步行千里，休道蓬萊歸路長。"]', '["且欲留君饮桂漿，九天無事莫推忙。","青龙舉步行千里，休道蓬萊归路长。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3156afd7-3991-48a0-b870-ea43b5d25192', '小遊仙詩九十八首 五十六', '小游仙诗九十八首 五十六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["侍女親擎玉酒巵，滿巵傾酒勸安期。","等閑相別三千歲，長憶水邊分棗時。"]', '["侍女親擎玉酒巵，满巵傾酒勸安期。","等闲相別三千歲，长憶水邊分棗时。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96c88a70-bdee-4645-9595-a565a09be949', '小遊仙詩九十八首 五十七', '小游仙诗九十八首 五十七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["萬歲蛾眉不解愁，旋彈清瑟旋閑遊。","忽聞下界笙簫曲，斜倚紅鸞笑不休。"]', '["万歲蛾眉不解愁，旋彈清瑟旋闲游。","忽闻下界笙簫曲，斜倚紅鸾笑不休。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f497ab3-676d-4086-9bad-e42a58090a46', '小遊仙詩九十八首 五十八', '小游仙诗九十八首 五十八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["去住樓臺一任風，十三天洞暗相通。","行廚侍女炊何物，滿竈無煙玉炭紅。"]', '["去住楼台一任风，十三天洞暗相通。","行廚侍女炊何物，满竈無煙玉炭紅。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十八 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cb7dd84-0100-4dca-9eb7-d1bdd792ee24', '小遊仙詩九十八首 五十九', '小游仙诗九十八首 五十九', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["風動閑天清桂陰，水精簾箔冷沉沉。","西妃少女多春思，斜倚彤雲盡日吟。"]', '["风动闲天清桂陰，水精簾箔冷沉沉。","西妃少女多春思，斜倚彤云尽日吟。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五十九 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aac10999-6868-4a5a-8ec0-fc3d16aff91b', '小遊仙詩九十八首 六十', '小游仙诗九十八首 六十', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["王母相留不放回，偶然沉醉臥瑤臺。","憑君與向蕭郎道，教著青龍取妾來。"]', '["王母相留不放回，偶然沉醉臥瑤台。","憑君與向蕭郎道，教著青龙取妾来。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4178a61-f447-43b9-8eb7-3d047c211a9d', '小遊仙詩九十八首 六十一', '小游仙诗九十八首 六十一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["絳節笙歌繞殿飛，紫皇欲到五雲歸。","細腰侍女瑤花外，爭向紅房報玉妃。"]', '["絳節笙歌繞殿飞，紫皇欲到五云归。","細腰侍女瑤花外，爭向紅房報玉妃。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b22b2fbd-3001-46b0-bec3-d140ba97bc5c', '小遊仙詩九十八首 六十二', '小游仙诗九十八首 六十二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["聞君新領八霞司，此別相逢是幾時。","妾有一觥雲母酒，請君終宴莫推辭。"]', '["闻君新領八霞司，此別相逢是幾时。","妾有一觥云母酒，請君終宴莫推辞。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a2678da-d0e5-4e09-8017-228af16f4c54', '小遊仙詩九十八首 六十三', '小游仙诗九十八首 六十三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["方士飛軒駐碧霞，酒寒風冷月初斜。","不知誰唱歸春曲，落盡溪頭白葛花。"]', '["方士飞軒駐碧霞，酒寒风冷月初斜。","不知誰唱归春曲，落尽溪头白葛花。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efe2e885-db7a-4291-8b5e-646e76416d90', '小遊仙詩九十八首 六十四', '小游仙诗九十八首 六十四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["方朔朝來到我家，欲將靈樹出丹霞。","三千年後知誰在，擬種紅桃待放花。"]', '["方朔朝来到我家，欲將靈樹出丹霞。","三千年後知誰在，擬種紅桃待放花。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fdecc70-5ff0-42ca-a338-b734e13a8829', '小遊仙詩九十八首 六十五', '小游仙诗九十八首 六十五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["水滿桑田白日沈，凍雲乾霰濕重陰。","遼東歸客閑相過，因話堯年雪更深。"]', '["水满桑田白日沈，凍云乾霰濕重陰。","遼东归客闲相過，因話堯年雪更深。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da638f0e-9c27-4bd6-baba-66247c6295d7', '小遊仙詩九十八首 六十六', '小游仙诗九十八首 六十六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["朝回相引看紅鸞，不覺風吹鶴氅偏。","好是興來騎白鶴，文妃爲伴上重天。"]', '["朝回相引看紅鸾，不覺风吹鹤氅偏。","好是兴来騎白鹤，文妃爲伴上重天。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8baab52f-e8eb-4a43-a87c-a282154fbfc0', '小遊仙詩九十八首 六十七', '小游仙诗九十八首 六十七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["公子閑吟八景文，花南拜別上陽君。","金鞭遙指玉清路，龍影馬嘶歸五雲。"]', '["公子闲吟八景文，花南拜別上陽君。","金鞭遙指玉清路，龙影马嘶归五云。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c6ea89-3396-41a8-85e6-94aa3da6098e', '小遊仙詩九十八首 六十八', '小游仙诗九十八首 六十八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["一百年中是一春，不教日月輒移輪。","金鼇頭上蓬萊殿，唯有人間鍊骨人。"]', '["一百年中是一春，不教日月輒移輪。","金鼇头上蓬萊殿，唯有人间鍊骨人。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十八 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d6113a-85cf-49b1-a2d5-2f20aef89ae5', '小遊仙詩九十八首 六十九', '小游仙诗九十八首 六十九', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["笑擎雲液紫瑤觥，共請雲和碧玉笙。","花下偶然吹一曲，人間因織董雙成。"]', '["笑擎云液紫瑤觥，共請云和碧玉笙。","花下偶然吹一曲，人间因织董雙成。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六十九 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('238ab7ce-a409-4223-8dc4-171cdf1caa9d', '小遊仙詩九十八首 七十', '小游仙诗九十八首 七十', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["東皇長女沒多年，從洗金芝到水邊。","無事伴他棊一局，等閑輸却賣花錢。"]', '["东皇长女沒多年，從洗金芝到水邊。","無事伴他棊一局，等闲輸却賣花錢。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea38e73-388d-4b20-96de-ea11881611eb', '小遊仙詩九十八首 七十一', '小游仙诗九十八首 七十一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["紅草青林日半斜，閑乘小鳳出彤霞。","略尋舊路過西國，因得冰園一尺瓜。"]', '["紅草青林日半斜，闲乘小鳳出彤霞。","略尋旧路過西国，因得冰园一尺瓜。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1ef90db-93b9-4ee7-b649-a9b63a5953f8', '小遊仙詩九十八首 七十二', '小游仙诗九十八首 七十二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["樹下星沉月欲高，前溪水影濕龍毛。","洞天雲冷玉花發，公子盡披雙錦袍。"]', '["樹下星沉月欲高，前溪水影濕龙毛。","洞天云冷玉花發，公子尽披雙錦袍。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2d41c2a-1a38-40dc-b50d-9f19964c1751', '小遊仙詩九十八首 七十三', '小游仙诗九十八首 七十三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["紫水風吹劒樹寒，水邊年少下紅鸞。","未知百一窮陽數，略請先生止的看。"]', '["紫水风吹劒樹寒，水邊年少下紅鸾。","未知百一窮陽數，略請先生止的看。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da6ed26b-d068-43a8-9431-d13925524fc5', '小遊仙詩九十八首 七十四', '小游仙诗九十八首 七十四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["武皇含笑把金觥，更請霓裳一兩聲。","護帳宮人最年少，舞腰時挈繡裙輕。"]', '["武皇含笑把金觥，更請霓裳一兩声。","護帳宮人最年少，舞腰时挈繡裙轻。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('932b9b54-8768-41e2-8cce-bb41b1f3b29d', '小遊仙詩九十八首 七十五', '小游仙诗九十八首 七十五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["瓊樹扶疎壓瑞煙，玉皇朝客滿花前。","東風小飲人皆醉，短尾青龍枕水眠。"]', '["瓊樹扶疎壓瑞煙，玉皇朝客满花前。","东风小饮人皆醉，短尾青龙枕水眠。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b56272f-fb13-42c9-90a1-f5f302e67e35', '小遊仙詩九十八首 七十六', '小游仙诗九十八首 七十六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["彤閣鐘鳴碧鷺飛，皇君催熨紫霞衣。","丹房玉女心慵甚，貪看投壺不肯歸。"]', '["彤閣鐘鳴碧鷺飞，皇君催熨紫霞衣。","丹房玉女心慵甚，貪看投壺不肯归。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25a25e6b-022d-4c7f-8baa-df3f2061b8e9', '小遊仙詩九十八首 七十七', '小游仙诗九十八首 七十七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["崑崙山上自雞啼，羽客爭昇碧玉梯。","因駕五龍看較藝，白鸞功用不如妻。"]', '["崑崙山上自雞啼，羽客爭昇碧玉梯。","因駕五龙看較藝，白鸾功用不如妻。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d7cdbf-9733-4cb5-b1f8-a61e030e92d9', '小遊仙詩九十八首 七十八', '小游仙诗九十八首 七十八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["沙野先生閉玉虛，焚香夜寫紫微書。","供承童子閑無事，教剉瓊花餵白驢。"]', '["沙野先生閉玉虛，焚香夜寫紫微书。","供承童子闲無事，教剉瓊花餵白驢。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十八 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5938baf6-a1c5-4cb8-883f-86f7ef8d5115', '小遊仙詩九十八首 七十九', '小游仙诗九十八首 七十九', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["雲隴瓊花滿地香，碧沙紅水遍朱堂。","外人欲壓長生籍，拜請飛瓊報玉皇。"]', '["云隴瓊花满地香，碧沙紅水遍朱堂。","外人欲壓长生籍，拜請飞瓊報玉皇。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七十九 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('facc02ca-055a-4a1d-a0a8-3a917c5a19ec', '小遊仙詩九十八首 八十', '小游仙诗九十八首 八十', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["玉洞長春風景鮮，丈人私宴就芝田。","笙歌暫向花間盡，便是人間一萬年。"]', '["玉洞长春风景鲜，丈人私宴就芝田。","笙歌暫向花间尽，便是人间一万年。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeb03285-f3f7-47c1-b1dd-0b8931b512b1', '小遊仙詩九十八首 八十一', '小游仙诗九十八首 八十一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["青童傳語便須回，報道麻姑玉蘂開。","滄海成塵等閑事，且乘龍鶴看花來。"]', '["青童傳語便須回，報道麻姑玉蘂开。","滄海成塵等闲事，且乘龙鹤看花来。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a40936c2-8ace-4cad-9e2c-c9ce95bc38d4', '小遊仙詩九十八首 八十二', '小游仙诗九十八首 八十二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["絳樹彤雲戶半開，守花童子怪人來。","青牛臥地喫瓊草，知道先生朝未回。"]', '["絳樹彤云戶半开，守花童子怪人来。","青牛臥地喫瓊草，知道先生朝未回。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96200dc1-96cf-46b6-b160-0b76afcd4672', '小遊仙詩九十八首 八十三', '小游仙诗九十八首 八十三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["石洞沙溪二十年，向明杭日夜朝天。","白礬煙盡水銀冷，不覺小龍牀下眠。"]', '["石洞沙溪二十年，向明杭日夜朝天。","白礬煙尽水銀冷，不覺小龙牀下眠。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd1d2438-bfba-4eb9-853d-debef47a366f', '小遊仙詩九十八首 八十四', '小游仙诗九十八首 八十四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["紫微深鎖敞丹軒，太帝親談不死門。","從此百寮俱拜後，走龍鞭虎下崑崙。"]', '["紫微深鎖敞丹軒，太帝親談不死门。","從此百寮俱拜後，走龙鞭虎下崑崙。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('702ee2ff-7191-44ff-8c55-2d25cc5a6a4e', '小遊仙詩九十八首 八十五', '小游仙诗九十八首 八十五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["雲衫玉帶好威儀，三洞真人入奏時。","頻着金鞭打龍角，爲嗔西去上天遲。"]', '["云衫玉带好威儀，三洞真人入奏时。","頻着金鞭打龙角，爲嗔西去上天遲。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca30bd2-ad66-4f22-8476-513998b07056', '小遊仙詩九十八首 八十六', '小游仙诗九十八首 八十六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["太子真娥相領行，當天合曲玉簫清。","棃花新折東風軟，猶在緱山樂笑聲。"]', '["太子真娥相領行，當天合曲玉簫清。","棃花新折东风軟，猶在緱山乐笑声。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('538c1dac-686c-4cc5-b39d-10f1eb5d9368', '小遊仙詩九十八首 八十七', '小游仙诗九十八首 八十七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["洞裏月明瓊樹風，畫簾青室影朦朧。","香殘酒冷玉妃睡，不覺七真歸海中。"]', '["洞裏月明瓊樹风，畫簾青室影朦朧。","香殘酒冷玉妃睡，不覺七真归海中。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c0570a-5dd7-4036-b84c-25c2df80e2fe', '小遊仙詩九十八首 八十八', '小游仙诗九十八首 八十八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["青苑紅堂壓瑞雲，月明閑宴九陽君。","不知昨夜誰先醉，書破明霞八幅裙。"]', '["青苑紅堂壓瑞云，月明闲宴九陽君。","不知昨夜誰先醉，书破明霞八幅裙。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十八 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47674538-d3e4-4ba4-8476-0de4c576dcee', '小遊仙詩九十八首 八十九', '小游仙诗九十八首 八十九', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["東溟兩度作塵飛，一萬年來會面稀。","千樹棃花百壺酒，共君論飲莫論詩。"]', '["东溟兩度作塵飞，一万年来會面稀。","千樹棃花百壺酒，共君論饮莫論诗。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八十九 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ee808a-abd0-42e9-9be0-ebf4d37cfdef', '小遊仙詩九十八首 九十', '小游仙诗九十八首 九十', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["滄海令拋即未能，且緣鸞鶴立相仍。","蔡家新婦莫嫌少，領取真珠三五升。"]', '["滄海令拋即未能，且緣鸾鹤立相仍。","蔡家新婦莫嫌少，領取真珠三五升。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九十 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('389bbb28-98a3-4944-9b85-f1ece5b7cebe', '小遊仙詩九十八首 九十一', '小游仙诗九十八首 九十一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["溪影沉沙樹影清，人家皆踏五音行。","可憐三十六天路，星月滿空瓊草青。"]', '["溪影沉沙樹影清，人家皆踏五音行。","可怜三十六天路，星月满空瓊草青。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九十一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93715a3c-0494-4fde-9cbe-f62af5ee8f76', '小遊仙詩九十八首 九十二', '小游仙诗九十八首 九十二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["北斗西風吹白榆，穆公相笑夜投壺。","花前玉女來相問，賭得青龍許贖無。"]', '["北斗西风吹白榆，穆公相笑夜投壺。","花前玉女来相问，賭得青龙許贖無。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九十二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('285a439d-79b5-451f-992a-3431e35d0546', '小遊仙詩九十八首 九十三', '小游仙诗九十八首 九十三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["九天王母皺蛾眉，惆悵無言倚桂枝。","悔不長留穆天子，任將妻妾住瑤池。"]', '["九天王母皺蛾眉，惆悵無言倚桂枝。","悔不长留穆天子，任將妻妾住瑤池。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九十三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ae01b23-96f7-44e9-a32d-e9ef0ceb0577', '小遊仙詩九十八首 九十四', '小游仙诗九十八首 九十四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["暫隨鳧伯縱閑遊，飲鹿因過翠水頭。","宮殿寂寥人不見，碧花菱角滿潭秋。"]', '["暫隨鳧伯縱闲游，饮鹿因過翠水头。","宮殿寂寥人不见，碧花菱角满潭秋。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九十四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e58c5aea-de33-48ed-822f-b716bf2c0732', '小遊仙詩九十八首 九十五', '小游仙诗九十八首 九十五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["新授金書八素章，玉皇教妾主扶桑。","與君一別三千歲，却厭仙家日月長。"]', '["新授金书八素章，玉皇教妾主扶桑。","與君一別三千歲，却厭仙家日月长。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九十五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66ddca6a-fb9d-439e-b66e-4fde9b847d6f', '小遊仙詩九十八首 九十六', '小游仙诗九十八首 九十六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["八海風涼水影高，上卿教製赤霜袍。","蛟絲玉線難裁割，須借玉妃金剪刀。"]', '["八海风涼水影高，上卿教製赤霜袍。","蛟絲玉線难裁割，須借玉妃金剪刀。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九十六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac1fd190-947e-4617-b98d-0f29b01018de', '小遊仙詩九十八首 九十七', '小游仙诗九十八首 九十七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["海上風來吹杏枝，崑崙山上看花時。","紅龍錦襜黃金勒，不是元君不得騎。"]', '["海上风来吹杏枝，崑崙山上看花时。","紅龙錦襜黄金勒，不是元君不得騎。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九十七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f3c108-0507-40ff-afef-3662164c0eb9', '小遊仙詩九十八首 九十八', '小游仙诗九十八首 九十八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["絳闕夫人下北方，細環清珮響丁當。","攀花笑入春風裏，偷折紅桃寄阮郎。"]', '["絳闕夫人下北方，細环清珮响丁當。","攀花笑入春风裏，偷折紅桃寄阮郎。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九十八 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca3f847-34a1-46f4-ba4a-4c7cd0d8dc7e', '又遊仙詩一絕', '又游仙诗一絕', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["靖節先生幾代孫，青娥曾接玉郎魂。","春風流水還無賴，偷放桃花出洞門。"]', '["靖節先生幾代孫，青娥曾接玉郎魂。","春风流水還無賴，偷放桃花出洞门。"]', '诗', 'shi', '', NULL, '又遊仙詩一絕 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4f1f2e0-ae1f-41ab-970f-9de7cf4d61a0', '題武陵洞五首 一', '題武陵洞五首 一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["此生終使此身閑，不是春時且要還。","寄語桃花與流水，莫辭相送到人間。"]', '["此生終使此身闲，不是春时且要還。","寄語桃花與流水，莫辞相送到人间。"]', '诗', 'shi', '', NULL, '題武陵洞五首 一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b079cb-568a-44cb-8715-0fe895f6226d', '題武陵洞五首 二', '題武陵洞五首 二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["溪口回舟日已昏，却聽雞犬隔前村。","殷勤重與秦人別，莫使桃花閉洞門。"]', '["溪口回舟日已昏，却听雞犬隔前村。","殷勤重與秦人別，莫使桃花閉洞门。"]', '诗', 'shi', '', NULL, '題武陵洞五首 二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e857c8-8f39-495c-bf82-971bcd6ef3a2', '題武陵洞五首 三', '題武陵洞五首 三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["却恐重來路不通，殷勤回首謝春風。","白雞黃犬不將去，且寄桃花深洞中。"]', '["却恐重来路不通，殷勤回首謝春风。","白雞黄犬不將去，且寄桃花深洞中。"]', '诗', 'shi', '', NULL, '題武陵洞五首 三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72a74391-ef14-4e13-9869-a3bcbc97d4bf', '題武陵洞五首 四', '題武陵洞五首 四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["桃花夾岸杳何之，花滿春山水去遲。","三宿武陵溪上月，始知人世有秦時。"]', '["桃花夾岸杳何之，花满春山水去遲。","三宿武陵溪上月，始知人世有秦时。"]', '诗', 'shi', '', NULL, '題武陵洞五首 四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f37780-9663-48cf-9404-57f7e320d453', '題武陵洞五首 五', '題武陵洞五首 五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["渡水傍山尋絕壁，白雲飛處洞天開。","仙人來往無行跡，石逕春風長綠苔。"]', '["渡水傍山尋絕壁，白云飞处洞天开。","仙人来往無行跡，石逕春风长綠苔。"]', '诗', 'shi', '', NULL, '題武陵洞五首 五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3861407e-9699-4fdf-b7b7-897a86f14ca5', '句', '句', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["斬蛟青海上，射虎黑山頭。","簫聲欲盡月色苦，依舊漢家宮樹秋。","一曲哀歌茂陵道，漢家天子葬秋風。","誰知漢武無仙骨，滿竈黃金成白煙。"]', '["斬蛟青海上，射虎黑山头。","簫声欲尽月色苦，依旧漢家宮樹秋。","一曲哀歌茂陵道，漢家天子葬秋风。","誰知漢武無仙骨，满竈黄金成白煙。"]', '诗', 'shi', '', NULL, '句 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52bb5a86-1af9-4f85-bfe7-977a7e11f247', '聖政紀頌', '聖政紀頌', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["三皇不書，五帝不紀。","有聖有神，風銷日已。","何教何師，生來死止。","無典無法，頑肩奡比。","三皇實作，五帝實治。","成天造地，不昏不圯。","言得非排，文得聖齒。","表表如見者，莫若乎史。","是知朴繩休結，正簡斯若。","君誥臣箴，觚編毫絡。","前書後經，規善鑒惡。","國之大章，如何寢略。","嗚呼！貞觀多吁，永徽多俞。","廷日發論，殿日發謨。","牙孽不作，鳥鼠不除。","論出不蓋，謨行不紆。","楹然史臣，蛇然史裾。","瞠瞠而視，逶逶而窶。","翹筆當面，決防納污。","不梏爾智，不息我愚。","執言直注，史文直敷。","故得粲粲朝典，落落廷謇。","聖牘既多，堯風不淺。","頌編坦軸，君出臣顯。","若儼見旒，若俯見冕。","無閑殿曠廷，無尸安素宴。","三皇不亡，五帝不翦。","太宗得之，史焉斯展。","暨乎後相圖身，天子專問。","我獨以言，史不得近。","丘明見嫌，倚相在擯。","秉筆如今，隨班不進。","班退史歸，枉然疇依。","奏問莫覩，嘉謨固稀。","取彼誥命，祿爲國肥。","炯哉時皇，言必成章。","德宣五帝，道奧三皇。","如何翌臣，嚵肉嗜𥁃。","觜距磨抉，楅衡拘長。","控截僚位，占護陽光。","垣私藩已，遠史廋唐。","俾德音嘉訪，默縮暗亡。","咽典噤法，蓋聖籠昌。","曷以致此，史文不張。","後必非笑，將來否臧。","謂乎殿空扆逸，朝懵廷荒。","不知姦蔽，文失汪洋。","有貞觀業，有永徽綱。","亦匿匪見，亦寢匪彰。","賴有後臣，斯言不佞。","伊尹直心，太甲須聖。","事既可書，史何不命。","乃具前欺，大陳不敬。","曰逐史之喻，請以物竝。","且十夫樹楊，一夫欲競。","栽既未牢，摒豈能盛。","帝業似栽，逐史似摒。","穆宗憮然，若疚若醟。","昔何臣斯，隱我祖正。","不傳親問，不寫密諍。","孰示來朝，以光神政。","由是天呼震吸，徵奔召急。","史題筆來，叱廷而入。","端耳抗目，不撝不挹。","獬豸側頭，螭蚪擺溼。","握管絕怡，當殿而立。","君也盡問，臣也倒誠。","磊磊其事，鏜鏜其聲。","大何不顯，細何不明。","語未絕緒，史已錄成。","謂之何書，以政紀名。","伊紀清芬，可昭典墳。","古師官鳥，昔聖官雲。","方之我后，錄里書分。","錄有君法，書有君文。","君法君文，在聖政紀云。","殿無閑時，廷無曠日。","雲諏波訪，卷編刓筆。","君劬臣勞，上討下述。","惟勤惟明，在聖政紀出。","至德何比，至教焉如。","孰窺孰測，外夷內儲。","謂君有道乎，臣有謨歟。","有道有謨，在聖政紀書。","一體列秩，同力翼戴。","祈福去邪，絕防無礙。","國章可披，唐文可愛。","善咨不偷，嘉論不蓋。","不偷不蓋，在聖政紀載。","諒夫，總斯不朽。","可懸魏闕，愚得是言。","非訕非伐，實謂醫臣渾沌。","開君日月，妖物雰死。","天文光發，惟我之有頌兮，奚斯躍而董狐蹙。"]', '["三皇不书，五帝不紀。","有聖有神，风銷日已。","何教何師，生来死止。","無典無法，頑肩奡比。","三皇實作，五帝實治。","成天造地，不昏不圯。","言得非排，文得聖齒。","表表如见者，莫若乎史。","是知朴繩休結，正簡斯若。","君誥臣箴，觚編毫絡。","前书後經，規善鑒惡。","国之大章，如何寢略。","嗚呼！貞观多吁，永徽多俞。","廷日發論，殿日發謨。","牙孽不作，鸟鼠不除。","論出不蓋，謨行不紆。","楹然史臣，蛇然史裾。","瞠瞠而視，逶逶而窶。","翹笔當面，決防納污。","不梏爾智，不息我愚。","執言直注，史文直敷。","故得粲粲朝典，落落廷謇。","聖牘既多，堯风不淺。","頌編坦軸，君出臣显。","若儼见旒，若俯见冕。","無闲殿曠廷，無尸安素宴。","三皇不亡，五帝不翦。","太宗得之，史焉斯展。","暨乎後相圖身，天子專问。","我独以言，史不得近。","丘明见嫌，倚相在擯。","秉笔如今，隨班不進。","班退史归，枉然疇依。","奏问莫覩，嘉謨固稀。","取彼誥命，祿爲国肥。","炯哉时皇，言必成章。","德宣五帝，道奧三皇。","如何翌臣，嚵肉嗜𥁃。","觜距磨抉，楅衡拘长。","控截僚位，占護陽光。","垣私藩已，远史廋唐。","俾德音嘉訪，默縮暗亡。","咽典噤法，蓋聖籠昌。","曷以致此，史文不張。","後必非笑，將来否臧。","謂乎殿空扆逸，朝懵廷荒。","不知姦蔽，文失汪洋。","有貞观業，有永徽綱。","亦匿匪见，亦寢匪彰。","賴有後臣，斯言不佞。","伊尹直心，太甲須聖。","事既可书，史何不命。","乃具前欺，大陳不敬。","曰逐史之喻，請以物竝。","且十夫樹楊，一夫欲競。","栽既未牢，摒豈能盛。","帝業似栽，逐史似摒。","穆宗憮然，若疚若醟。","昔何臣斯，隐我祖正。","不傳親问，不寫密諍。","孰示来朝，以光神政。","由是天呼震吸，徵奔召急。","史題笔来，叱廷而入。","端耳抗目，不撝不挹。","獬豸側头，螭蚪擺溼。","握管絕怡，當殿而立。","君也尽问，臣也倒誠。","磊磊其事，鏜鏜其声。","大何不显，細何不明。","語未絕緒，史已錄成。","謂之何书，以政紀名。","伊紀清芬，可昭典墳。","古師官鸟，昔聖官云。","方之我后，錄里书分。","錄有君法，书有君文。","君法君文，在聖政紀云。","殿無闲时，廷無曠日。","云諏波訪，卷編刓笔。","君劬臣勞，上討下述。","惟勤惟明，在聖政紀出。","至德何比，至教焉如。","孰窺孰測，外夷內儲。","謂君有道乎，臣有謨歟。","有道有謨，在聖政紀书。","一體列秩，同力翼戴。","祈福去邪，絕防無礙。","国章可披，唐文可愛。","善咨不偷，嘉論不蓋。","不偷不蓋，在聖政紀載。","諒夫，總斯不朽。","可懸魏闕，愚得是言。","非訕非伐，實謂醫臣渾沌。","开君日月，妖物雰死。","天文光發，惟我之有頌兮，奚斯躍而董狐蹙。"]', '诗', 'shi', '', NULL, '聖政紀頌 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac77a741-d6cc-4047-9e9e-e708f0f2d22e', '宛陵送李明府罷任歸江州', '宛陵送李明府罷任归江州', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["菊花村晚雁來天，共把離觴向水邊。","官滿便尋垂釣侶，家貧已用賣琴錢。","浪生湓浦千層雪，雲起爐峰一炷煙。","倘見吾鄉舊知己，爲言顦顇過年年。"]', '["菊花村晚雁来天，共把離觴向水邊。","官满便尋垂釣侶，家貧已用賣琴錢。","浪生湓浦千層雪，云起爐峰一炷煙。","倘见吾乡旧知己，爲言顦顇過年年。"]', '诗', 'shi', '', NULL, '宛陵送李明府罷任歸江州 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b70cb525-c13d-410e-b14d-d625f88d3eab', '清明日與友人遊玉粒塘莊', '清明日與友人游玉粒塘莊', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["幾宿春山逐陸郎，清明時節好煙光。","歸穿細荇船頭滑，醉踏殘花屐齒香。","風急嶺雲飄迥野，雨餘田水落方塘。","不堪吟罷東回首，滿耳蛙聲正夕陽。"]', '["幾宿春山逐陸郎，清明时節好煙光。","归穿細荇船头滑，醉踏殘花屐齒香。","风急嶺云飄迥野，雨餘田水落方塘。","不堪吟罷东回首，满耳蛙声正夕陽。"]', '诗', 'shi', '', NULL, '清明日與友人遊玉粒塘莊 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a2c2ba-ca07-461d-8c95-58bc5dfe64f8', '寒食山館書情', '寒食山館书情', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["獨把一杯山館中，每經時節恨飄蓬。","侵堦草色連朝雨，滿地梨花昨夜風。","蜀魄啼來春寂寞，楚魂吟後月朦朧。","分明記得還家夢，徐孺宅前湖水東。"]', '["独把一杯山館中，每經时節恨飄蓬。","侵堦草色連朝雨，满地梨花昨夜风。","蜀魄啼来春寂寞，楚魂吟後月朦朧。","分明記得還家梦，徐孺宅前湖水东。"]', '诗', 'shi', '', NULL, '寒食山館書情 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9bc20c3-5663-4c2e-bcca-1c8e25820147', '病起', '病起', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["春初一臥到秋深，不見紅芳與綠陰。","窗下展書難久讀，池邊扶杖欲閑吟。","藕穿平地生荷葉，笋過東家作竹林。","在舍渾如遠鄉客，詩僧酒伴鎮相尋。"]', '["春初一臥到秋深，不见紅芳與綠陰。","窗下展书难久读，池邊扶杖欲闲吟。","藕穿平地生荷葉，笋過东家作竹林。","在舍渾如远乡客，诗僧酒伴鎮相尋。"]', '诗', 'shi', '', NULL, '病起 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('291649a3-b0c3-4d02-b55f-21927738cc04', '鄂渚除夜書懷', '鄂渚除夜书懷', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["鸚鵡洲頭夜泊船，此時形影共淒然。","難歸故國干戈後，欲告何人雨雪天。","筯撥冷灰書悶字，枕陪寒席帶愁眠。","自嗟落魄無成事，明日春風又一年。"]', '["鸚鵡洲头夜泊船，此时形影共淒然。","难归故国干戈後，欲告何人雨雪天。","筯撥冷灰书悶字，枕陪寒席带愁眠。","自嗟落魄無成事，明日春风又一年。"]', '诗', 'shi', '', NULL, '鄂渚除夜書懷 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f573c0f4-72e6-4e2c-9eb2-f690c7422808', '鄂渚清明日與鄉友登頭陀山', '鄂渚清明日與乡友登头陀山', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["冷酒一杯相勸頻，異鄉相遇轉相親。","落花風裏數聲笛，芳草煙中無限人。","都大此時深悵望，豈堪高處更逡巡。","思量費子真仙子，不作頭陀山下塵。"]', '["冷酒一杯相勸頻，異乡相遇轉相親。","落花风裏數声笛，芳草煙中無限人。","都大此时深悵望，豈堪高处更逡巡。","思量費子真仙子，不作头陀山下塵。"]', '诗', 'shi', '', NULL, '鄂渚清明日與鄉友登頭陀山 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('491e12d6-4fb9-4c00-b315-9fdf952f3f6d', '蠶婦', '蠶婦', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["曉夕採桑多苦辛，好花時節不閑身。","若教解愛繁華事，凍殺黃金屋裏人。"]', '["晓夕採桑多苦辛，好花时節不闲身。","若教解愛繁华事，凍殺黄金屋裏人。"]', '诗', 'shi', '', NULL, '蠶婦 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb09880b-688f-4f60-9f3c-d2edf32782fd', '題廬山雙劒峰', '題廬山雙劒峰', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["倚天雙劒古今閑，三尺高於四面山。","若使火雲燒得動，始應農器滿人間。"]', '["倚天雙劒古今闲，三尺高於四面山。","若使火云燒得动，始應農器满人间。"]', '诗', 'shi', '', NULL, '題廬山雙劒峰 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d32b372-5481-4ac0-b0f1-580ab50d05c9', '雲', '云', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["千形萬象竟還空，映水藏山片復重。","無限旱苗枯欲盡，悠悠閑處作奇峰。"]', '["千形万象竟還空，映水藏山片复重。","無限旱苗枯欲尽，悠悠闲处作奇峰。"]', '诗', 'shi', '', NULL, '雲 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b823010-6edb-4594-8db7-98b47827647c', '金錢花', '金錢花', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["也無稜郭也無神，露洗還同鑄出新。","青帝若教花裏用，牡丹應是得錢人。"]', '["也無稜郭也無神，露洗還同鑄出新。","青帝若教花裏用，牡丹應是得錢人。"]', '诗', 'shi', '', NULL, '金錢花 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9e2f62e-e42c-4223-9e16-e976a8ac36ae', '曉雞', '晓雞', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["黯黯嚴城罷鼓鼙，數聲相續出寒栖。","不嫌驚破紗窗夢，却怕爲妖半夜啼。"]', '["黯黯嚴城罷鼓鼙，數声相續出寒栖。","不嫌驚破紗窗梦，却怕爲妖半夜啼。"]', '诗', 'shi', '', NULL, '曉雞 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75dd09a5-71b9-47d8-9f49-593cfed39750', '山中避難作', '山中避难作', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["山頭烽火水邊營，鬼哭人悲夜夜聲。","唯有碧天無一事，日還西下月還明。"]', '["山头烽火水邊營，鬼哭人悲夜夜声。","唯有碧天無一事，日還西下月還明。"]', '诗', 'shi', '', NULL, '山中避難作 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('385dbd50-8382-43c6-ae37-d50a354ae07a', '早春', '早春', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["新曆才將半紙開，小庭猶聚爆竿灰。","偏憎楊柳難鈐轄，又惹東風意緒來。"]', '["新曆才將半紙开，小庭猶聚爆竿灰。","偏憎楊柳难鈐轄，又惹东风意緒来。"]', '诗', 'shi', '', NULL, '早春 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b21b53c7-b74b-4ac4-b7a1-168a86e3a2f7', '鷺鷥', '鷺鷥', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["褭絲翹足傍澄瀾，消盡年光佇思間。","若使見魚無羨意，向人姿態更應閑。"]', '["褭絲翹足傍澄瀾，消尽年光佇思间。","若使见鱼無羨意，向人姿態更應闲。"]', '诗', 'shi', '', NULL, '鷺鷥 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b7c7212-79b7-4d89-bfb6-763add437897', '子規', '子規', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["雨恨花愁同此冤，啼時聞處正春繁。","千聲萬血誰哀爾，爭得如花笑不言。"]', '["雨恨花愁同此冤，啼时闻处正春繁。","千声万血誰哀爾，爭得如花笑不言。"]', '诗', 'shi', '', NULL, '子規 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('925263e8-e4f6-4a92-bab9-263e10418963', '新安官舍閑坐', '新安官舍闲坐', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["寂寞空階草亂生，簟涼風動若爲情。","不知獨坐閑多少，看得蜘蛛結網成。"]', '["寂寞空階草亂生，簟涼风动若爲情。","不知独坐闲多少，看得蜘蛛結網成。"]', '诗', 'shi', '', NULL, '新安官舍閑坐 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b54c55e-4d58-4be6-bf67-052ff111c06a', '除夜', '除夜', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["事關休戚已成空，萬里相思一夜中。","愁到曉雞聲絕後，又將顦顇見春風。"]', '["事关休戚已成空，万里相思一夜中。","愁到晓雞声絕後，又將顦顇见春风。"]', '诗', 'shi', '', NULL, '除夜 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5926bdfb-7c59-4ecf-9ec8-c6b6050227f1', '游魚', '游鱼', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["弄萍隈荇思夷猶，掉尾揚鬐逐慢流。","應怕碧巖巖下水，浮藤如線月如鉤。"]', '["弄萍隈荇思夷猶，掉尾揚鬐逐慢流。","應怕碧巖巖下水，浮藤如線月如鉤。"]', '诗', 'shi', '', NULL, '游魚 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a49e6c91-9d64-47a5-8cab-3060d1b3ed94', '鸚鵡', '鸚鵡', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["色白還應及雪衣，觜紅毛綠語仍奇。","年年鎖在金籠裏，何似隴山閑處飛。"]', '["色白還應及雪衣，觜紅毛綠語仍奇。","年年鎖在金籠裏，何似隴山闲处飞。"]', '诗', 'shi', '', NULL, '鸚鵡 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bfb96cb-6d18-434c-b802-1c34a49e12a6', '偶題二首 一', '偶題二首 一', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["近來靈鵲語何疎，獨凭欄干恨有殊。","一夜綠荷霜翦破，賺他秋雨不成珠。"]', '["近来靈鵲語何疎，独凭欄干恨有殊。","一夜綠荷霜翦破，賺他秋雨不成珠。"]', '诗', 'shi', '', NULL, '偶題二首 一 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a60d0ee3-d3f3-44ed-87c3-d1c60ce06cb5', '偶題二首 二', '偶題二首 二', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["水邊箕踞靜書空，欲解愁腸酒不濃。","可惜青天好雷雹，只能驅趂懶蛟龍。"]', '["水邊箕踞静书空，欲解愁腸酒不濃。","可惜青天好雷雹，只能驱趂懶蛟龙。"]', '诗', 'shi', '', NULL, '偶題二首 二 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ccab35-217d-4866-9c52-03449ddfe5b3', '惜花', '惜花', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["東風漸急夕陽斜，一樹夭桃數日花。","爲惜紅芳今夜裏，不知和月落誰家。"]', '["东风漸急夕陽斜，一樹夭桃數日花。","爲惜紅芳今夜裏，不知和月落誰家。"]', '诗', 'shi', '', NULL, '惜花 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59cf3dc1-497f-48e1-b4f9-f6acb2b1978e', '洞庭隐', '洞庭隐', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["高臥洞庭三十春，芰荷香裏獨垂綸。","莫嫌無事閑銷日，有事始憐無事人。"]', '["高臥洞庭三十春，芰荷香裏独垂綸。","莫嫌無事闲銷日，有事始怜無事人。"]', '诗', 'shi', '', NULL, '洞庭隐 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfc49d49-4140-4650-b28f-1de9792fdde7', '古劒池', '古劒池', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["秋水蓮花三四枝，我來慷慨步遲遲。","不決浮雲斬邪佞，直成龍去欲何爲。"]', '["秋水蓮花三四枝，我来慷慨步遲遲。","不決浮云斬邪佞，直成龙去欲何爲。"]', '诗', 'shi', '', NULL, '古劒池 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1bf254c-171e-4842-89f0-2f616b635cdb', '梅花', '梅花', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["枝枝倚檻照池冰，粉薄香殘恨不勝。","占得早芳何所利，與他霜雪助威稜。"]', '["枝枝倚檻照池冰，粉薄香殘恨不勝。","占得早芳何所利，與他霜雪助威稜。"]', '诗', 'shi', '', NULL, '梅花 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5acc0ee-6f84-4905-a0ec-791cf855d91a', '聞蟬', '闻蟬', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["綠槐陰裏一聲新，霧薄風輕力未勻。","莫道聞時總惆悵，有愁人有不愁人。"]', '["綠槐陰裏一声新，霧薄风轻力未勻。","莫道闻时總惆悵，有愁人有不愁人。"]', '诗', 'shi', '', NULL, '聞蟬 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c82ff83-d0a2-4c1d-bddf-4dc8ad9d88b8', '賣花謠', '賣花謠', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["紫豔紅苞價不同，匝街羅列起香風。","無言無語呈顏色，知落誰家池館中。"]', '["紫豔紅苞價不同，匝街羅列起香风。","無言無語呈顏色，知落誰家池館中。"]', '诗', 'shi', '', NULL, '賣花謠 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a8a81a-bc86-4fc2-96c9-57ea31235e29', '子規', '子規', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["月落空山聞數聲，此時孤館酒初醒。","投人語若似伊淚，口畔血流應始聽。"]', '["月落空山闻數声，此时孤館酒初醒。","投人語若似伊泪，口畔血流應始听。"]', '诗', 'shi', '', NULL, '子規 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6d55862-018e-4602-9f98-3ee3123133e4', '句', '句', 'c85e961b-4957-4137-ab10-5bb78d3d02fa', '唐', '["回眸綠水波初起，合掌白蓮花未開。"]', '["回眸綠水波初起，合掌白蓮花未开。"]', '诗', 'shi', '', NULL, '句 來鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd364eb0-a4f3-42ef-87b3-bc568f503e1a', '菊', '菊', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["籬下霜前偶得存，忍教遲晚避蘭蓀。","也銷造化無多力，未受陽和一點恩。","栽處不容依玉砌，要時還許上金尊。","陶潛歿後誰知己，露滴幽叢見淚痕。"]', '["籬下霜前偶得存，忍教遲晚避蘭蓀。","也銷造化無多力，未受陽和一点恩。","栽处不容依玉砌，要时還許上金尊。","陶潛歿後誰知己，露滴幽叢见泪痕。"]', '诗', 'shi', '', NULL, '菊 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f92b56-d7f3-4553-94f1-9a5570d20018', '風', '风', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["喜怒寒暄直不勻，終無形狀始無因。","能將塵土平欺客，愛把波瀾枉陷人。","飄樂遰香隨日在，綻花開柳逐年新。","深知造化由君力，試爲吹噓借與春。"]', '["喜怒寒暄直不勻，終無形狀始無因。","能將塵土平欺客，愛把波瀾枉陷人。","飄乐遰香隨日在，綻花开柳逐年新。","深知造化由君力，試爲吹噓借與春。"]', '诗', 'shi', '', NULL, '風 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e76e36ea-75e8-43b2-b8aa-2df21dcb6946', '月', '月', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["狡兔頑蟾死復生，度雲經漢澹還明。","夜長雖耐對君坐，年少不禁隨爾行。","玉桂影搖烏鵲動，金波寒注鬼神驚。","人間半被虛拋擲，唯向孤吟客有情。"]', '["狡兔頑蟾死复生，度云經漢澹還明。","夜长雖耐对君坐，年少不禁隨爾行。","玉桂影搖烏鵲动，金波寒注鬼神驚。","人间半被虛拋擲，唯向孤吟客有情。"]', '诗', 'shi', '', NULL, '月 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ff3436-20ac-4495-8d40-e24c315e50f5', '秋', '秋', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["傍雨衣風冷漸勻，更憑青女事精神。","來時將得幾多雁，到處愁他無限人。","能被綠楊深懊惱，謾偎黃菊送殷勤。","鄒家不用偏吹律，到底榮枯也自均。"]', '["傍雨衣风冷漸勻，更憑青女事精神。","来时將得幾多雁，到处愁他無限人。","能被綠楊深懊惱，謾偎黄菊送殷勤。","鄒家不用偏吹律，到底榮枯也自均。"]', '诗', 'shi', '', NULL, '秋 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de1ebe27-4eee-420b-8816-03337f734d46', '松', '松', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["地聳蒼龍勢抱雲，天教青共衆材分。","孤標百尺雲中見，長嘯一聲風裏聞。","桃李傍他真是佞，藤蘿攀爾亦非羣。","平生相愛應相識，誰道修篁勝此君。"]', '["地聳蒼龙勢抱云，天教青共衆材分。","孤標百尺云中见，长嘯一声风裏闻。","桃李傍他真是佞，藤蘿攀爾亦非羣。","平生相愛應相識，誰道修篁勝此君。"]', '诗', 'shi', '', NULL, '松 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fecd579f-9528-48be-86f6-6cc4f6fa4672', '讀漢史', '读漢史', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["四百年間反覆尋，漢家興替好沾襟。","每逢姦詐須挼手，真遇英雄始醒心。","王莽弄來曾半破，曹公將去便平沈。","當時虛受君恩者，謾向青編作鬼林。"]', '["四百年间反覆尋，漢家兴替好沾襟。","每逢姦詐須挼手，真遇英雄始醒心。","王莽弄来曾半破，曹公將去便平沈。","當时虛受君恩者，謾向青編作鬼林。"]', '诗', 'shi', '', NULL, '讀漢史 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('847539b6-7ea7-4aec-a7ff-7a32da3e8c6b', '上元懷古二首 一', '上元懷古二首 一', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["南朝天子愛風流，盡守江山不到頭。","總是戰爭收拾得，却因歌舞破除休。","堯行道德終無敵，秦把金湯可自由。","試問繁華何處有，雨苔煙草古城秋。"]', '["南朝天子愛风流，尽守江山不到头。","總是戰爭收拾得，却因歌舞破除休。","堯行道德終無敵，秦把金湯可自由。","試问繁华何处有，雨苔煙草古城秋。"]', '诗', 'shi', '', NULL, '上元懷古二首 一 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58070aff-c81d-4222-9ad2-8f8b6de6f0c9', '上元懷古二首 二', '上元懷古二首 二', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["爭帝圖王德盡衰，驟興馳霸亦何爲。","君臣都是一塲笑，家國共成千載悲。","排岸遠檣森似槊，落波殘照赫如旗。","今朝城上難迴首，不見樓船索戰時。"]', '["爭帝圖王德尽衰，驟兴驰霸亦何爲。","君臣都是一塲笑，家国共成千載悲。","排岸远檣森似槊，落波殘照赫如旗。","今朝城上难迴首，不见楼船索戰时。"]', '诗', 'shi', '', NULL, '上元懷古二首 二 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72f577cd-8974-4e77-810b-731a0c7d5e2c', '隋堤柳', '隋堤柳', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["曾傍龍舟拂翠華，至今凝恨倚天涯。","但經春色還秋色，不覺楊家是李家。","背日古陰從北朽，逐波疎影向南斜。","年年只有晴風便，遙爲雷塘送雪花。"]', '["曾傍龙舟拂翠华，至今凝恨倚天涯。","但經春色還秋色，不覺楊家是李家。","背日古陰從北朽，逐波疎影向南斜。","年年只有晴风便，遙爲雷塘送雪花。"]', '诗', 'shi', '', NULL, '隋堤柳 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6acd98af-efc6-49c4-b9b7-c8a010db993a', '蒲關西道中作', '蒲关西道中作', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["國東王氣凝蒲關，樓臺帖出晴空間。","紫煙橫捧大舜廟，黃河直打中條山。","地鎖咽喉千古壯，風傳歌吹萬家閑。","來來去去身依舊，未及潘年鬢已斑。"]', '["国东王氣凝蒲关，楼台帖出晴空间。","紫煙橫捧大舜廟，黄河直打中條山。","地鎖咽喉千古壯，风傳歌吹万家闲。","来来去去身依旧，未及潘年鬢已斑。"]', '诗', 'shi', '', NULL, '蒲關西道中作 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37714d4c-e101-40aa-bb53-e611b9453851', '道李秀才入軍', '道李秀才入軍', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["弱柳貞松一地栽，不因霜霰自難媒。","書生只是平時物，男子爭無亂世才。","鐵馬已隨紅斾去，同人猶著白衣來。","到頭功業須如此，莫爲初心首重回。"]', '["弱柳貞松一地栽，不因霜霰自难媒。","书生只是平时物，男子爭無亂世才。","鐵马已隨紅斾去，同人猶著白衣来。","到头功業須如此，莫爲初心首重回。"]', '诗', 'shi', '', NULL, '道李秀才入軍 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c1cdc78-f9ca-4e01-9c8e-3c1c074d277a', '送蘄州裴員外', '送蘄州裴員外', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["正作南宮第一人，蹔隨霓斾愴離羣。","曉從闕下辭天子，春向江頭待使君。","五馬尚迷青瑣路，雙魚猶惹翠蘭芬。","明朝無路尋歸處，禁樹參差隔紫雲。"]', '["正作南宮第一人，蹔隨霓斾愴離羣。","晓從闕下辞天子，春向江头待使君。","五马尚迷青瑣路，雙鱼猶惹翠蘭芬。","明朝無路尋归处，禁樹參差隔紫云。"]', '诗', 'shi', '', NULL, '送蘄州裴員外 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e56b3d4-d709-41ea-a8b6-a1d28fb296ba', '代孔明哭先主', '代孔明哭先主', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["憶昔南陽顧草廬，便乘雷電捧乘輿。","酌量諸夏須平取，期刻羣雄待遍鋤。","南面未能成帝業，西陵那忍送宮車。","九疑山下頻惆悵，曾許微臣水共魚。"]', '["憶昔南陽顧草廬，便乘雷電捧乘輿。","酌量諸夏須平取，期刻羣雄待遍鋤。","南面未能成帝業，西陵那忍送宮车。","九疑山下頻惆悵，曾許微臣水共鱼。"]', '诗', 'shi', '', NULL, '代孔明哭先主 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d938bf-b466-4524-a1f2-9ce252ccc5cd', '送職方王郎中吏部劉員外自太原鄭相公幕繼奉徵書歸省署', '送職方王郎中吏部劉員外自太原鄭相公幕繼奉徵书归省署', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["雙鳳銜書次第飛，玉皇催促列仙歸。","雲開日月臨青瑣，風卷煙霞上紫微。","蓮影一時空儉府，蘭香同處撲堯衣。","此生長掃朱門者，每向人間夢粉闈。"]', '["雙鳳銜书次第飞，玉皇催促列仙归。","云开日月臨青瑣，风卷煙霞上紫微。","蓮影一时空儉府，蘭香同处撲堯衣。","此生长掃朱门者，每向人间梦粉闈。"]', '诗', 'shi', '', NULL, '送職方王郎中吏部劉員外自太原鄭相公幕繼奉徵書歸省署 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3da4e09-5915-4ef6-b234-4aab0e619ced', '寒食二首 一', '寒食二首 一', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["柳帶東風一向斜，春陰澹澹蔽人家。","有時三點兩點雨，到處十枝五枝花。","萬井樓臺疑繡畫，九原珠翠似煙霞。","年年今日誰相問，獨臥長安泣歲華。"]', '["柳带东风一向斜，春陰澹澹蔽人家。","有时三点兩点雨，到处十枝五枝花。","万井楼台疑繡畫，九原珠翠似煙霞。","年年今日誰相问，独臥长安泣歲华。"]', '诗', 'shi', '', NULL, '寒食二首 一 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc04b5a5-f7ea-4040-8872-19f2d1912c11', '寒食二首 二', '寒食二首 二', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["風煙放蕩花披猖，鞦韆女兒飛短牆。","繡袍馳馬拾遺翠，錦袖鬬雞喧廣塲。","天地氣和融霽色，池臺日暖燒春光。","自憐塵土無他事，空脫荷衣泥醉鄉。"]', '["风煙放蕩花披猖，鞦韆女兒飞短牆。","繡袍驰马拾遺翠，錦袖鬬雞喧廣塲。","天地氣和融霽色，池台日暖燒春光。","自怜塵土無他事，空脫荷衣泥醉乡。"]', '诗', 'shi', '', NULL, '寒食二首 二 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98c46436-ea84-44e4-8521-825a69e01082', '又代孔明哭先主', '又代孔明哭先主', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["鯨鬣翻騰四海波，始將天意用干戈。","盡驅神鬼隨鞭策，全罩英雄入網羅。","提劒尚殘吳郡國，垂衣猶欠魏山河。","鼎湖無路追仙駕，空使羣臣泣血多。"]', '["鯨鬣翻腾四海波，始將天意用干戈。","尽驱神鬼隨鞭策，全罩英雄入網羅。","提劒尚殘吳郡国，垂衣猶欠魏山河。","鼎湖無路追仙駕，空使羣臣泣血多。"]', '诗', 'shi', '', NULL, '又代孔明哭先主 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3ae9671-6997-446b-96dc-3fd66939e152', '貧女', '貧女', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["平生不識繡衣裳，閑把荆釵亦自傷。","鏡裏只應諳素貌，人間多自信紅妝。","當年未嫁還憂老，終日求媒即道狂。","兩意定知無說處，暗垂珠淚濕蠶筐。"]', '["平生不識繡衣裳，闲把荆釵亦自傷。","镜裏只應諳素貌，人间多自信紅妝。","當年未嫁還憂老，終日求媒即道狂。","兩意定知無说处，暗垂珠泪濕蠶筐。"]', '诗', 'shi', '', NULL, '貧女 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('481de596-c60e-45d1-99d8-b715f46d5bb7', '寓懷', '寓懷', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["萬古交馳一片塵，思量名利孰如身。","長疑好事皆虛事，却恐閑人是貴人。","老逐少來終不放，辱隨榮後直須勻。","勸君不用誇頭角，夢裏輸贏總未真。"]', '["万古交驰一片塵，思量名利孰如身。","长疑好事皆虛事，却恐闲人是貴人。","老逐少来終不放，辱隨榮後直須勻。","勸君不用誇头角，梦裏輸贏總未真。"]', '诗', 'shi', '', NULL, '寓懷 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7835f216-6e86-43e8-b122-eac142063bad', '蜀中寓懷', '蜀中寓懷', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["千里煙霞錦水頭，五丁開得也風流。","春裝寶闕重重樹，日照仙州萬萬樓。","蛙似公孫雖不守，龍如諸葛亦須休。","此中無限英雄鬼，應對江山各自羞。"]', '["千里煙霞錦水头，五丁开得也风流。","春裝寶闕重重樹，日照仙州万万楼。","蛙似公孫雖不守，龙如諸葛亦須休。","此中無限英雄鬼，應对江山各自羞。"]', '诗', 'shi', '', NULL, '蜀中寓懷 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77f434c1-8374-45ef-a4b7-aa8ab210694b', '下第臥疾盧員外召遊曲江', '下第臥疾盧員外召游曲江', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["眼前何事不傷神，忍向江頭更弄春。","桂樹既能欺賤子，杏花爭肯採閑人。","麻衣未掉渾身雪，皁蓋難遮滿面塵。","珍重列星相借問，嵇康慵病也天真。"]', '["眼前何事不傷神，忍向江头更弄春。","桂樹既能欺賤子，杏花爭肯採闲人。","麻衣未掉渾身雪，皁蓋难遮满面塵。","珍重列星相借问，嵇康慵病也天真。"]', '诗', 'shi', '', NULL, '下第臥疾盧員外召遊曲江 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('838782aa-7340-4de5-bec0-46ecc67ecd34', '司天臺', '司天台', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["拂雲朱檻捧昭回，靜對銅渾水鏡開。","太史只知頻奏瑞，蒼生無計可防災。","景公進德星曾退，漢帝推誠日爲迴。","何事曠官全不語，好天良月鎖高臺。"]', '["拂云朱檻捧昭回，静对銅渾水镜开。","太史只知頻奏瑞，蒼生無計可防災。","景公進德星曾退，漢帝推誠日爲迴。","何事曠官全不語，好天良月鎖高台。"]', '诗', 'shi', '', NULL, '司天臺 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c07f4a1e-aea8-45dc-b043-ac4ac52910dd', '落花', '落花', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["落拓東風不藉春，吹開吹謝兩何因。","當時曾見笑筵主，今日自爲行路塵。","顏色却還天上女，馨香留與世間人。","明年寒食重相見，零淚無端又滿巾。"]', '["落拓东风不藉春，吹开吹謝兩何因。","當时曾见笑筵主，今日自爲行路塵。","顏色却還天上女，馨香留與世间人。","明年寒食重相见，零泪無端又满巾。"]', '诗', 'shi', '', NULL, '落花 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e50c8203-889f-4852-883e-eceb9fd2486c', '赴舉別所知', '赴舉別所知', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["腰劒囊書出戶遲，壯心奇命兩相疑。","麻衣盡舉一雙手，桂樹只生三兩枝。","黃祖不憐鸚鵡客，誌公偏賞麒麟兒。","叔牙憂我應相痛，回首天涯寄所思。"]', '["腰劒囊书出戶遲，壯心奇命兩相疑。","麻衣尽舉一雙手，桂樹只生三兩枝。","黄祖不怜鸚鵡客，誌公偏賞麒麟兒。","叔牙憂我應相痛，回首天涯寄所思。"]', '诗', 'shi', '', NULL, '赴舉別所知 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a116199a-f983-41cb-be0b-5ffaaf022cd8', '賀邢州盧員外', '賀邢州盧員外', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["紫泥飛詔下金鑾，列象分明世仰觀。","北省諫書藏舊草，南宮郎署握新蘭。","春歸鳳沼恩波暖，曉入鴛行瑞氣寒。","偏是此生棲息者，滿衣零淚一時乾。"]', '["紫泥飞詔下金鑾，列象分明世仰观。","北省諫书藏旧草，南宮郎署握新蘭。","春归鳳沼恩波暖，晓入鴛行瑞氣寒。","偏是此生棲息者，满衣零泪一时乾。"]', '诗', 'shi', '', NULL, '賀邢州盧員外 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1691957b-b9b7-442f-b76f-481dbf4b834e', '方干隱居', '方干隐居', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["咬咬嘎嘎水禽聲，露洗松陰滿院清。","溪畔印沙多鶴跡，檻前題竹有僧名。","問人遠岫千重意，對客閑雲一片情。","早晚塵埃得休去，且將書劒事先生。"]', '["咬咬嘎嘎水禽声，露洗松陰满院清。","溪畔印沙多鹤跡，檻前題竹有僧名。","问人远岫千重意，对客闲云一片情。","早晚塵埃得休去，且將书劒事先生。"]', '诗', 'shi', '', NULL, '方干隱居 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b663d1-ec19-4999-be77-f34181f81a1f', '早春微雨', '早春微雨', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["怪來鶯蝶似凝愁，不覺看花蹔濕頭。","疎影未藏千里樹，遠陰微翳萬家樓。","青羅舞袖紛紛轉，紅臉啼珠旋旋收。","歲旱且須教濟物，爲霖何事愛風流。"]', '["怪来鶯蝶似凝愁，不覺看花蹔濕头。","疎影未藏千里樹，远陰微翳万家楼。","青羅舞袖紛紛轉，紅臉啼珠旋旋收。","歲旱且須教濟物，爲霖何事愛风流。"]', '诗', 'shi', '', NULL, '早春微雨 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30b7423f-6a09-4427-9301-5cf14720119b', '謁翰林劉學士不遇', '謁翰林劉学士不遇', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["夢繞清華宴地深，洞宮橫鎖曉沈沈。","鵬飛碧海終難見，鶴入青霄豈易尋。","六尺羇魂迷定止，兩行愁血謝知音。","平生只耻凌風翼，隨得鳴珂上禁林。"]', '["梦繞清华宴地深，洞宮橫鎖晓沈沈。","鵬飞碧海終难见，鹤入青霄豈易尋。","六尺羇魂迷定止，兩行愁血謝知音。","平生只耻凌风翼，隨得鳴珂上禁林。"]', '诗', 'shi', '', NULL, '謁翰林劉學士不遇 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed68218-7826-46a3-a432-418b00e4d15a', '答劉書記見贈', '答劉书記见贈', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["吟近秋光思不窮，酷探騷雅愧無功。","茫然心苦千篇拙，瞑坐神凝萬象空。","月上開襟當北戶，竹邊回首揖西風。","知音頻有新詩贈，白雪紛紛落郢中。"]', '["吟近秋光思不窮，酷探騷雅愧無功。","茫然心苦千篇拙，瞑坐神凝万象空。","月上开襟當北戶，竹邊回首揖西风。","知音頻有新诗贈，白雪紛紛落郢中。"]', '诗', 'shi', '', NULL, '答劉書記見贈 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55069a74-8930-425c-8633-06cd5646da04', '賀友人及第', '賀友人及第', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["得水蛟龍失水魚，此心相對兩何如。","敢辭今日須行卷，猶喜他年待薦書。","松桂也應情未改，萍蓬爭奈迹還疎。","春風不見尋花伴，遙向青雲泥子虛。"]', '["得水蛟龙失水鱼，此心相对兩何如。","敢辞今日須行卷，猶喜他年待薦书。","松桂也應情未改，萍蓬爭奈迹還疎。","春风不见尋花伴，遙向青云泥子虛。"]', '诗', 'shi', '', NULL, '賀友人及第 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dad3bf10-ae4d-4d73-b0d0-e859b928491a', '雨後過華嶽廟', '雨後過华嶽廟', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["華山黑影霄崔嵬，金天□□門未開。","雨淋鬼火滅不滅，風送神香來不來。","牆外素錢飄似雪，殿前陰栢吼如雷。","知君暗宰人間事，休把蒼生夢裏裁。"]', '["华山黑影霄崔嵬，金天□□门未开。","雨淋鬼火滅不滅，风送神香来不来。","牆外素錢飄似雪，殿前陰栢吼如雷。","知君暗宰人间事，休把蒼生梦裏裁。"]', '诗', 'shi', '', NULL, '雨後過華嶽廟 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('786e21cb-3d73-44a2-adf4-fb90bfa30160', '贈彈琴李處士', '贈彈琴李处士', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["情知此事少知音，自是先生枉用心。","世上幾時曾好古，人前何必更沾襟。","致身不似笙竽巧，悅耳寧如鄭衛淫。","三尺焦桐七條線，子期師曠兩沈沈。"]', '["情知此事少知音，自是先生枉用心。","世上幾时曾好古，人前何必更沾襟。","致身不似笙竽巧，悅耳寧如鄭衛淫。","三尺焦桐七條線，子期師曠兩沈沈。"]', '诗', 'shi', '', NULL, '贈彈琴李處士 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc6627b1-698f-44d2-9145-8f57af01a649', '劉員外寄移菊', '劉員外寄移菊', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["秋來緣樹復緣牆，怕共平蕪一例荒。","顏色不能隨地變，風流唯解逐人香。","煙含細葉交加碧，露拆寒英次第黃。","深謝栽培與知賞，但慙終歲待重陽。"]', '["秋来緣樹复緣牆，怕共平蕪一例荒。","顏色不能隨地变，风流唯解逐人香。","煙含細葉交加碧，露拆寒英次第黄。","深謝栽培與知賞，但慙終歲待重陽。"]', '诗', 'shi', '', NULL, '劉員外寄移菊 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3f10660-9859-42bd-8c8e-b77308682c04', '南山', '南山', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["鈍碧頑青幾萬秋，直無天地始應休。","莫嫌塵土佯遮面，能向樓臺強出頭。","霽色陡添千尺翠，夕陽閑放一堆愁。","假繞不是神仙骨，終抱琴書向此遊。"]', '["鈍碧頑青幾万秋，直無天地始應休。","莫嫌塵土佯遮面，能向楼台強出头。","霽色陡添千尺翠，夕陽闲放一堆愁。","假繞不是神仙骨，終抱琴书向此游。"]', '诗', 'shi', '', NULL, '南山 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6ef35c-9fb8-4aa9-81d3-ecca44e1e1b9', '山中覽劉書記新詩', '山中覽劉书記新诗', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["記室新詩相寄我，藹然清絕更無過。","溪風滿袖吹騷雅，巖瀑無時滴薜蘿。","雲外山高寒色重，雪中松苦夜聲多。","靜酬嘉唱對幽景，蒼鶴羸棲古木柯。"]', '["記室新诗相寄我，藹然清絕更無過。","溪风满袖吹騷雅，巖瀑無时滴薜蘿。","云外山高寒色重，雪中松苦夜声多。","静酬嘉唱对幽景，蒼鹤羸棲古木柯。"]', '诗', 'shi', '', NULL, '山中覽劉書記新詩 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b184397-9da2-44e7-be9b-b73373769e30', '早秋山中作', '早秋山中作', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["榮枯無路入千峯，肥遯誰諧此志同。","司寇亦曾遭魯黜，步兵何事哭途窮。","檜松瘦健滴秋露，戶牖虛明生晚風。","山思更清人影絕，隴雲飛入草堂中。"]', '["榮枯無路入千峯，肥遯誰諧此志同。","司寇亦曾遭魯黜，步兵何事哭途窮。","檜松瘦健滴秋露，戶牖虛明生晚风。","山思更清人影絕，隴云飞入草堂中。"]', '诗', 'shi', '', NULL, '早秋山中作 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae50bb5-5d5a-4a3d-a5b3-f9f9b5321b75', '賦得寒月寄齊已', '賦得寒月寄齊已', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["松下清風吹我襟，上方鐘磬夜沉沉。","已知廬嶽塵埃絕，更憶寒山雪月深。","高謝萬緣消祖意，朗吟千首亦師心。","豈知名出徧諸夏，石上棲禪竹影侵。"]', '["松下清风吹我襟，上方鐘磬夜沉沉。","已知廬嶽塵埃絕，更憶寒山雪月深。","高謝万緣消祖意，朗吟千首亦師心。","豈知名出徧諸夏，石上棲禪竹影侵。"]', '诗', 'shi', '', NULL, '賦得寒月寄齊已 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a81130f-f5d8-42cb-aa0e-aed0adec9531', '曲江二首 一', '曲江二首 一', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["南山低對紫雲樓，翠影紅陰瑞氣浮。","一種是春長富貴，大都爲水也風流。","爭攀柳帶千千手，間插花枝萬萬頭。","獨向江邊最惆悵，滿衣塵土避王侯。"]', '["南山低对紫云楼，翠影紅陰瑞氣浮。","一種是春长富貴，大都爲水也风流。","爭攀柳带千千手，间插花枝万万头。","独向江邊最惆悵，满衣塵土避王侯。"]', '诗', 'shi', '', NULL, '曲江二首 一 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e40e7f-b8cd-4b1a-81e5-468896d7c830', '曲江二首 二', '曲江二首 二', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["江色沈天萬草齊，暖煙晴靄自相迷。","蜂憐杏蕋細香落，鶯墜柳條濃翠低。","千隊國娥輕似雪，一羣公子醉如泥。","斜陽怪得長安動，陌上分飛萬馬蹄。"]', '["江色沈天万草齊，暖煙晴靄自相迷。","蜂怜杏蕋細香落，鶯墜柳條濃翠低。","千隊国娥轻似雪，一羣公子醉如泥。","斜陽怪得长安动，陌上分飞万马蹄。"]', '诗', 'shi', '', NULL, '曲江二首 二 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c06f015b-4e31-403c-943c-741b9e61fd16', '遷居清谿和劉書記見示', '遷居清谿和劉书記见示', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["擔錫歸來竹繞谿，過津曾笑魯儒迷。","端居味道塵勞息，扣寂眠雲心境齊。","還似村家無寵祿，時將隣叟話幽棲。","山衣毳爛唯添野，石井源清不貯泥。","祖意豈從年臘得，松枝肯爲雪霜低。","晚天吟望秋光重，雨陣橫空蔽斷霓。"]', '["擔錫归来竹繞谿，過津曾笑魯儒迷。","端居味道塵勞息，扣寂眠云心境齊。","還似村家無寵祿，时將隣叟話幽棲。","山衣毳爛唯添野，石井源清不貯泥。","祖意豈從年臘得，松枝肯爲雪霜低。","晚天吟望秋光重，雨陣橫空蔽斷霓。"]', '诗', 'shi', '', NULL, '遷居清谿和劉書記見示 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1cbca71-a4ac-432c-9a35-72ce1d9e781f', '陰地關崇徽公主手跡', '陰地关崇徽公主手跡', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["一拓纖痕更不收，翠微蒼蘚幾經秋。","誰陳帝子和番策，我是男兒爲國羞。","寒雨洗來香已盡，澹煙籠著恨長留。","可憐汾水知人意，旁與吞聲未忍休。"]', '["一拓纖痕更不收，翠微蒼蘚幾經秋。","誰陳帝子和番策，我是男兒爲国羞。","寒雨洗来香已尽，澹煙籠著恨长留。","可怜汾水知人意，旁與吞声未忍休。"]', '诗', 'shi', '', NULL, '陰地關崇徽公主手跡 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae339d2-44f7-45d5-8a12-e26198f3a9c1', '題李員外廳', '題李員外廳', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["石砌蛩吟響，草堂人語稀。","道孤思絕唱，年長漸知非。","名利終成患，煙霞亦可依。","高丘松蓋古，閑地藥苗肥。","猨鳥啼嘉景，牛羊傍晚暉。","幽棲還自得，清嘯坐忘機。","愛彼人深處，白雲相伴歸。"]', '["石砌蛩吟响，草堂人語稀。","道孤思絕唱，年长漸知非。","名利終成患，煙霞亦可依。","高丘松蓋古，闲地藥苗肥。","猨鸟啼嘉景，牛羊傍晚暉。","幽棲還自得，清嘯坐忘機。","愛彼人深处，白云相伴归。"]', '诗', 'shi', '', NULL, '題李員外廳 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1ca04a-ec8d-4414-8fd3-5f5caf642d02', '山中寄梁判官', '山中寄梁判官', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["歸臥東林計偶諧，柴門深向翠微開。","更無塵事心頭起，還有詩情象外來。","康樂公應頻結社，寒山子亦患多才。","星郎雅是道中侶，六藝拘牽在隗臺。"]', '["归臥东林計偶諧，柴门深向翠微开。","更無塵事心头起，還有诗情象外来。","康乐公應頻結社，寒山子亦患多才。","星郎雅是道中侶，六藝拘牽在隗台。"]', '诗', 'shi', '', NULL, '山中寄梁判官 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a285c45-d028-48d9-b1b8-d3a130c36d91', '禪林寺作寄劉書記', '禪林寺作寄劉书記', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["坐近松風骨自寒，茅齋直拶白雲邊。","玄關不閉何人到，此事誰論在佛先。","天竺老師留一句，曹溪行者答全篇。","今朝林下忘言說，強把新詩寄謫仙。"]', '["坐近松风骨自寒，茅斋直拶白云邊。","玄关不閉何人到，此事誰論在佛先。","天竺老師留一句，曹溪行者答全篇。","今朝林下忘言说，強把新诗寄謫仙。"]', '诗', 'shi', '', NULL, '禪林寺作寄劉書記 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7923ead0-313e-4dec-b8d2-885d0f57afb1', '山中病後作', '山中病後作', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["臥病厭厭三伏盡，商飆初自水邊來。","高峯枯槁骨偏峭，野樹扶疎葉未摧。","時序追牽從鬢改，蟬聲酸急是誰催。","雲門不閉全無事，心外沈然一聚灰。"]', '["臥病厭厭三伏尽，商飆初自水邊来。","高峯枯槁骨偏峭，野樹扶疎葉未摧。","时序追牽從鬢改，蟬声酸急是誰催。","云门不閉全無事，心外沈然一聚灰。"]', '诗', 'shi', '', NULL, '山中病後作 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f4d7d31-3aba-4742-8b39-b2c3d406fd3a', '寄衛別駕', '寄衛別駕', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["曉屐歸來嶽寺深，嘗思道侶會東林。","昏沈天竺看經眼，蕭索淨名老病心。","雲蓋數重橫隴首，苔花千點遍松陰。","知君超達悟空旨，三徑閑行抱素琴。"]', '["晓屐归来嶽寺深，嘗思道侶會东林。","昏沈天竺看經眼，蕭索淨名老病心。","云蓋數重橫隴首，苔花千点遍松陰。","知君超達悟空旨，三徑闲行抱素琴。"]', '诗', 'shi', '', NULL, '寄衛別駕 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('504c444d-2e7a-4508-9a08-ac8976f31f76', '遣懷', '遣懷', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["長松埋澗底，鬱鬱未出原。","孤雲飛隴首，高潔不可攀。","古道貴拙直，時事不足言。","莫飲盜泉水，無爲天下先。","智者與愚者，盡歸北邙山。","唯有東流水，年光不蹔閑。"]', '["长松埋澗底，鬱鬱未出原。","孤云飞隴首，高潔不可攀。","古道貴拙直，时事不足言。","莫饮盜泉水，無爲天下先。","智者與愚者，尽归北邙山。","唯有东流水，年光不蹔闲。"]', '诗', 'shi', '', NULL, '遣懷 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('744f543e-2b43-4caf-a1d5-dfd97c31cdaa', '酬劉書記一二知己見寄', '酬劉书記一二知己见寄', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["見說金臺客，相逢秪論詩。","坐來殘暑退，吟許野僧知。","自喜幽棲僻，唯慙道義虧。","身閑偏好古，句冷不求奇。","晦跡全無累，安貧自得宜。","同人終念我，蓮社有歸期。"]', '["见说金台客，相逢秪論诗。","坐来殘暑退，吟許野僧知。","自喜幽棲僻，唯慙道義虧。","身闲偏好古，句冷不求奇。","晦跡全無累，安貧自得宜。","同人終念我，蓮社有归期。"]', '诗', 'shi', '', NULL, '酬劉書記一二知己見寄 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00746ae5-6e74-4285-954e-536bc25747ae', '山中依韻答劉書記見贈', '山中依韻答劉书記见贈', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["幽居少人事，三徑草不開。","隱几虛室靜，閑雲入坐來。","至道非內外，詎言才不才。","寶月當秋空，高潔無纖埃。","心滅百慮減，詩成萬象回。","亦有吾廬在，寂寞舊山隈。","從容未歸去，滿地生青苔。","謝公寄我詩，清奇不可陪。","白雲飛不盡，碧雲欲成堆。","驚風出地戶，虩虩似震雷。","吟哦山嶽動，令人心膽摧。","思君覽章句，還復如望梅。","慷慨追古意，曠望登高臺。","何當陶淵明，遠師勸傾盃。","流年將老來，華髪自相催。","野寺連屏障，左右相裴回。"]', '["幽居少人事，三徑草不开。","隐几虛室静，闲云入坐来。","至道非內外，詎言才不才。","寶月當秋空，高潔無纖埃。","心滅百慮減，诗成万象回。","亦有吾廬在，寂寞旧山隈。","從容未归去，满地生青苔。","謝公寄我诗，清奇不可陪。","白云飞不尽，碧云欲成堆。","驚风出地戶，虩虩似震雷。","吟哦山嶽动，令人心膽摧。","思君覽章句，還复如望梅。","慷慨追古意，曠望登高台。","何當陶淵明，远師勸傾盃。","流年將老来，华髪自相催。","野寺連屏障，左右相裴回。"]', '诗', 'shi', '', NULL, '山中依韻答劉書記見贈 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c42920-e893-4820-a655-cb1622d80487', '山中答劉書記寓懷', '山中答劉书記寓懷', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["貴門多冠冕，日與榮辱並。","山中有獨夫，笑傲出衰盛。","正直任天真，鬼神亦相敬。","之子賁丘園，戶牖松蘿暎。","骨將槁木齊，心同止水淨。","筆頭指金波，座上橫玉柄。","芙蓉出秋渚，繡段流清詠。","高古不稱時，沈默豈相競。","窮搜萬籟息，危坐千峯靜。","林僧繼嘉唱，風前亦爲幸。"]', '["貴门多冠冕，日與榮辱並。","山中有独夫，笑傲出衰盛。","正直任天真，鬼神亦相敬。","之子賁丘园，戶牖松蘿暎。","骨將槁木齊，心同止水淨。","笔头指金波，座上橫玉柄。","芙蓉出秋渚，繡段流清詠。","高古不稱时，沈默豈相競。","窮搜万籟息，危坐千峯静。","林僧繼嘉唱，风前亦爲幸。"]', '诗', 'shi', '', NULL, '山中答劉書記寓懷 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf93b309-99d2-4903-831a-948b41237045', '項羽廟', '項羽廟', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["爲虜爲王盡偶然，有何羞見漢江船。","停分天下猶嫌少，可要行人贈紙錢。"]', '["爲虜爲王尽偶然，有何羞见漢江船。","停分天下猶嫌少，可要行人贈紙錢。"]', '诗', 'shi', '', NULL, '項羽廟 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e45348-a3b1-4cf3-ab85-b4bd1ed9afed', '春日商山道中作', '春日商山道中作', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["一逕春光裏，揚鞭入翠微。","風來花落帽，雲過雨沾衣。","谷鳥銜枝去，巴人負笈歸。","殘陽更惆悵，前路客亭稀。"]', '["一逕春光裏，揚鞭入翠微。","风来花落帽，云過雨沾衣。","谷鸟銜枝去，巴人負笈归。","殘陽更惆悵，前路客亭稀。"]', '诗', 'shi', '', NULL, '春日商山道中作 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('badbc3a4-f625-4d5f-a4d9-e5294f3ea568', '古石硯', '古石硯', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["追琢他山石，方圓一勺深。","抱真唯守墨，求用每虛心。","波浪因文起，塵埃爲廢侵。","憑君更研究，何啻直千金。"]', '["追琢他山石，方圓一勺深。","抱真唯守墨，求用每虛心。","波浪因文起，塵埃爲廢侵。","憑君更研究，何啻直千金。"]', '诗', 'shi', '', NULL, '古石硯 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f9fde68-8cba-4237-a2f7-6f1a5895fa17', '惜花', '惜花', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["未會春風意，開君又落君。","一年今爛熳，幾日便繽紛。","別豔那堪賞，餘香不忍聞。","尊前恨無語，應解作朝雲。"]', '["未會春风意，开君又落君。","一年今爛熳，幾日便繽紛。","別豔那堪賞，餘香不忍闻。","尊前恨無語，應解作朝云。"]', '诗', 'shi', '', NULL, '惜花 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409a9707-4097-4323-8693-49ee24a47bd0', '別楊秀才', '別楊秀才', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["因亂與君別，相逢悲且驚。","開襟魂自慰，拭淚眼空明。","故國已無業，舊交多不生。","如何又分袂，難話別離情。"]', '["因亂與君別，相逢悲且驚。","开襟魂自慰，拭泪眼空明。","故国已無業，旧交多不生。","如何又分袂，难話別離情。"]', '诗', 'shi', '', NULL, '別楊秀才 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2429d5e-f507-4138-b954-911a00a831a1', '自歎拙', '自歎拙', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["自憐心計拙，欲語更悲辛。","世亂僮欺主，年衰鬼弄人。","鏡中顏欲老，江上業長貧。","不是劉公樂，何由變此身。"]', '["自怜心計拙，欲語更悲辛。","世亂僮欺主，年衰鬼弄人。","镜中顏欲老，江上業长貧。","不是劉公乐，何由变此身。"]', '诗', 'shi', '', NULL, '自歎拙 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a224e8b-7580-49b4-9906-caef628be9c0', '亂後途中', '亂後途中', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["亂離尋故園，朝市不如村。","慟哭翻無淚，顛狂覺少魂。","諸侯貪割據，羣盜恣幷吞。","爲問登壇者，何年答漢恩。"]', '["亂離尋故园，朝市不如村。","慟哭翻無泪，顛狂覺少魂。","諸侯貪割據，羣盜恣幷吞。","爲问登壇者，何年答漢恩。"]', '诗', 'shi', '', NULL, '亂後途中 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('031feb59-e047-4527-bf66-810a5008bc19', '燕', '燕', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["每歲同辛苦，看人似有情。","亂飛春得意，幽語夜聞聲。","整羽莊姜恨，迴身漢后輕。","豪家足金彈，不用污雕楹。"]', '["每歲同辛苦，看人似有情。","亂飞春得意，幽語夜闻声。","整羽莊姜恨，迴身漢后轻。","豪家足金彈，不用污雕楹。"]', '诗', 'shi', '', NULL, '燕 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1d40d1e-a200-4cc8-b119-5189cca2dfae', '題慈雲寺僧院', '題慈云寺僧院', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["帝城深處寺，棲殿壓秋江。","紅葉去寒樹，碧峯來曉窗。","煙霞生淨土，苔蘚上高幢。","欲問吾師語，心猨不肯降。"]', '["帝城深处寺，棲殿壓秋江。","紅葉去寒樹，碧峯来晓窗。","煙霞生淨土，苔蘚上高幢。","欲问吾師語，心猨不肯降。"]', '诗', 'shi', '', NULL, '題慈雲寺僧院 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c846db54-7fed-417a-b0d9-b35c304b3933', '聞子規', '闻子規', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["冤禽名杜宇，此事更難知。","昔帝一時恨，後人千古悲。","斷腸思故國，啼血濺芳枝。","況是天涯客，那堪□□眉。"]', '["冤禽名杜宇，此事更难知。","昔帝一时恨，後人千古悲。","斷腸思故国，啼血濺芳枝。","況是天涯客，那堪□□眉。"]', '诗', 'shi', '', NULL, '聞子規 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b050f88-e4c9-4cba-aa14-1735bf5e4b3a', '送劉將軍入關討賊', '送劉將軍入关討賊', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["世人多恃武，何者是真雄。","欲滅黃巾賊，須憑黑矟公。","指星憂國計，望氣識天風。","明日凌雲上，期君第一功。"]', '["世人多恃武，何者是真雄。","欲滅黄巾賊，須憑黑矟公。","指星憂国計，望氣識天风。","明日凌云上，期君第一功。"]', '诗', 'shi', '', NULL, '送劉將軍入關討賊 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a446816-cd3b-4dda-a1be-12796dc43592', '陪鄭先輩華山羅谷訪張隱者', '陪鄭先輩华山羅谷訪張隐者', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["白雲閑洞口，飛蓋入嵐光。","好鳥共人語，異花迎客香。","谷風聞鼓吹，苔石見文章。","不是陪仙侶，無因訪阮郎。"]', '["白云闲洞口，飞蓋入嵐光。","好鸟共人語，異花迎客香。","谷风闻鼓吹，苔石见文章。","不是陪仙侶，無因訪阮郎。"]', '诗', 'shi', '', NULL, '陪鄭先輩華山羅谷訪張隱者 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca70f842-d61e-4d41-ab95-12fa47fcc816', '兵後尋邊三首 一', '兵後尋邊三首 一', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["千里煙砂盡日昏，戰餘燒罷閉重門。","新成劒戟皆農器，舊著衣裳盡血痕。","卷地朔風吹白骨，柱天青氣泣幽魂。","自憐長策無人問，羞戴儒冠傍塞垣。"]', '["千里煙砂尽日昏，戰餘燒罷閉重门。","新成劒戟皆農器，旧著衣裳尽血痕。","卷地朔风吹白骨，柱天青氣泣幽魂。","自怜长策無人问，羞戴儒冠傍塞垣。"]', '诗', 'shi', '', NULL, '兵後尋邊三首 一 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf73cabf-0d1b-4231-b0b4-ab22e1c96135', '兵後尋邊三首 二', '兵後尋邊三首 二', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["旗頭指處見黃埃，萬馬橫馳鶻翅迴。","劒戟遠腥凝血在，山河先暗陣雲來。","角聲惡殺悲於哭，鼓勢爭強怒若雷。","日暮却登寒壘望，飽鴟清嘯伏屍堆。"]', '["旗头指处见黄埃，万马橫驰鶻翅迴。","劒戟远腥凝血在，山河先暗陣云来。","角声惡殺悲於哭，鼓勢爭強怒若雷。","日暮却登寒壘望，飽鴟清嘯伏屍堆。"]', '诗', 'shi', '', NULL, '兵後尋邊三首 二 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fa8a2f7-2c17-4aa2-8801-363316ec8247', '兵後尋邊三首 三', '兵後尋邊三首 三', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["風怒邊沙迸鐵衣，胡兒胡馬正驕肥。","將軍對陣誰教入，戰士辭營不道歸。","新血濺紅黏蔓草，舊骸堆白映寒暉。","胸中縱有銷兵術，欲向何門說是非。"]', '["风怒邊沙迸鐵衣，胡兒胡马正驕肥。","將軍对陣誰教入，戰士辞營不道归。","新血濺紅黏蔓草，旧骸堆白映寒暉。","胸中縱有銷兵術，欲向何门说是非。"]', '诗', 'shi', '', NULL, '兵後尋邊三首 三 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6967cf9-7689-4b9a-b18d-81a39068b6ef', '滄浪峽', '滄浪峽', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["走轂飛蹄過此傍，幾人留意問滄浪。","煙波莫笑趨名客，爲愛朝宗日夜忙。"]', '["走轂飞蹄過此傍，幾人留意问滄浪。","煙波莫笑趨名客，爲愛朝宗日夜忙。"]', '诗', 'shi', '', NULL, '滄浪峽 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa0be53e-c35f-4bcf-9963-a1a2ce76fa94', '公子家二首 一', '公子家二首 一', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["曾是皇家幾世侯，入雲高第照神州。","柳遮門戶橫金鎖，花擁弦歌咽畫樓。","錦袖妒姬爭巧笑，玉銜[驕]馬索閑遊。","麻衣酷獻平生業，醉倚春風不點頭。"]', '["曾是皇家幾世侯，入云高第照神州。","柳遮门戶橫金鎖，花擁弦歌咽畫楼。","錦袖妒姬爭巧笑，玉銜[驕]马索闲游。","麻衣酷獻平生業，醉倚春风不点头。"]', '诗', 'shi', '', NULL, '公子家二首 一 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf93a660-38dd-4394-bfbb-73bbed191eb0', '公子家二首 二', '公子家二首 二', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["柳底花陰壓露塵，醉煙輕罩一團春。","鴛鴦占水能嗔客，鸚鵡嫌籠解駡人。","騕褭似龍隨日換，輕盈如燕逐年新。","不知買盡長安笑，活得蒼生幾戶貧。"]', '["柳底花陰壓露塵，醉煙轻罩一團春。","鴛鴦占水能嗔客，鸚鵡嫌籠解駡人。","騕褭似龙隨日換，轻盈如燕逐年新。","不知買尽长安笑，活得蒼生幾戶貧。"]', '诗', 'shi', '', NULL, '公子家二首 二 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bc7d111-5685-4bd6-87cf-80d17db7b4fc', '山下殘夏偶作', '山下殘夏偶作', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["等閑三伏後，獨臥此高丘。","殘暑炎於火，林風爽帶秋。","聲名何要出，吟詠亦堪休。","自許紅塵外，雲溪好漱流。"]', '["等闲三伏後，独臥此高丘。","殘暑炎於火，林风爽带秋。","声名何要出，吟詠亦堪休。","自許紅塵外，云溪好漱流。"]', '诗', 'shi', '', NULL, '山下殘夏偶作 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd54e990-4f28-4d16-9cbd-1ce909e3247a', '夜吟', '夜吟', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["除却閑吟外，人間事事慵。","更深成一句，月冷上孤峯。","窮理多瞑目，含毫靜倚松。","終篇渾不寐，危坐到晨鐘。"]', '["除却闲吟外，人间事事慵。","更深成一句，月冷上孤峯。","窮理多瞑目，含毫静倚松。","終篇渾不寐，危坐到晨鐘。"]', '诗', 'shi', '', NULL, '夜吟 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7353dc-27dd-4f11-a384-4cec7a407e29', '代崇徽公主意', '代崇徽公主意', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["金釵墜地鬢堆雲，自別朝陽帝豈聞。","遣妾一身安社稷，不知何處用將軍。"]', '["金釵墜地鬢堆云，自別朝陽帝豈闻。","遣妾一身安社稷，不知何处用將軍。"]', '诗', 'shi', '', NULL, '代崇徽公主意 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3fb575b-cdf2-45a3-877a-29ff52418cc0', '下第獻所知三首 一', '下第獻所知三首 一', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["偶向江頭別釣磯，等閑經歲與心違。","虛教六尺受辛苦，枉把一身憂是非。","青桂本來無欠負，碧霄何處有因依？","春風不用相催促，迴避花時也解歸。"]', '["偶向江头別釣磯，等闲經歲與心違。","虛教六尺受辛苦，枉把一身憂是非。","青桂本来無欠負，碧霄何处有因依？","春风不用相催促，迴避花时也解归。"]', '诗', 'shi', '', NULL, '下第獻所知三首 一 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('636da7b1-f7f6-4a30-9b1a-c55ea8b60ff4', '下第獻所知三首 二', '下第獻所知三首 二', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["不識人間巧路岐，只將端拙泥神祇。","與他名利本無分，却共水雲曾有期。","大抵物情應莫料，近來天意也須疑。","自憐心計今如此，憑仗春醪爲解頤。"]', '["不識人间巧路岐，只將端拙泥神祇。","與他名利本無分，却共水云曾有期。","大抵物情應莫料，近来天意也須疑。","自怜心計今如此，憑仗春醪爲解頤。"]', '诗', 'shi', '', NULL, '下第獻所知三首 二 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4876b9e7-9ce2-4881-9855-e2cffdf3abc4', '下第獻所知三首 三', '下第獻所知三首 三', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["十年磨鏃事鋒鋩，始逐朱旗入戰塲。","四海風雲難際會，一生肝膽易開張。","退飛鶯谷春零落，倒卓龍門路渺茫。","今日慙知也慙命，笑餘歌罷忽淒涼。"]', '["十年磨鏃事鋒鋩，始逐朱旗入戰塲。","四海风云难際會，一生肝膽易开張。","退飞鶯谷春零落，倒卓龙门路渺茫。","今日慙知也慙命，笑餘歌罷忽淒涼。"]', '诗', 'shi', '', NULL, '下第獻所知三首 三 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08c626ac-6cb1-43a1-88ba-64644d1920f9', '寄太常王少卿', '寄太常王少卿', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["別後西風起，新蟬坐臥聞。","秋天靜如水，遠岫碧侵雲。","雅飲純和氣，清吟冰雪文。","想思重回首，梧葉下紛紛。"]', '["別後西风起，新蟬坐臥闻。","秋天静如水，远岫碧侵云。","雅饮純和氣，清吟冰雪文。","想思重回首，梧葉下紛紛。"]', '诗', 'shi', '', NULL, '寄太常王少卿 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87836386-02d5-42f5-a158-d441cc399d96', '遊俠兒', '游俠兒', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["好把雄姿渾世塵，一塲閑事莫因循。","荆軻只爲閑言語，不與燕丹了得人。"]', '["好把雄姿渾世塵，一塲闲事莫因循。","荆軻只爲闲言語，不與燕丹了得人。"]', '诗', 'shi', '', NULL, '遊俠兒 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e079c98-2067-4dd7-9665-8b84fdc7a7ad', '下第出春明門', '下第出春明门', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["曾和秋雨驅愁入，却向春風領恨回。","深謝灞陵堤畔柳，與人頭上拂塵埃。"]', '["曾和秋雨驱愁入，却向春风領恨回。","深謝灞陵堤畔柳，與人头上拂塵埃。"]', '诗', 'shi', '', NULL, '下第出春明門 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d6dbb6-2425-49cd-b264-b02cf89d4a0b', '望思臺', '望思台', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["君父昏蒙死不回，謾將平地築高臺。","九層黃土是何物，銷得向前冤恨來。"]', '["君父昏蒙死不回，謾將平地築高台。","九層黄土是何物，銷得向前冤恨来。"]', '诗', 'shi', '', NULL, '望思臺 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfff3e3a-8dd6-45d7-afc2-cb2379c13cf0', '病中答劉書記見贈', '病中答劉书記见贈', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["病來雙樹下，雲脚上禪袍。","頻有瓊瑤贈，空瞻雪月高。","已知捐俗態，時許話風騷。","衰疾未能起，相思徒自勞。"]', '["病来雙樹下，云脚上禪袍。","頻有瓊瑤贈，空瞻雪月高。","已知捐俗態，时許話风騷。","衰疾未能起，相思徒自勞。"]', '诗', 'shi', '', NULL, '病中答劉書記見贈 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db4aca4-0946-4b2a-be3e-f956540c9386', '早秋山中作', '早秋山中作', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["誰到山中語，雨餘風氣秋。","煙嵐出澗底，瀑布落牀頭。","至道亦非遠，僻詩須苦求。","千峰有嘉景，拄杖獨巡遊。"]', '["誰到山中語，雨餘风氣秋。","煙嵐出澗底，瀑布落牀头。","至道亦非远，僻诗須苦求。","千峰有嘉景，拄杖独巡游。"]', '诗', 'shi', '', NULL, '早秋山中作 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3650d400-b87b-405e-8235-45f67cbc43f1', '別墅', '別墅', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["此地可求息，開門足野情。","窗明雨初歇，日落風更清。","蒼蘚槎根匝，碧煙水面生。","翫奇心自樂，暑月聽蟬聲。"]', '["此地可求息，开门足野情。","窗明雨初歇，日落风更清。","蒼蘚槎根匝，碧煙水面生。","翫奇心自乐，暑月听蟬声。"]', '诗', 'shi', '', NULL, '別墅 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ca86906-05b4-4767-b25b-d01fbd0ead36', '柳十首 一', '柳十首 一', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["灞岸江頭臘雪消，東風偷軟入纖條。","春來不忍登樓望，萬架金絲著地嬌。"]', '["灞岸江头臘雪消，东风偷軟入纖條。","春来不忍登楼望，万架金絲著地嬌。"]', '诗', 'shi', '', NULL, '柳十首 一 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19cdb053-e124-471b-8dd2-985cbfcd581b', '柳十首 二', '柳十首 二', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["受盡風霜得到春，一條條是逐年新。","尋常送別無餘事，爭忍攀將過與人。"]', '["受尽风霜得到春，一條條是逐年新。","尋常送別無餘事，爭忍攀將過與人。"]', '诗', 'shi', '', NULL, '柳十首 二 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128ba1ca-fdcc-4dfb-986a-db65523adf7f', '柳十首 三', '柳十首 三', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["長恨陽和也世情，把香和豔與紅英。","家家只是栽桃李，獨自無根到處生。"]', '["长恨陽和也世情，把香和豔與紅英。","家家只是栽桃李，独自無根到处生。"]', '诗', 'shi', '', NULL, '柳十首 三 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbcd044a-da3b-4c27-9b15-64bb44afe41d', '柳十首 四', '柳十首 四', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["只爲遮樓又拂橋，被人摧折好枝條。","假饒張緒如今在，須把風流暗裏銷。"]', '["只爲遮楼又拂橋，被人摧折好枝條。","假饒張緒如今在，須把风流暗裏銷。"]', '诗', 'shi', '', NULL, '柳十首 四 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6106b1bf-bf97-4f80-956e-199203ab3384', '柳十首 五', '柳十首 五', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["弱帶低垂可自由，傍他門戶倚他樓。","金風不解相擡舉，露壓煙欺直到秋。"]', '["弱带低垂可自由，傍他门戶倚他楼。","金风不解相擡舉，露壓煙欺直到秋。"]', '诗', 'shi', '', NULL, '柳十首 五 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95c5f416-b8b0-456f-b022-c558e1a24090', '柳十首 六', '柳十首 六', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["終日堂前學畫眉，幾人曾道勝花枝。","試看三月春殘後，門外青陰是阿誰。"]', '["終日堂前学畫眉，幾人曾道勝花枝。","試看三月春殘後，门外青陰是阿誰。"]', '诗', 'shi', '', NULL, '柳十首 六 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0804b937-3f23-4d55-a4d4-76339462f67b', '柳十首 七', '柳十首 七', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["也曾飛絮謝家庭，從此風流別有名。","不是向人無用處，一枝愁殺別離情。"]', '["也曾飞絮謝家庭，從此风流別有名。","不是向人無用处，一枝愁殺別離情。"]', '诗', 'shi', '', NULL, '柳十首 七 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b997729-03fd-4a73-8a23-a79162f816c3', '柳十首 八', '柳十首 八', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["從來只是愛花人，楊柳何曾占得春。","多向客亭門外立，與他迎送往來塵。"]', '["從来只是愛花人，楊柳何曾占得春。","多向客亭门外立，與他迎送往来塵。"]', '诗', 'shi', '', NULL, '柳十首 八 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d7f74f-d56c-46f5-a07c-1d2600905bba', '柳十首 九', '柳十首 九', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["強扶柔態酒難醒，殢著春風別有情。","公子王孫且相伴，與君俱得幾時榮。"]', '["強扶柔態酒难醒，殢著春风別有情。","公子王孫且相伴，與君俱得幾时榮。"]', '诗', 'shi', '', NULL, '柳十首 九 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11ae213e-73fa-4ab5-ba0a-78188a66ddb5', '柳十首 十', '柳十首 十', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["無賴秋風斗覺寒，萬條煙草一時乾。","遊人若要春消息，直向江頭臘後看。"]', '["無賴秋风斗覺寒，万條煙草一时乾。","游人若要春消息，直向江头臘後看。"]', '诗', 'shi', '', NULL, '柳十首 十 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6fd333f-417b-48e4-a8d6-b9198a8dad4b', '酬劉書記見贈', '酬劉书記见贈', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["獨在西峯末，憐君和氣多。","勞生同朽索，急景似傾波。","禪者行擔錫，樵師語隔坡。","旱□生赤蘚，古木架青蘿。","石澗新蟬脫，茅簷舊燕窠。","篇章蒙見許，松月好相過。","思苦通真理，吟清合大和。","□□□□□，風起送漁歌。"]', '["独在西峯末，怜君和氣多。","勞生同朽索，急景似傾波。","禪者行擔錫，樵師語隔坡。","旱□生赤蘚，古木架青蘿。","石澗新蟬脫，茅簷旧燕窠。","篇章蒙见許，松月好相過。","思苦通真理，吟清合大和。","□□□□□，风起送漁歌。"]', '诗', 'shi', '', NULL, '酬劉書記見贈 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b382efc5-831e-47f6-8db8-e02330bbb27b', '贈徐三十', '贈徐三十', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["春滿南宮白日長，夜來新值錦衣郎。","朱排六相助神聳，玉襯一廳侵骨涼。","砌竹拂袍爭草色，庭花飄豔妬蘭香。","從今不羨乘槎客，曾到三星列宿傍。"]', '["春满南宮白日长，夜来新值錦衣郎。","朱排六相助神聳，玉襯一廳侵骨涼。","砌竹拂袍爭草色，庭花飄豔妬蘭香。","從今不羨乘槎客，曾到三星列宿傍。"]', '诗', 'shi', '', NULL, '贈徐三十 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('231418c4-d098-4d2e-8180-e83e5b9e79c4', '牡丹', '牡丹', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["邀勒春風不早開，衆芳飄後上樓臺。","數苞仙豔火中出，一片異香天上來。","曉露精神妖欲動，暮煙情態恨成堆。","知君也解相輕薄，斜倚闌干首重迴。"]', '["邀勒春风不早开，衆芳飄後上楼台。","數苞仙豔火中出，一片異香天上来。","晓露精神妖欲动，暮煙情態恨成堆。","知君也解相轻薄，斜倚闌干首重迴。"]', '诗', 'shi', '', NULL, '牡丹 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('804ac476-3c58-4164-aaca-30549dd0970e', '贈宿將', '贈宿將', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["校獵燕山經幾春，雕弓白羽不離身。","年來馬上渾無力，望見飛鴻指似人。"]', '["校獵燕山經幾春，雕弓白羽不離身。","年来马上渾無力，望见飞鴻指似人。"]', '诗', 'shi', '', NULL, '贈宿將 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03daac61-52d5-4b17-9b9c-1f38350768b1', '水仙操', '水仙操', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["大波相拍流水鳴，蓬山鳥獸多奇形。","琴心不喜亦不驚，安弦緩爪何泠泠。","水仙縹緲來相迎，伯牙從此留嘉名。","嶧陽散木虛且輕，重華斧下知其聲。","檿絲相糺成淒清，調和引得薰風生。","指底先王長養情，曲終天下稱太平。","後人好事傳其曲，有時聲足意不足。","始峩峩兮復洋洋，但見山青兼水綠。","成連入海移人情，豈是本來無嗜慾。","琴兮琴兮在自然，不在徽金將軫玉。"]', '["大波相拍流水鳴，蓬山鸟獸多奇形。","琴心不喜亦不驚，安弦緩爪何泠泠。","水仙縹緲来相迎，伯牙從此留嘉名。","嶧陽散木虛且轻，重华斧下知其声。","檿絲相糺成淒清，調和引得薰风生。","指底先王长養情，曲終天下稱太平。","後人好事傳其曲，有时声足意不足。","始峩峩兮复洋洋，但见山青兼水綠。","成連入海移人情，豈是本来無嗜慾。","琴兮琴兮在自然，不在徽金將軫玉。"]', '诗', 'shi', '', NULL, '水仙操 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ef8e21f-03b7-4d0e-b59f-26df8ef34195', '雞鳴曲', '雞鳴曲', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["海樹相扶烏影翹，戴紅拍翠聲膠膠。","鴛瓦凍危金距趫，誇雄鬬氣爭相高。","漏殘雨急風蕭蕭，患亂忠臣欺寶刀。","霜濃月薄星昭昭，太平才子能歌謠。","山翁夢斷出衡茅，谷口霧中飢虎號，離人枕上心忉忉。"]', '["海樹相扶烏影翹，戴紅拍翠声膠膠。","鴛瓦凍危金距趫，誇雄鬬氣爭相高。","漏殘雨急风蕭蕭，患亂忠臣欺寶刀。","霜濃月薄星昭昭，太平才子能歌謠。","山翁梦斷出衡茅，谷口霧中飢虎號，離人枕上心忉忉。"]', '诗', 'shi', '', NULL, '雞鳴曲 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0925b977-1e8a-435b-8c9c-c83039e3c518', '西門行', '西门行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["勞禽不擇枝，飢虎不畏檻。","君子當固窮，無爲仲由濫。","爾奮空拳彼擊劍，水縱長瀾火飛焰。","漢高偶試神蛇驗，武王龜筮驚人險。","四龍或躍猶依泉，小狐勿恃衝波膽。"]', '["勞禽不擇枝，飢虎不畏檻。","君子當固窮，無爲仲由濫。","爾奮空拳彼擊劍，水縱长瀾火飞焰。","漢高偶試神蛇驗，武王龟筮驚人險。","四龙或躍猶依泉，小狐勿恃衝波膽。"]', '诗', 'shi', '', NULL, '西門行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cda3ba75-7ed6-4d6a-9ea1-b7f343115c80', '輕薄怨', '轻薄怨', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["花驄躞蹀遊龍驕，連連寶節揮長鞘。","鳳雛麟子皆至交，春風相逐垂楊橋。","捻笙軟玉開素苞，畫樓閃閃紅裙搖。","碧蹄偃蹇連金鑣，狂情十里飛相燒。","西母青禽輕飄飄，分環破璧來往勞。","黃金千鎰新一宵，少年心事風中毛。","明朝何處逢嬌饒，門前桃樹空夭夭。"]', '["花驄躞蹀游龙驕，連連寶節揮长鞘。","鳳雛麟子皆至交，春风相逐垂楊橋。","捻笙軟玉开素苞，畫楼閃閃紅裙搖。","碧蹄偃蹇連金鑣，狂情十里飞相燒。","西母青禽轻飄飄，分环破璧来往勞。","黄金千鎰新一宵，少年心事风中毛。","明朝何处逢嬌饒，门前桃樹空夭夭。"]', '诗', 'shi', '', NULL, '輕薄怨 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92067edc-02e7-4eca-b3e1-e7f0651b38bf', '長歌行', '长歌行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["要衣須破束，欲炙須解牛。","當年不快意，徒爲他人留。","百歲之約何悠悠，華髪星星稀滿頭。","蛾眉螓首聊我仇，圓紅闕白令人愁，何不夕引清奏？","朝登翠樓，逢花便折，聞勝即遊。","鼓腕騰棍晴雷收，舞腰困褭垂楊柔。","象筯擊折歌勿休，玉山未倒非風流。","眼前有物俱是夢，莫將身作黃金讐。","死生同域不用懼，富貴在天何足憂。"]', '["要衣須破束，欲炙須解牛。","當年不快意，徒爲他人留。","百歲之約何悠悠，华髪星星稀满头。","蛾眉螓首聊我仇，圓紅闕白令人愁，何不夕引清奏？","朝登翠楼，逢花便折，闻勝即游。","鼓腕腾棍晴雷收，舞腰困褭垂楊柔。","象筯擊折歌勿休，玉山未倒非风流。","眼前有物俱是梦，莫將身作黄金讐。","死生同域不用懼，富貴在天何足憂。"]', '诗', 'shi', '', NULL, '長歌行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e85b3fc-0f9b-41ab-88ce-7be21972ab0f', '巫山高', '巫山高', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["通蜀連秦山十二，中有妖靈會人意。","鬬豔傳情世不知，楚王魂夢春風裏。","雨態雲容多似是，色荒見物皆成媚。","露泫煙愁巖上花，至今猶滴相思淚。","西眉南臉人中美，或者皆聞無所利。","忍聽憑虛巧佞言，不求萬壽翻求死。"]', '["通蜀連秦山十二，中有妖靈會人意。","鬬豔傳情世不知，楚王魂梦春风裏。","雨態云容多似是，色荒见物皆成媚。","露泫煙愁巖上花，至今猶滴相思泪。","西眉南臉人中美，或者皆闻無所利。","忍听憑虛巧佞言，不求万壽翻求死。"]', '诗', 'shi', '', NULL, '巫山高 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9285deb1-301a-4f27-a4f9-2e02f7ad6f64', '公無渡河', '公無渡河', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["有叟有叟何清狂，行搔短髪提壺漿。","亂流直涉神洋洋，妻止不聽追沈湘。","偕老不偕死，箜篌遺淒涼。","刳松輕穩琅玕長，連呼急榜庸何妨。","見溺不援能語狼，忍聽麗玉傳悲傷。"]', '["有叟有叟何清狂，行搔短髪提壺漿。","亂流直涉神洋洋，妻止不听追沈湘。","偕老不偕死，箜篌遺淒涼。","刳松轻穩琅玕长，連呼急榜庸何妨。","见溺不援能語狼，忍听丽玉傳悲傷。"]', '诗', 'shi', '', NULL, '公無渡河 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d50d76b-b580-4cd9-9f21-5cfbf582accc', '春雨', '春雨', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["大帝閑吹破凍風，青雲融液流長空。","天人醉引玄酒注，傾香旋入花根土。","濕塵輕舞唐唐春，神娥無跡莓苔新。","老農私與牧童論，紛紛便是倉箱本。"]', '["大帝闲吹破凍风，青云融液流长空。","天人醉引玄酒注，傾香旋入花根土。","濕塵轻舞唐唐春，神娥無跡莓苔新。","老農私與牧童論，紛紛便是倉箱本。"]', '诗', 'shi', '', NULL, '春雨 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aedd3f13-ad27-418f-b366-a0f5cf6ca6cb', '石版歌', '石版歌', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["雲根劈裂雷斧痕，龍泉切璞青皮皴。","直方挺質貞且真，當庭卓立凝頑神。","春雨流膏成立文，主人性靜看長新。","明月夜來迴短影，何如照冷太湖濱。"]', '["云根劈裂雷斧痕，龙泉切璞青皮皴。","直方挺質貞且真，當庭卓立凝頑神。","春雨流膏成立文，主人性静看长新。","明月夜来迴短影，何如照冷太湖濱。"]', '诗', 'shi', '', NULL, '石版歌 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('939820b9-39e1-45c4-bf95-2680b06a664e', '春宮詞', '春宮词', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["風和氣淑宮殿春，感陽體解思君恩。","眼光滴滴心振振，重瞳不轉憂生民，女當爲妾男當臣。","男力百歲在，女色片時新。","用不用，唯一人。","敢放天寵私微身，六宮萬國教誰賓。"]', '["风和氣淑宮殿春，感陽體解思君恩。","眼光滴滴心振振，重瞳不轉憂生民，女當爲妾男當臣。","男力百歲在，女色片时新。","用不用，唯一人。","敢放天寵私微身，六宮万国教誰賓。"]', '诗', 'shi', '', NULL, '春宮詞 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5767a5df-ea11-4c46-bf8c-6ab84e0f9f15', '富貴曲', '富貴曲', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["畫藻雕山金碧彩，鴛鴦曡翠眠晴靄。","編珠影裏醉春庭，團紅片下攢歌黛。","革咽絲煩歡不改，繳絳垂緹忽如晦。","活花起舞夜春來，蠟焰煌煌天日在。","雪暖瑤杯鳳髓融，紅拖象筯猩唇細。","空中漢轉星移蓋，火城擁出隨朝會。","車如雷兮馬如龍，鬼神辟易不敢害。","冠峩劍重鏘環珮，步入天門相真宰。","開口長爲爵祿筌，迴眸便是公卿罪。","珍珠索得龍宮貧，膏腴刮下蒼生背。","九野干戈指著心，威福滿拳猶未快。","我聞周公貴爲天子弟，富有半四海。","蔑有驕奢貽後悔，紅錦障收。","珊瑚樹碎，至今笑石崇王愷。"]', '["畫藻雕山金碧彩，鴛鴦曡翠眠晴靄。","編珠影裏醉春庭，團紅片下攢歌黛。","革咽絲煩歡不改，繳絳垂緹忽如晦。","活花起舞夜春来，蠟焰煌煌天日在。","雪暖瑤杯鳳髓融，紅拖象筯猩唇細。","空中漢轉星移蓋，火城擁出隨朝會。","车如雷兮马如龙，鬼神辟易不敢害。","冠峩劍重鏘环珮，步入天门相真宰。","开口长爲爵祿筌，迴眸便是公卿罪。","珍珠索得龙宮貧，膏腴刮下蒼生背。","九野干戈指著心，威福满拳猶未快。","我闻周公貴爲天子弟，富有半四海。","蔑有驕奢貽後悔，紅錦障收。","珊瑚樹碎，至今笑石崇王愷。"]', '诗', 'shi', '', NULL, '富貴曲 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f03bbe0c-559d-4226-8274-0f00a6087a42', '獨鵠吟', '独鵠吟', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["碧玉喙長丹頂圓，亭亭危立風松間。","啄萍吞鱗意已闌，舉頭咫尺輕重天。","黑翎白本排雲煙，離羣脫侶孤如仙。","披霜唳月驚嬋娟，逍遊忘却還青田。","鳶寒鴉晚空相喧，時時側耳清冷泉。"]', '["碧玉喙长丹頂圓，亭亭危立风松间。","啄萍吞鱗意已闌，舉头咫尺轻重天。","黑翎白本排云煙，離羣脫侶孤如仙。","披霜唳月驚嬋娟，逍游忘却還青田。","鳶寒鴉晚空相喧，时时側耳清冷泉。"]', '诗', 'shi', '', NULL, '獨鵠吟 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f2cd68-0eb1-4ca2-a3a9-5420406b5e86', '煌煌京洛行', '煌煌京洛行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["長安近甸巡遊遍，洛陽尋有黃龍見。","千乘萬騎如雷轉，差差清蹕祥雲卷。","百司舊分當玉殿，太平官屬無遺彥。","歌鐘沸激香塵散，晨旗隱隱羅軒冕。","周公舊跡生紅蘚，瀍澗波光春照晚。","但聽嵩山萬歲聲，將軍旗鼓何時偃。"]', '["长安近甸巡游遍，洛陽尋有黄龙见。","千乘万騎如雷轉，差差清蹕祥云卷。","百司旧分當玉殿，太平官屬無遺彥。","歌鐘沸激香塵散，晨旗隐隐羅軒冕。","周公旧跡生紅蘚，瀍澗波光春照晚。","但听嵩山万歲声，將軍旗鼓何时偃。"]', '诗', 'shi', '', NULL, '煌煌京洛行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce1b608-14c7-4a09-a30f-93edae9f99b9', '昇天行', '昇天行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["堂堂削玉青蠅喧，寒鴉啄鼠愁飛鸞。","梳玄洗白逡巡間，蘭言花笑俄衰殘。","盤金束紫身屬官，強仁小德終無端。","不如服取長流丹，潛神却入黃庭閑。","志定功成飛九關，逍遙長揖辭人寰。","空中龍駕時迴旋，左雲右鶴翔翩聯。","雙童樹節當風翻，常娥倚桂開朱顏。","河邊牛子星郎牽，三清宮殿浮晴煙。","玉皇據案方凝然，仙官立仗森幢幡。","引余再拜歸仙班，清聲妙色視聽安。","飡和飲順中腸寬，虛無之樂不可言。"]', '["堂堂削玉青蠅喧，寒鴉啄鼠愁飞鸾。","梳玄洗白逡巡间，蘭言花笑俄衰殘。","盤金束紫身屬官，強仁小德終無端。","不如服取长流丹，潛神却入黄庭闲。","志定功成飞九关，逍遙长揖辞人寰。","空中龙駕时迴旋，左云右鹤翔翩聯。","雙童樹節當风翻，常娥倚桂开朱顏。","河邊牛子星郎牽，三清宮殿浮晴煙。","玉皇據案方凝然，仙官立仗森幢幡。","引余再拜归仙班，清声妙色視听安。","飡和饮順中腸寬，虛無之乐不可言。"]', '诗', 'shi', '', NULL, '昇天行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c9cbf40-1977-4747-b0ac-a01dbf737224', '緋桃花歌', '緋桃花歌', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["上帝春宮思麗絕，夭桃變態求新悅。","便是花中傾國容，牡丹露泣長門月。","野樹滴殘龍戰血，曦車碾下朝霞屑。","惆悵東風未解狂，爭教此物芳菲歇。"]', '["上帝春宮思丽絕，夭桃变態求新悅。","便是花中傾国容，牡丹露泣长门月。","野樹滴殘龙戰血，曦车碾下朝霞屑。","惆悵东风未解狂，爭教此物芳菲歇。"]', '诗', 'shi', '', NULL, '緋桃花歌 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba307bc2-fca2-4441-8b4e-3077e577dd16', '短歌行', '短歌行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["一罇綠酒綠於染，拍手高歌天地險。","上得青雲下不難，下在黃埃上須漸。","少年歡樂須及時，莫學懦夫長泣岐。","白日欲沈猶未沈，片月已來天半垂。","坎鼓鏘鐘殺愁賊，挼碎是非佯不識。","長短高卑不可求，莫歎人生頭雪色。"]', '["一罇綠酒綠於染，拍手高歌天地險。","上得青云下不难，下在黄埃上須漸。","少年歡乐須及时，莫学懦夫长泣岐。","白日欲沈猶未沈，片月已来天半垂。","坎鼓鏘鐘殺愁賊，挼碎是非佯不識。","长短高卑不可求，莫歎人生头雪色。"]', '诗', 'shi', '', NULL, '短歌行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a91758f-e6d8-44cb-80a3-66390266ad68', '小松歌', '小松歌', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["幽人不喜凡草生，秋鋤斸得寒青青。","庭閑土瘦根脚獰，風搖雨拂精神醒。","短影月斜不滿尺，清聲細入鳴蛩翼。","天人戲剪蒼龍髯，參差簇在瑤堦側。","金精水鬼欺不得，長與東皇逞顏色。","勁節暫因君子移，貞心不爲麻中直。"]', '["幽人不喜凡草生，秋鋤斸得寒青青。","庭闲土瘦根脚獰，风搖雨拂精神醒。","短影月斜不满尺，清声細入鳴蛩翼。","天人戲剪蒼龙髯，參差簇在瑤堦側。","金精水鬼欺不得，长與东皇逞顏色。","勁節暫因君子移，貞心不爲麻中直。"]', '诗', 'shi', '', NULL, '小松歌 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4577b87-dc3b-4bee-8f03-206b385599fd', '大雪歌', '大雪歌', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["同雲慘慘如天怒，寒龍振鬣飛乾雨。","玉圃花飄朵不勻，銀河風急驚砂度。","謝客憑軒吟未住，望中頓失縱橫路。","應是羲和倦曉昏，暫反元元歸太素。"]', '["同云慘慘如天怒，寒龙振鬣飞乾雨。","玉圃花飄朵不勻，銀河风急驚砂度。","謝客憑軒吟未住，望中頓失縱橫路。","應是羲和倦晓昏，暫反元元归太素。"]', '诗', 'shi', '', NULL, '大雪歌 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f0caadb-5178-4f09-a14c-639866673920', '塘上行', '塘上行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["橫塘日澹秋雲隔，浪織輕颸羅冪冪。","紅綃撇水蕩舟人，畫橈摻摻柔荑白。","鯉魚虛擲無消息，花老蓮疎愁未摘。","却把金釵打綠荷，懊惱露珠穿不得。"]', '["橫塘日澹秋云隔，浪织轻颸羅冪冪。","紅綃撇水蕩舟人，畫橈摻摻柔荑白。","鯉鱼虛擲無消息，花老蓮疎愁未摘。","却把金釵打綠荷，懊惱露珠穿不得。"]', '诗', 'shi', '', NULL, '塘上行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8246838a-99ce-49e5-bf69-3ce37023549d', '寓意', '寓意', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["直道荆棘生，斜徑紅塵起。","蒼蒼杳無言，麒麟迴瑞趾。","東風如未來，飛雪終不已。"]', '["直道荆棘生，斜徑紅塵起。","蒼蒼杳無言，麒麟迴瑞趾。","东风如未来，飞雪終不已。"]', '诗', 'shi', '', NULL, '寓意 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be1e2db2-1783-4fbf-aed6-c3e6acbfce0d', '劍喻', '劍喻', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["黯黯秋水寒，至剛非可缺。","風胡不出來，攝履人相蔑。","縱挺倚天形，誰是躬提挈。","願將百鍊身，助我王臣節。"]', '["黯黯秋水寒，至剛非可缺。","风胡不出来，攝履人相蔑。","縱挺倚天形，誰是躬提挈。","願將百鍊身，助我王臣節。"]', '诗', 'shi', '', NULL, '劍喻 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6159f836-285c-4101-bc4c-4dd055ff6b4f', '蒼頡臺', '蒼頡台', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["先賢憂民詐，觀跡成綱紀。","自有書契來，爭及結繩理。"]', '["先賢憂民詐，观跡成綱紀。","自有书契来，爭及結繩理。"]', '诗', 'shi', '', NULL, '蒼頡臺 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('909092a6-5da8-4673-b9f7-19d714ae81b7', '荆山', '荆山', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["良工指君疑，真玉却非玉。","寄言懷寶人，不須傷手足。"]', '["良工指君疑，真玉却非玉。","寄言懷寶人，不須傷手足。"]', '诗', 'shi', '', NULL, '荆山 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b40d13d-2b6f-4452-a816-233027b1bc1e', '自君之出矣', '自君之出矣', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["自君之出矣，鸞鏡空塵生。","思君如明月，明月逐君行。"]', '["自君之出矣，鸾镜空塵生。","思君如明月，明月逐君行。"]', '诗', 'shi', '', NULL, '自君之出矣 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42e7879-b2d3-4f59-94dd-6c69736de33c', '妾薄命', '妾薄命', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["妾命何太薄，不及宮中水。","時時對天顏，聲聲入君耳。"]', '["妾命何太薄，不及宮中水。","时时对天顏，声声入君耳。"]', '诗', 'shi', '', NULL, '妾薄命 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b28c27f1-881e-416c-8da4-78cfa97903fd', '君子行', '君子行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["君子慎所履，小人多所疑。","尼甫至聖賢，猶爲匡所縻。"]', '["君子慎所履，小人多所疑。","尼甫至聖賢，猶爲匡所縻。"]', '诗', 'shi', '', NULL, '君子行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c30599b0-833f-4761-a532-0ef4375b8b15', '銅雀臺', '銅雀台', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["但見西陵慘明月，女妓無因更相悅。","有虞曾不有遺言，滴盡湘妃眼中血。"]', '["但见西陵慘明月，女妓無因更相悅。","有虞曾不有遺言，滴尽湘妃眼中血。"]', '诗', 'shi', '', NULL, '銅雀臺 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a0e28e-24f4-43fa-a526-f01acd371436', '倢伃怨', '倢伃怨', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["莫恃芙蓉開滿面，更有身輕似飛燕。","不得團圓長近君，珪月鈋時泣秋扇。"]', '["莫恃芙蓉开满面，更有身轻似飞燕。","不得團圓长近君，珪月鈋时泣秋扇。"]', '诗', 'shi', '', NULL, '倢伃怨 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c79b3b6-a192-4871-b4b3-9310179a7384', '悲哉行', '悲哉行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["雲色陰沈弄秋氣，危葉高枝恨深翠。","用却春風力幾多，微霜逼迫何容易。"]', '["云色陰沈弄秋氣，危葉高枝恨深翠。","用却春风力幾多，微霜逼迫何容易。"]', '诗', 'shi', '', NULL, '悲哉行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f988bdf-67c8-4516-990c-a7c0badc9659', '攜手曲', '携手曲', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["攜手春復春，未嘗漸離別。","夭夭風前花，纖纖日中雪。","不敢怨於天，唯驚添歲月。","不敢怨於君，秪怕芳菲歇。","芳菲若長然，君恩應不絕。"]', '["携手春复春，未嘗漸離別。","夭夭风前花，纖纖日中雪。","不敢怨於天，唯驚添歲月。","不敢怨於君，秪怕芳菲歇。","芳菲若长然，君恩應不絕。"]', '诗', 'shi', '', NULL, '攜手曲 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5acc90a9-612e-42eb-8a2d-29ab6c655c92', '空城雀', '空城雀', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["啾啾空城雀，一啄數跳躍。","寧尋覆轍餘，豈比巢危幕。","茫茫九萬鵬，百雉且爲樂。"]', '["啾啾空城雀，一啄數跳躍。","寧尋覆轍餘，豈比巢危幕。","茫茫九万鵬，百雉且爲乐。"]', '诗', 'shi', '', NULL, '空城雀 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6566b47-4995-4a3c-b87a-fc474110965a', '放歌行', '放歌行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["蠢蠢荼蓼蟲，薨薨避葵薺。","悠悠狷者心，寂寂厭清世。","如何不食甘，命合苦其噬。","如何不趣時，分合辱其體。","至哉先哲言，於物不凝滯。"]', '["蠢蠢荼蓼蟲，薨薨避葵薺。","悠悠狷者心，寂寂厭清世。","如何不食甘，命合苦其噬。","如何不趣时，分合辱其體。","至哉先哲言，於物不凝滯。"]', '诗', 'shi', '', NULL, '放歌行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92fd4bec-c397-4b44-b8b0-e5d3caa1b99f', '猛虎行', '猛虎行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["猛虎不怯敵，烈士無虛言。","怯敵辱其班，虛言負其恩。","爪牙欺白刃，果敢無前陣。","須知易水歌，至死無悔恡。"]', '["猛虎不怯敵，烈士無虛言。","怯敵辱其班，虛言負其恩。","爪牙欺白刃，果敢無前陣。","須知易水歌，至死無悔恡。"]', '诗', 'shi', '', NULL, '猛虎行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8797f174-0807-4bb0-96ae-219c0bbb731c', '隴頭行', '隴头行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["行人何徬徨，隴頭水嗚咽。","寒沙戰鬼愁，白骨風霜切。","薄日曚曨秋，怨氣陰雲結。","殺成邊將名，名著生靈滅。"]', '["行人何徬徨，隴头水嗚咽。","寒沙戰鬼愁，白骨风霜切。","薄日曚曨秋，怨氣陰云結。","殺成邊將名，名著生靈滅。"]', '诗', 'shi', '', NULL, '隴頭行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('797e6674-d389-4f87-bdfb-50861c154abe', '關山月', '关山月', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["離離天際雲，皎皎關山月。","羌笛一聲來，白盡征人髪。","嘹唳孤鴻高，蕭索悲風發。","雪壓塞塵清，鵰落沙場闊。","何當胡無人，荷戈朝鳳闕。"]', '["離離天際云，皎皎关山月。","羌笛一声来，白尽征人髪。","嘹唳孤鴻高，蕭索悲风發。","雪壓塞塵清，鵰落沙場闊。","何當胡無人，荷戈朝鳳闕。"]', '诗', 'shi', '', NULL, '關山月 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('410ae66b-d8e5-454a-9394-ce259c8c4091', '覽友生古風', '覽友生古风', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["伯牙鳴玉琴，幽音隨指發。","不是鍾期聽，俗耳安能別。","高山閑巍峩，流水聲嗚咽。","一卷冰雪言，清泠冷心骨。","分明古雅聲，諷諭成淒切。","皴皵老松根，晃朗驪龍窟。","荆璞且深藏，瑉石方如雪。","金多醜女妍，木朽良工拙。","姦宄欺雷霆，魑魅嫌日月。","蝶迷桃李香，鮒惘江湖闊。","不寐孤燈前，舒卷忘飢渴。"]', '["伯牙鳴玉琴，幽音隨指發。","不是鍾期听，俗耳安能別。","高山闲巍峩，流水声嗚咽。","一卷冰雪言，清泠冷心骨。","分明古雅声，諷諭成淒切。","皴皵老松根，晃朗驪龙窟。","荆璞且深藏，瑉石方如雪。","金多醜女妍，木朽良工拙。","姦宄欺雷霆，魑魅嫌日月。","蝶迷桃李香，鮒惘江湖闊。","不寐孤灯前，舒卷忘飢渴。"]', '诗', 'shi', '', NULL, '覽友生古風 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('787b7a62-4b3e-4010-b265-c5772c34dcba', '題友生叢竹', '題友生叢竹', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["菊華寒露濃，蘭愁曉霜重。","指佞不長生，蒲萐今無種。","安如植叢篁，他年待栖鳳。","大則化龍騎，小可釣璜用。","留煙伴獨醒，迴陰冷閑夢。","何妨積雪凌，但爲清風動。","乃知子猷心，不與常人共。"]', '["菊华寒露濃，蘭愁晓霜重。","指佞不长生，蒲萐今無種。","安如植叢篁，他年待栖鳳。","大則化龙騎，小可釣璜用。","留煙伴独醒，迴陰冷闲梦。","何妨積雪凌，但爲清风动。","乃知子猷心，不與常人共。"]', '诗', 'shi', '', NULL, '題友生叢竹 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eca3daa-333c-4bb6-9509-5f32aa5022c0', '石版', '石版', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["高人好自然，移得它山碧。","不磨如版平，大巧非因力。","古蘚小青錢，塵中看野色。","冷倚砌花春，靜伴疎篁直。","山僧若轉頭，如逢舊相識。"]', '["高人好自然，移得它山碧。","不磨如版平，大巧非因力。","古蘚小青錢，塵中看野色。","冷倚砌花春，静伴疎篁直。","山僧若轉头，如逢旧相識。"]', '诗', 'shi', '', NULL, '石版 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('468099c0-de06-4952-9db7-27c905c8594b', '江南曲', '江南曲', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["江南四月薰風低，江南女兒芳步齊。","晚雲接水共渺瀰，遠沙曡草空萋萋。","白苧不堪論古意，數花猶可醉前溪。","孤舟有客歸未得，鄉夢欲成山鳥啼。"]', '["江南四月薰风低，江南女兒芳步齊。","晚云接水共渺瀰，远沙曡草空萋萋。","白苧不堪論古意，數花猶可醉前溪。","孤舟有客归未得，乡梦欲成山鸟啼。"]', '诗', 'shi', '', NULL, '江南曲 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88bcc6f6-8a16-4a94-970e-6fe45705a34e', '臨川逢陳百年', '臨川逢陳百年', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["麻姑山下逢真士，玄膚碧眼方瞳子。","自言混沌鑿不死，大笑老彭非久視。","強爭龍虎是狂人，不保元和虛叩齒。","桃花雨過春光膩，勸我一杯靈液味。","教我無爲禮樂拘，利路名場多忌諱。","不如含德反嬰兒，金玉滿堂真可貴。"]', '["麻姑山下逢真士，玄膚碧眼方瞳子。","自言混沌鑿不死，大笑老彭非久視。","強爭龙虎是狂人，不保元和虛叩齒。","桃花雨過春光膩，勸我一杯靈液味。","教我無爲禮乐拘，利路名場多忌諱。","不如含德反嬰兒，金玉满堂真可貴。"]', '诗', 'shi', '', NULL, '臨川逢陳百年 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c597786f-a5f2-4b07-ad43-74ce16d1934a', '寄修睦上人', '寄修睦上人', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["衣服田方無內客，一入廬雲斷消息。","應爲山中勝概偏，惠持惠遠多蹤跡。","尋陽有箇虛舟子，相憶由來無一事。","江邊月色到巖前，此際心情必相似。","似不似，寄數字。"]', '["衣服田方無內客，一入廬云斷消息。","應爲山中勝概偏，惠持惠远多蹤跡。","尋陽有箇虛舟子，相憶由来無一事。","江邊月色到巖前，此際心情必相似。","似不似，寄數字。"]', '诗', 'shi', '', NULL, '寄修睦上人 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9443135-efc1-4f5a-85d0-991f03bb71d3', '讀修睦上人歌篇', '读修睦上人歌篇', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["李白亡，李賀死。","陳陶趙睦尋相次，須知代不乏騷人。","貫休之後，惟修睦而已矣。","睦公睦公真可畏，開口向人無所忌。","才似煙霞生則媚，直如屈軼佞則指。","意下紛紛造化機，筆頭滴滴文章髓。","明月清風三十年，被君驅使如奴婢。","勸君休，莫容易，世俗由來稀則貴。","珊瑚高架五雲毫，小小不須煩藻思。"]', '["李白亡，李賀死。","陳陶趙睦尋相次，須知代不乏騷人。","貫休之後，惟修睦而已矣。","睦公睦公真可畏，开口向人無所忌。","才似煙霞生則媚，直如屈軼佞則指。","意下紛紛造化機，笔头滴滴文章髓。","明月清风三十年，被君驱使如奴婢。","勸君休，莫容易，世俗由来稀則貴。","珊瑚高架五云毫，小小不須煩藻思。"]', '诗', 'shi', '', NULL, '讀修睦上人歌篇 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2572035f-4df7-4a35-ae19-13155ff59d4d', '遠公亭牡丹', '远公亭牡丹', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["雁門禪客吟春亭，牡丹獨逞花中英。","雙成膩臉偎雲屏，百般姿態因風生。","延年不敢歌傾城，朝雲暮雨愁娉婷。","蘂繁蟻脚黏不行，甜迷蜂醉飛無聲。","廬山根脚含精靈，發妍吐秀叢君庭。","湓江太守多閑情，欄朱繞絳留輕盈。","潺潺綠醴當風傾，平頭奴子啾銀笙。","紅葩豔豔交童星，左文右武憐君榮，白銅鞮上慙清明。"]', '["雁门禪客吟春亭，牡丹独逞花中英。","雙成膩臉偎云屏，百般姿態因风生。","延年不敢歌傾城，朝云暮雨愁娉婷。","蘂繁蟻脚黏不行，甜迷蜂醉飞無声。","廬山根脚含精靈，發妍吐秀叢君庭。","湓江太守多闲情，欄朱繞絳留轻盈。","潺潺綠醴當风傾，平头奴子啾銀笙。","紅葩豔豔交童星，左文右武怜君榮，白銅鞮上慙清明。"]', '诗', 'shi', '', NULL, '遠公亭牡丹 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c11b6611-4f6c-4581-9d9f-90a50ca8457e', '謝僧寄茶', '謝僧寄茶', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["空門少年初志堅，摘芳爲藥除睡眠。","匡山茗樹朝陽偏，暖萌如爪拏飛鳶。","枝枝膏露凝滴圓，參差失向兜羅錦。","傾筐短甑蒸新鮮，白紵眼細勻於研。","甎排古砌春苔乾，殷勤寄我清明前。","金槽無聲飛碧煙，赤獸呵冰急鐵喧。","林風夕和真珠泉，半匙清粉攪潺湲。","綠雲輕綰湘娥鬟，嘗來縱使重支枕，胡蝶寂寥空掩關。"]', '["空门少年初志堅，摘芳爲藥除睡眠。","匡山茗樹朝陽偏，暖萌如爪拏飞鳶。","枝枝膏露凝滴圓，參差失向兜羅錦。","傾筐短甑蒸新鲜，白紵眼細勻於研。","甎排古砌春苔乾，殷勤寄我清明前。","金槽無声飞碧煙，赤獸呵冰急鐵喧。","林风夕和真珠泉，半匙清粉攪潺湲。","綠云轻綰湘娥鬟，嘗来縱使重支枕，胡蝶寂寥空掩关。"]', '诗', 'shi', '', NULL, '謝僧寄茶 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad6e0da4-972f-4c71-9a55-6197676c79a3', '送人', '送人', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["少皥開宮行帝業，無刃金風剪紅葉。","雁別邊沙入暖雲，蛩辭敗草鳴香閤。","有客爲儒二十霜，酣歌郢雪時飄揚。","不甘長在諸生下，束書攜劒離家鄉。","利爪韝上鷹，雄文霧中豹。","可堪長與烏鳶噪，是宜摩碧漢以遐飛。","出南山而遠蹈，況今大朝公道。","天子文明，團團月樹懸青青。","燕中有馬如龍行，不換黃金無駿名。","荆山有玉猶在璞，未遇良工虛擲鵲。","一壺清酒酌離情，休向嵩中隨雀躍。"]', '["少皥开宮行帝業，無刃金风剪紅葉。","雁別邊沙入暖云，蛩辞敗草鳴香閤。","有客爲儒二十霜，酣歌郢雪时飄揚。","不甘长在諸生下，束书携劒離家乡。","利爪韝上鷹，雄文霧中豹。","可堪长與烏鳶噪，是宜摩碧漢以遐飞。","出南山而远蹈，況今大朝公道。","天子文明，團團月樹懸青青。","燕中有马如龙行，不換黄金無駿名。","荆山有玉猶在璞，未遇良工虛擲鵲。","一壺清酒酌離情，休向嵩中隨雀躍。"]', '诗', 'shi', '', NULL, '送人 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b59c44-5d20-4657-8230-20936edb9367', '古意論交', '古意論交', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["擇友如淘金，沙盡不得寶。","結交如乾銀，產竭不成道。","我生四十年，相識苦草草。","多爲勢利朋，少有歲寒操。","通財能幾何，聞善寧相告。","茫然同夜行，中路自不保。","常恐管鮑情，參差忽終老。","今來既見君，青天無片雲。","語直瑟弦急，行高山桂芬。","約我爲交友，不覺心醺醺。","見義必許死，臨危當指囷。","無令後世士，重廣孝標文。"]', '["擇友如淘金，沙尽不得寶。","結交如乾銀，產竭不成道。","我生四十年，相識苦草草。","多爲勢利朋，少有歲寒操。","通財能幾何，闻善寧相告。","茫然同夜行，中路自不保。","常恐管鲍情，參差忽終老。","今来既见君，青天無片云。","語直瑟弦急，行高山桂芬。","約我爲交友，不覺心醺醺。","见義必許死，臨危當指囷。","無令後世士，重廣孝標文。"]', '诗', 'shi', '', NULL, '古意論交 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06274f5a-bc41-4b8a-9f97-645a16336434', '春風', '春风', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["青帝使和氣，吹噓萬國中。","發生寧有異，先後自難同。","輦草不消力，巖花應費功。","年年三十騎，飄入玉蟾宮。"]', '["青帝使和氣，吹噓万国中。","發生寧有異，先後自难同。","輦草不消力，巖花應費功。","年年三十騎，飄入玉蟾宮。"]', '诗', 'shi', '', NULL, '春風 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe9b161-4cdc-4cb3-99a7-f250a07afe10', '自愧', '自愧', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["多負懸弧禮，危時隱薜蘿。","有心明俎豆，無力執干戈。","壯士難移節，貞松不改柯。","纓塵徒自滿，欲濯待清波。"]', '["多負懸弧禮，危时隐薜蘿。","有心明俎豆，無力執干戈。","壯士难移節，貞松不改柯。","纓塵徒自满，欲濯待清波。"]', '诗', 'shi', '', NULL, '自愧 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a44a66f-c717-40af-aac0-15c5c26e8485', '夜吟', '夜吟', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["白兔輪當午，儒家業敢慵。","竹軒吟未已，錦帳夢應重。","落筆思成虎，懸梭待化龍。","景清神自爽，風逓遠樓鐘。"]', '["白兔輪當午，儒家業敢慵。","竹軒吟未已，錦帳梦應重。","落笔思成虎，懸梭待化龙。","景清神自爽，风逓远楼鐘。"]', '诗', 'shi', '', NULL, '夜吟 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b067afe8-c19a-498b-bed2-65327983cb5b', '昭君', '昭君', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["古帝修文德，蠻夷莫敢侵。","不知桃李貌，能轉虎狼心。","日暮邊風急，程遙磧雪深。","千秋青塚骨，留怨在胡琴。"]', '["古帝修文德，蠻夷莫敢侵。","不知桃李貌，能轉虎狼心。","日暮邊风急，程遙磧雪深。","千秋青塚骨，留怨在胡琴。"]', '诗', 'shi', '', NULL, '昭君 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eb0e6a6-8e4a-42c9-b3c8-c58adfbf2f72', '秋夕', '秋夕', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["寥廓秋雲薄，空庭月影微。","樹寒棲鳥密，砌冷夜蛩稀。","曉鼓軍容肅，疎鐘客夢歸。","吟餘何所憶，聖主尚宵衣。"]', '["寥廓秋云薄，空庭月影微。","樹寒棲鸟密，砌冷夜蛩稀。","晓鼓軍容肅，疎鐘客梦归。","吟餘何所憶，聖主尚宵衣。"]', '诗', 'shi', '', NULL, '秋夕 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3932be-883b-4804-817f-ddfe13cc2220', '秋日與友生言別', '秋日與友生言別', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["利名心未已，離別恨難休。","爲箇文儒業，致多岐路愁。","數花籬菊晚，片葉井梧秋。","又決出門計，一尊期少留。"]', '["利名心未已，離別恨难休。","爲箇文儒業，致多岐路愁。","數花籬菊晚，片葉井梧秋。","又決出门計，一尊期少留。"]', '诗', 'shi', '', NULL, '秋日與友生言別 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79d30b12-c3a7-4985-aac1-066f56fa52dd', '邊城聽角', '邊城听角', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["戍樓鳴畫角，寒露滴金槍。","細引雲成陣，高催雁著行。","喚迴邊將夢，吹薄曉蟾光。","未遂終軍志，何勞思故鄉。"]', '["戍楼鳴畫角，寒露滴金槍。","細引云成陣，高催雁著行。","喚迴邊將梦，吹薄晓蟾光。","未遂終軍志，何勞思故乡。"]', '诗', 'shi', '', NULL, '邊城聽角 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02a6b142-7f05-4123-8877-220ea1439066', '秋日訪同人', '秋日訪同人', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["忽憶金蘭友，攜琴去自由。","遠尋寒澗碧，深入亂山秋。","見後却無語，別來長獨愁。","幸逢三五夕，露坐對冥搜。"]', '["忽憶金蘭友，携琴去自由。","远尋寒澗碧，深入亂山秋。","见後却無語，別来长独愁。","幸逢三五夕，露坐对冥搜。"]', '诗', 'shi', '', NULL, '秋日訪同人 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53edfcf6-21b2-4677-9237-5dbfef58ab14', '寄楚瓊上人', '寄楚瓊上人', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["遙知無事日，靜對五峰秋。","鳥隔寒煙語，泉和夕照流。","凭欄疎磬盡，瞑目遠雲收。","幾句出人意，風高白雪浮。"]', '["遙知無事日，静对五峰秋。","鸟隔寒煙語，泉和夕照流。","凭欄疎磬尽，瞑目远云收。","幾句出人意，风高白雪浮。"]', '诗', 'shi', '', NULL, '寄楚瓊上人 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16df96bc-83b9-4212-baac-a828c15caf97', '遊寺', '游寺', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["無家身自在，時得到蓮宮。","秋覺暑衣薄，老知塵世空。","幽情憐水石，野性任萍蓬。","是處堪閑坐，與僧行止同。"]', '["無家身自在，时得到蓮宮。","秋覺暑衣薄，老知塵世空。","幽情怜水石，野性任萍蓬。","是处堪闲坐，與僧行止同。"]', '诗', 'shi', '', NULL, '遊寺 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef6cc2fe-cf04-44b5-aa17-049709544d65', '春日', '春日', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["浩蕩東風裏，裴回無所親。","危城三面水，古樹一邊春。","衰世難修道，花時不稱貧。"]', '["浩蕩东风裏，裴回無所親。","危城三面水，古樹一邊春。","衰世难修道，花时不稱貧。"]', '诗', 'shi', '', NULL, '春日 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dfb2d9f-2bcc-451a-9da5-8a33ef426f27', '論交', '論交', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["行虧何必富，節在不妨貧。","易得笑言友，難逢終始人。","松篁貞管鮑，桃李豔張陳。","少見歲寒後，免爲霜雪塵。"]', '["行虧何必富，節在不妨貧。","易得笑言友，难逢終始人。","松篁貞管鲍，桃李豔張陳。","少见歲寒後，免爲霜雪塵。"]', '诗', 'shi', '', NULL, '論交 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d8d9c8-3feb-42bb-aca2-0c1bdcef504c', '秋興', '秋兴', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["木葉亂飛盡，故人猶未還。","心雖遊紫闕，時合在青山。","近寺僧鄰靜，臨池鶴對閑。","兵戈如未息，名位莫相關。"]', '["木葉亂飞尽，故人猶未還。","心雖游紫闕，时合在青山。","近寺僧鄰静，臨池鹤对闲。","兵戈如未息，名位莫相关。"]', '诗', 'shi', '', NULL, '秋興 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efbe7067-6be0-4f7e-8a3f-5e9d225940e0', '山居', '山居', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["草堂書一架，苔徑竹千竿。","難世投誰是，清貧且自安。","鄰居皆學稼，客至亦無官。","焦尾何人聽，涼宵對月彈。"]', '["草堂书一架，苔徑竹千竿。","难世投誰是，清貧且自安。","鄰居皆学稼，客至亦無官。","焦尾何人听，涼宵对月彈。"]', '诗', 'shi', '', NULL, '山居 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('458b9af4-8ced-4422-9c58-40fc59635d2a', '遣興', '遣兴', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["風細酒初醒，憑欄別有情。","蟬稀秋樹瘦，雨盡晚雲輕。","旅鬢一絲出，鄉心寸火生。","子牟魂欲斷，何日是升平。"]', '["风細酒初醒，憑欄別有情。","蟬稀秋樹瘦，雨尽晚云轻。","旅鬢一絲出，乡心寸火生。","子牟魂欲斷，何日是升平。"]', '诗', 'shi', '', NULL, '遣興 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('835ce4f2-24b9-4c25-a4ac-cce96100461d', '待旦', '待旦', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["簷靜燕雛語，窗虛蟾影過。","時情因客老，歸夢入秋多。","蔽日羣山霧，滔天四海波。","吾皇思壯士，誰應大風歌。"]', '["簷静燕雛語，窗虛蟾影過。","时情因客老，归梦入秋多。","蔽日羣山霧，滔天四海波。","吾皇思壯士，誰應大风歌。"]', '诗', 'shi', '', NULL, '待旦 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8beccc46-1d8b-4e32-8ae8-fcf621ce386a', '送從兄坤載', '送從兄坤載', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["忍淚不敢下，恐兄情更傷。","別離當亂世，骨肉在他鄉。","語盡意不盡，路長愁更長。","那堪回首處，殘照滿衣裳。"]', '["忍泪不敢下，恐兄情更傷。","別離當亂世，骨肉在他乡。","語尽意不尽，路长愁更长。","那堪回首处，殘照满衣裳。"]', '诗', 'shi', '', NULL, '送從兄坤載 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('489d38f5-329b-4627-a6e1-8c521ae187a6', '惜別', '惜別', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["細雨妝行色，霏霏入戶來。","須知相識喜，却是別愁媒。","白刃方盈國，黃金不上臺。"]', '["細雨妝行色，霏霏入戶来。","須知相識喜，却是別愁媒。","白刃方盈国，黄金不上台。"]', '诗', 'shi', '', NULL, '惜別 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d174cba5-5379-4a13-ba63-5d93c3079802', '早秋遊山寺', '早秋游山寺', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["閑臥雲巖穩，攀緣笑戲猱。","靜於諸境靜，高却衆山高。","至理無言了，浮生一夢勞。","清風朝復暮，四海自波濤。"]', '["闲臥云巖穩，攀緣笑戲猱。","静於諸境静，高却衆山高。","至理無言了，浮生一梦勞。","清风朝复暮，四海自波濤。"]', '诗', 'shi', '', NULL, '早秋遊山寺 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e0710a-ff8c-4707-ac10-97ff5ca0baca', '秋日疾中寄諸同志', '秋日疾中寄諸同志', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["閑居無勝事，公幹臥來心。","門靜秋風晚，人稀古巷深。","花疎籬菊色，葉減井梧陰。","賴有斯文在，時時得強尋。"]', '["闲居無勝事，公幹臥来心。","门静秋风晚，人稀古巷深。","花疎籬菊色，葉減井梧陰。","賴有斯文在，时时得強尋。"]', '诗', 'shi', '', NULL, '秋日疾中寄諸同志 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caa1cd0b-4de2-431c-ab43-701cf92dc45e', '贈山僧', '贈山僧', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["榮枯雖在目，名利不關身。","高出城隍寺，野爲雲鶴鄰。","松聲寒後遠，潭色雨餘新。","豈住空空裏，空空亦是塵。"]', '["榮枯雖在目，名利不关身。","高出城隍寺，野爲云鹤鄰。","松声寒後远，潭色雨餘新。","豈住空空裏，空空亦是塵。"]', '诗', 'shi', '', NULL, '贈山僧 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c5024a-4396-4ec5-bd66-115379050621', '宿隱者居', '宿隐者居', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["永日連清夜，因君識躁君。","竹扉難掩月，巖樹易延雲。","曙鳥枕前起，寒泉夢裏聞。","又須隨計吏，雞鶴迥然分。"]', '["永日連清夜，因君識躁君。","竹扉难掩月，巖樹易延云。","曙鸟枕前起，寒泉梦裏闻。","又須隨計吏，雞鹤迥然分。"]', '诗', 'shi', '', NULL, '宿隱者居 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79bc43cf-ff1c-4f79-8ed7-ef23d3db3273', '送錢契明尊師歸廬山', '送錢契明尊師归廬山', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["瘦倚青竹杖，鑪峰指欲歸。","霜黏行日屨，風暖到時衣。","憑檻雲還在，攀松鶴不飛。","何曾有別恨，楊柳自依依。"]', '["瘦倚青竹杖，鑪峰指欲归。","霜黏行日屨，风暖到时衣。","憑檻云還在，攀松鹤不飞。","何曾有別恨，楊柳自依依。"]', '诗', 'shi', '', NULL, '送錢契明尊師歸廬山 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac9faf74-5f90-470e-a063-5444bd494af8', '送進士劉松', '送進士劉松', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["滔滔皆魯客，難得是心知。","到寺多同步，遊山未失期。","雲低春雨後，風細暮鐘時。","忽別垂楊岸，遙遙望所之。"]', '["滔滔皆魯客，难得是心知。","到寺多同步，游山未失期。","云低春雨後，风細暮鐘时。","忽別垂楊岸，遙遙望所之。"]', '诗', 'shi', '', NULL, '送進士劉松 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05730877-1741-4016-acda-56647cc356c5', '贈任肅', '贈任肅', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["玄髪難姑息，青雲有路岐。","莫言多事日，虛擲少年時。","松色雪中出，人情難後知。","聖朝公道在，中鵠勿差池。"]', '["玄髪难姑息，青云有路岐。","莫言多事日，虛擲少年时。","松色雪中出，人情难後知。","聖朝公道在，中鵠勿差池。"]', '诗', 'shi', '', NULL, '贈任肅 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd31eed7-1086-49ef-9eca-64b74ea9533e', '題陳正字山居', '題陳正字山居', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["怪來忘祿位，習學近瀟湘。","見處雲山好，吟中歲月長。","花光籠晚雨，樹映浸寒塘。","幾日憑欄望，歸心自不忙。"]', '["怪来忘祿位，習学近瀟湘。","见处云山好，吟中歲月长。","花光籠晚雨，樹映浸寒塘。","幾日憑欄望，归心自不忙。"]', '诗', 'shi', '', NULL, '題陳正字山居 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eecbf0f-c2f3-45b8-8626-eba2f3fc57b0', '贈來進士鵬', '贈来進士鵬', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["語玄人不到，星漢在靈空。","若使無良遇，虛言有至公。","月明千嶠雪，灘急五更風。","此際苦吟力，分將造化功。"]', '["語玄人不到，星漢在靈空。","若使無良遇，虛言有至公。","月明千嶠雪，灘急五更风。","此際苦吟力，分將造化功。"]', '诗', 'shi', '', NULL, '贈來進士鵬 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab2d2305-2e50-4492-8762-10f52e08d644', '送曹稅', '送曹稅', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["摻袂向春風，何時約再逢。","若教相見密，肯恨別離重。","芳草漁家路，殘陽水寺鐘。","落帆當此處，吟興不應慵。"]', '["摻袂向春风，何时約再逢。","若教相见密，肯恨別離重。","芳草漁家路，殘陽水寺鐘。","落帆當此处，吟兴不應慵。"]', '诗', 'shi', '', NULL, '送曹稅 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ccf313-f574-4962-9a7e-d24e52c5747e', '贈來鵬', '贈来鵬', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["默坐非關悶，凝情秪在詩。","庭閑花落後，山靜月明時。","荅客言多簡，尋僧步稍遲。","既同和氏璧，終有玉人知。"]', '["默坐非关悶，凝情秪在诗。","庭闲花落後，山静月明时。","荅客言多簡，尋僧步稍遲。","既同和氏璧，終有玉人知。"]', '诗', 'shi', '', NULL, '贈來鵬 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6ebbf7-d0c5-4638-89cc-a1e4c01e4e73', '途中作', '途中作', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["瘦馬倦行役，斜陽勸著鞭。","野橋寒樹亞，山店暮雲連。","退鷁風雖急，攀龍志已堅。","路人休莫笑，百里有時賢。"]', '["瘦马倦行役，斜陽勸著鞭。","野橋寒樹亞，山店暮云連。","退鷁风雖急，攀龙志已堅。","路人休莫笑，百里有时賢。"]', '诗', 'shi', '', NULL, '途中作 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f0518c3-c371-48cb-aee5-480af9a863ad', '秋晚', '秋晚', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["斜陽山雨外，秋色思無窮。","柳葉飄乾翠，楓枝撼碎紅。","鬢毛看似雪，生計尚如蓬。","不及樵童樂，蒹葭一笛風。"]', '["斜陽山雨外，秋色思無窮。","柳葉飄乾翠，楓枝撼碎紅。","鬢毛看似雪，生計尚如蓬。","不及樵童乐，蒹葭一笛风。"]', '诗', 'shi', '', NULL, '秋晚 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3917ec48-e51f-4e43-be54-d3d61563f0d5', '曉望', '晓望', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["露驚松上鶴，曉色動扶桑。","碧浪催人老，紅輪照物忙。","世情隨日變，利路與天長。","好駕觥船去，陶陶入醉鄉。"]', '["露驚松上鹤，晓色动扶桑。","碧浪催人老，紅輪照物忙。","世情隨日变，利路與天长。","好駕觥船去，陶陶入醉乡。"]', '诗', 'shi', '', NULL, '曉望 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('434606b8-d921-4fe0-95d9-2deaf7f1d2a4', '寄友生', '寄友生', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["交情應不變，何事久離羣。","圓月思同步，寒泉憶共聞。","雪霜松色在，風雨雁行分。","每見人來說，窗前改舊文。"]', '["交情應不变，何事久離羣。","圓月思同步，寒泉憶共闻。","雪霜松色在，风雨雁行分。","每见人来说，窗前改旧文。"]', '诗', 'shi', '', NULL, '寄友生 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92e19adb-fd2c-45af-a6f0-eab2d9803d30', '江行', '江行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["瀟湘無事後，征棹復嘔啞。","高岫留斜照，歸鴻背落霞。","魚殘沙岸草，蝶寄洑流槎。","共說干戈苦，汀洲減釣家。"]', '["瀟湘無事後，征棹复嘔啞。","高岫留斜照，归鴻背落霞。","鱼殘沙岸草，蝶寄洑流槎。","共说干戈苦，汀洲減釣家。"]', '诗', 'shi', '', NULL, '江行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d45f485c-3c30-44b7-a414-f14cba61e690', '題王氏山居', '題王氏山居', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["簷有煙嵐色，地多松竹風。","自言離亂後，不到鼓鼙中。","徑柳拂雲綠，山櫻帶雪紅。","南邊青嶂下，時見採芝翁。"]', '["簷有煙嵐色，地多松竹风。","自言離亂後，不到鼓鼙中。","徑柳拂云綠，山櫻带雪紅。","南邊青嶂下，时见採芝翁。"]', '诗', 'shi', '', NULL, '題王氏山居 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c8b12d5-c287-4152-b546-bde4a09d753b', '送別', '送別', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["別意說難盡，離盃深莫辭。","長歌終此席，一笑又何時。","棹入寒潭急，帆當落照遲。","遠書如不寄，無以慰相思。"]', '["別意说难尽，離盃深莫辞。","长歌終此席，一笑又何时。","棹入寒潭急，帆當落照遲。","远书如不寄，無以慰相思。"]', '诗', 'shi', '', NULL, '送別 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85efa425-c26e-4ef8-9eb9-a3ce28d52c70', '覽文僧卷', '覽文僧卷', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["雖無先聖耳，異代得聞昭。","怪石難爲古，奇花不敢妖。","調高非郢雪，思靜礙箕瓢。","未可重吟過，雲山興轉饒。"]', '["雖無先聖耳，異代得闻昭。","怪石难爲古，奇花不敢妖。","調高非郢雪，思静礙箕瓢。","未可重吟過，云山兴轉饒。"]', '诗', 'shi', '', NULL, '覽文僧卷 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38549906-01a3-49e6-9e48-569aee2c1b73', '望仰山憶玄泰上人', '望仰山憶玄泰上人', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["晴嵐凝片碧，知在此中禪。","見面定何日，無書已一年。","高秋關靜夢，良夜入新篇。","仰德心如是，清風不我傳。"]', '["晴嵐凝片碧，知在此中禪。","见面定何日，無书已一年。","高秋关静梦，良夜入新篇。","仰德心如是，清风不我傳。"]', '诗', 'shi', '', NULL, '望仰山憶玄泰上人 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('116e161b-4964-4d91-aa3a-d48b88fd8090', '聞泉', '闻泉', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["淅淅夢初驚，幽窗枕簟清。","更無人共聽，秪有月空明。","急想穿巖曲，低應過石平。","欲將琴強寫，不是自然聲。"]', '["淅淅梦初驚，幽窗枕簟清。","更無人共听，秪有月空明。","急想穿巖曲，低應過石平。","欲將琴強寫，不是自然声。"]', '诗', 'shi', '', NULL, '聞泉 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b816e2-7ec1-4d06-a3bb-fc8f1e1750a7', '酬鄭進士九江新居見寄', '酬鄭進士九江新居见寄', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["躡屐扣柴關，因成盡日閑。","獨聽黃鳥語，深似白雲間。","萍沼寬於井，莎城綠當山。","前期招我作，此景得吟還。"]', '["躡屐扣柴关，因成尽日闲。","独听黄鸟語，深似白云间。","萍沼寬於井，莎城綠當山。","前期招我作，此景得吟還。"]', '诗', 'shi', '', NULL, '酬鄭進士九江新居見寄 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acfaa4fa-3c35-4f86-80a6-5108a2436530', '九江和人贈陳生', '九江和人贈陳生', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["天畏斯文墜，憑君助素風。","意深皆可補，句逸不因功。","暮替雲愁遠，秋驚月占空。","寄家當瀑布，時得笑言同。"]', '["天畏斯文墜，憑君助素风。","意深皆可補，句逸不因功。","暮替云愁远，秋驚月占空。","寄家當瀑布，时得笑言同。"]', '诗', 'shi', '', NULL, '九江和人贈陳生 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9b97fac-69f5-4b09-af59-e59969077dc0', '登樓值雨二首 一', '登楼值雨二首 一', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["共訝高樓望，匡廬色已空。","白雲橫野闊，遮嶽與天同。","數點雨入酒，滿襟香在風。","遠江吟得出，方下郡齋東。"]', '["共訝高楼望，匡廬色已空。","白云橫野闊，遮嶽與天同。","數点雨入酒，满襟香在风。","远江吟得出，方下郡斋东。"]', '诗', 'shi', '', NULL, '登樓值雨二首 一 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b573c8-62f4-4b6b-999b-8658ad52a3d9', '登樓值雨二首 二', '登楼值雨二首 二', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["江徼多佳景，秋吟興未窮。","送來松檻雨，半是蓼花風。","浪猛驚翹鷺，煙昏叫斷鴻。","不知今夜客，幾處臥鳴篷。"]', '["江徼多佳景，秋吟兴未窮。","送来松檻雨，半是蓼花风。","浪猛驚翹鷺，煙昏叫斷鴻。","不知今夜客，幾处臥鳴篷。"]', '诗', 'shi', '', NULL, '登樓值雨二首 二 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c8ad77-2a19-46f6-9661-8b23996922a4', '送趙舒處士歸廬山', '送趙舒处士归廬山', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["歸岫香鑪碧，行吟步益遲。","諸侯師不得，樵客偶相隨。","思舊江雲斷，談玄嶽月移。","秪應張野輩，異代作心知。"]', '["归岫香鑪碧，行吟步益遲。","諸侯師不得，樵客偶相隨。","思旧江云斷，談玄嶽月移。","秪應張野輩，異代作心知。"]', '诗', 'shi', '', NULL, '送趙舒處士歸廬山 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d1ebc13-f6cf-4907-bed4-e0a19a60731f', '僧院薔薇', '僧院薔薇', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["客引擎茶看，離披曬錦紅。","不緣開淨域，爭忍負春風。","小片當吟落，清香入定空。","何人來此植，應固惱休公。"]', '["客引擎茶看，離披曬錦紅。","不緣开淨域，爭忍負春风。","小片當吟落，清香入定空。","何人来此植，應固惱休公。"]', '诗', 'shi', '', NULL, '僧院薔薇 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4867c606-50fe-4d38-9db7-c07e52764cb2', '友生攜修睦上人詩見訪', '友生携修睦上人诗见訪', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["雪中敲竹戶，袖出岳僧詩。","語盡景皆活，吟闌角獨吹。","意如將俗背，業必少人知。","共約冰銷日，雲邊訪所思。"]', '["雪中敲竹戶，袖出岳僧诗。","語尽景皆活，吟闌角独吹。","意如將俗背，業必少人知。","共約冰銷日，云邊訪所思。"]', '诗', 'shi', '', NULL, '友生攜修睦上人詩見訪 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcf7dfa4-fdc6-4ecb-bd85-e03092339cf8', '冬夕喜友生至', '冬夕喜友生至', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["天涯行欲遍，此夜故人情。","鄉國別來久，干戈還未平。","燈殘偏有焰，雪甚却無聲。","多少新聞見，應須語到明。"]', '["天涯行欲遍，此夜故人情。","乡国別来久，干戈還未平。","灯殘偏有焰，雪甚却無声。","多少新闻见，應須語到明。"]', '诗', 'shi', '', NULL, '冬夕喜友生至 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3dec6a2-8c43-4760-a08e-a9619dfb8e91', '牡丹', '牡丹', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["少見南人識，識來嗟復驚。","始知春有色，不信爾無情。","恐是天地媚，暫隨雲雨生。","緣何絕尤物，更可比妍明。"]', '["少见南人識，識来嗟复驚。","始知春有色，不信爾無情。","恐是天地媚，暫隨云雨生。","緣何絕尤物，更可比妍明。"]', '诗', 'shi', '', NULL, '牡丹 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ccabf20-7fee-4e7c-b4f9-307e5b1ebf62', '送春', '送春', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["四時爲第一，一歲一重來。","好景應難勝，餘花虛自開。","相思九箇月，得信數枝梅。","不向東門送，還成負酒杯。"]', '["四时爲第一，一歲一重来。","好景應难勝，餘花虛自开。","相思九箇月，得信數枝梅。","不向东门送，還成負酒杯。"]', '诗', 'shi', '', NULL, '送春 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed4dece-4776-4243-9b90-0f7d0494c862', '送邊將', '送邊將', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["天驕頻犯塞，鐵騎又征西。","臣節輕鄉土，雄心生鼓鼙。","地寒花不豔，沙遠日難低。","漸喜秋弓健，鵰翻白草齊。"]', '["天驕頻犯塞，鐵騎又征西。","臣節轻乡土，雄心生鼓鼙。","地寒花不豔，沙远日难低。","漸喜秋弓健，鵰翻白草齊。"]', '诗', 'shi', '', NULL, '送邊將 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a86d87f4-33bb-4434-8bbd-3a04cbe6d949', '春晴', '春晴', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["簷滴春膏絕，憑欄晚吹生。","良朋在何處，高樹忽流鶯。","遊寺期應定，尋芳步已輕。","新詩吟未穩，遲日又西傾。"]', '["簷滴春膏絕，憑欄晚吹生。","良朋在何处，高樹忽流鶯。","游寺期應定，尋芳步已轻。","新诗吟未穩，遲日又西傾。"]', '诗', 'shi', '', NULL, '春晴 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3158fdcf-4e90-438b-b999-37b423d08756', '冬夜與修睦上人宿遠公亭寄南嶽玄泰禪師', '冬夜與修睦上人宿远公亭寄南嶽玄泰禪師', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["丈室掩孤燈，更深霰雹增。","相看雲夢客，共憶祝融僧。","語合茶忘味，吟欹卷有稜。","楚南山水秀，行止豈無憑。"]', '["丈室掩孤灯，更深霰雹增。","相看云梦客，共憶祝融僧。","語合茶忘味，吟欹卷有稜。","楚南山水秀，行止豈無憑。"]', '诗', 'shi', '', NULL, '冬夜與修睦上人宿遠公亭寄南嶽玄泰禪師 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cef109e-90f7-4734-924f-f81e826a52a6', '落花', '落花', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["拾得移時看，重思造化功。","如何飄麗景，不似遇春風。","滿地餘香在，繁枝一夜空。","秪應公子見，先憶墜樓紅。"]', '["拾得移时看，重思造化功。","如何飄丽景，不似遇春风。","满地餘香在，繁枝一夜空。","秪應公子见，先憶墜楼紅。"]', '诗', 'shi', '', NULL, '落花 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e79a51a4-95e6-402f-a9ce-81371a5ce938', '寄嵩陽隱者', '寄嵩陽隐者', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["昔年江上別，初入亂離中。","我住匡山北，君之少室東。","信來經險道，詩半憶皇風。","何事猶高臥，巖邊夢未通。"]', '["昔年江上別，初入亂離中。","我住匡山北，君之少室东。","信来經險道，诗半憶皇风。","何事猶高臥，巖邊梦未通。"]', '诗', 'shi', '', NULL, '寄嵩陽隱者 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('978164b2-cc71-4ee7-b99e-250dbee9f7f5', '早蟬', '早蟬', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["門柳不連野，乍聞爲早蟬。","遊人無定處，入耳更應先。","暫默斜陽雨，重吟遠岸煙。","前年湘竹裏，風激遶離筵。"]', '["门柳不連野，乍闻爲早蟬。","游人無定处，入耳更應先。","暫默斜陽雨，重吟远岸煙。","前年湘竹裏，风激遶離筵。"]', '诗', 'shi', '', NULL, '早蟬 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43b75b1a-3a46-4106-89e8-945e7b31d082', '酬蘊微', '酬蘊微', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["白衣經亂世，相遇一開顏。","得句禪思外，論交野步間。","舉朝無舊識，入眼秪青山。","幾度斜陽寺，訪君還獨還。"]', '["白衣經亂世，相遇一开顏。","得句禪思外，論交野步间。","舉朝無旧識，入眼秪青山。","幾度斜陽寺，訪君還独還。"]', '诗', 'shi', '', NULL, '酬蘊微 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b8a597f-c2ac-4f20-8a68-3876c5d0091f', '萱草', '萱草', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["芳草比君子，詩人情有由。","秪應憐雅態，未必解忘憂。","積雨莎庭小，微風蘚砌幽。","莫言開太晚，猶勝菊花秋。"]', '["芳草比君子，诗人情有由。","秪應怜雅態，未必解忘憂。","積雨莎庭小，微风蘚砌幽。","莫言开太晚，猶勝菊花秋。"]', '诗', 'shi', '', NULL, '萱草 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51c51f72-e949-436f-a59b-7f8d0ddb8b8b', '訪友人不遇', '訪友人不遇', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["出門無至友，動即到君家。","空掩一庭竹，去看何寺花。","短童應捧杖，稚女學擎茶。","吟罷留題處，苔階日影斜。"]', '["出门無至友，动即到君家。","空掩一庭竹，去看何寺花。","短童應捧杖，稚女学擎茶。","吟罷留題处，苔階日影斜。"]', '诗', 'shi', '', NULL, '訪友人不遇 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('720d5d2a-70b8-4f8f-b71d-fdfbed21d56e', '苔', '苔', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["幾年風雨跡，曡在石孱顏。","生處景長靜，看來情儘閑。","吟亭侵壞壁，藥院掩空關。","每憶東行徑，移筇獨自還。"]', '["幾年风雨跡，曡在石孱顏。","生处景长静，看来情儘闲。","吟亭侵壞壁，藥院掩空关。","每憶东行徑，移筇独自還。"]', '诗', 'shi', '', NULL, '苔 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ad8641-b390-46e8-806b-aa9f9e5769aa', '紅薇', '紅薇', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["春雨有五色，灑來花旋成。","欲留池上景，別染草中英。","畫出看還欠，蓪爲插未輕。","王孫多好事，攜酒寄吟傾。"]', '["春雨有五色，灑来花旋成。","欲留池上景，別染草中英。","畫出看還欠，蓪爲插未轻。","王孫多好事，携酒寄吟傾。"]', '诗', 'shi', '', NULL, '紅薇 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b14b39-e0f0-410f-9c43-88918e8a2f7c', '別所知', '別所知', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["有路有西東，天涯自恨同。","却須深酌酒，況不比飄蓬。","帆冒新秋雨，鼓傳微浪風。","閏牽寒氣早，何浦值賓鴻。"]', '["有路有西东，天涯自恨同。","却須深酌酒，況不比飄蓬。","帆冒新秋雨，鼓傳微浪风。","閏牽寒氣早，何浦值賓鴻。"]', '诗', 'shi', '', NULL, '別所知 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63bbd3d2-eb26-47f1-8aa3-6e012f9ff965', '小雪', '小雪', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["散漫陰風裏，天涯不可收。","壓松猶未得，撲石暫能留。","閣靜縈吟思，途長拂旅愁。","崆峒山北面，早想玉成丘。"]', '["散漫陰风裏，天涯不可收。","壓松猶未得，撲石暫能留。","閣静縈吟思，途长拂旅愁。","崆峒山北面，早想玉成丘。"]', '诗', 'shi', '', NULL, '小雪 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99d23371-41cb-4840-b6b2-4ee068cb1a4d', '和修睦上人聽猿', '和修睦上人听猿', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["禪客聞猶苦，是聲應是啼。","自然無穩夢，何必到巴溪。","疎雨灑不歇，迴風吹暫低。","此宵秋欲半，山在二林西。"]', '["禪客闻猶苦，是声應是啼。","自然無穩梦，何必到巴溪。","疎雨灑不歇，迴风吹暫低。","此宵秋欲半，山在二林西。"]', '诗', 'shi', '', NULL, '和修睦上人聽猿 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff4b8352-b778-47a2-908f-4213ad72151e', '庭竹', '庭竹', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["嫩綠與老碧，森然庭砌中。","坐銷三伏景，吟起數竿風。","葉影重還密，梢聲遠或通。","更期春共看，桃映小花紅。"]', '["嫩綠與老碧，森然庭砌中。","坐銷三伏景，吟起數竿风。","葉影重還密，梢声远或通。","更期春共看，桃映小花紅。"]', '诗', 'shi', '', NULL, '庭竹 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c73f1743-c1e4-4353-973e-933723f4d058', '早行', '早行', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["家國三千里，中宵算去程。","困纔成蝶夢，行不待雞鳴。","馬首搖殘月，鴉羣起古城。","發來經幾堠，村寺遠鐘聲。"]', '["家国三千里，中宵算去程。","困纔成蝶梦，行不待雞鳴。","马首搖殘月，鴉羣起古城。","發来經幾堠，村寺远鐘声。"]', '诗', 'shi', '', NULL, '早行 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10eb553b-117a-42d3-856a-99e94d376742', '哭所知', '哭所知', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["朝作青雲士，暮爲玄夜人。","風燈無定度，露薤亦逡巡。","乘馬驚新塚，書帷擺舊塵。","秪應從此去，何處福生民。"]', '["朝作青云士，暮爲玄夜人。","风灯無定度，露薤亦逡巡。","乘马驚新塚，书帷擺旧塵。","秪應從此去，何处福生民。"]', '诗', 'shi', '', NULL, '哭所知 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76a4e88d-6f6c-4011-8172-2e1088a2b126', '分題雪霽望爐峰', '分題雪霽望爐峰', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["雪霽上庭除，爐峰勢轉孤。","略無煙作帶，獨有影沈湖。","冷觸歸鴻急，明凝落照俱。","□□□□□，□□□□□。"]', '["雪霽上庭除，爐峰勢轉孤。","略無煙作带，独有影沈湖。","冷觸归鴻急，明凝落照俱。","□□□□□，□□□□□。"]', '诗', 'shi', '', NULL, '分題雪霽望爐峰 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a58eafd-bfd1-4fbf-9c30-e0cb153dadb0', '雪十二韻', '雪十二韻', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["六出凝陰氣，同雲指上天。","結時風乍急，集處霰長先。","草穗翹祥燕，陂樁吐白蓮。","犬狂南陌上，竹醉小池前。","樵徑花黏履，漁舟玉帖舷。","陣經暘谷薄，勢想朔方偏。","樓面光搖錫，籬頭曉列錢。","石苔青鹿臥，殿網素蛾穿。","嘶馬應思塞，蹲烏似爲燕。","童癡爲獸揑，僧愛用茶煎。","念物希周穆，含毫愧惠連。","吟闌餘興逸，還憶剡溪船。"]', '["六出凝陰氣，同云指上天。","結时风乍急，集处霰长先。","草穗翹祥燕，陂樁吐白蓮。","犬狂南陌上，竹醉小池前。","樵徑花黏履，漁舟玉帖舷。","陣經暘谷薄，勢想朔方偏。","楼面光搖錫，籬头晓列錢。","石苔青鹿臥，殿網素蛾穿。","嘶马應思塞，蹲烏似爲燕。","童癡爲獸揑，僧愛用茶煎。","念物希周穆，含毫愧惠連。","吟闌餘兴逸，還憶剡溪船。"]', '诗', 'shi', '', NULL, '雪十二韻 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411ff059-1d88-4da8-bf72-efedfefa833f', '廬山', '廬山', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["非嶽不言嶽，此山通嶽言。","高人居亂世，幾處滿前軒。","秀作神仙宅，靈爲風雨根。","餘陰鋪楚甸，一柱表吳門。","靜得八公侶，雄臨九子尊。","對猶青熨眼，到必冷凝魂。","勢受重湖讓，形難七澤吞。","黑巖藏晝電，紫霧泛朝暾。","蓮墮寧唯華，玉焚堪小崑。","倒松微發罅，飛瀑遠成痕。","曡見雲容襯，稜收雪氣昏。","裁詩曾困謝，作賦偶無孫。","流礙星光撇，驚衝雁陣翻。","峰奇寒倚劍，泉曲旋如盆。","草短分雛雉，林明露擲猿。","秋楓紅葉散，春石谷雷奔。","月好虎溪路，煙深栗里源。","醉吟長易醒，夢去亦銷煩。","有覺南方重，無疑厚地掀。","輕揚聞舊俗，端用鎮元元。"]', '["非嶽不言嶽，此山通嶽言。","高人居亂世，幾处满前軒。","秀作神仙宅，靈爲风雨根。","餘陰鋪楚甸，一柱表吳门。","静得八公侶，雄臨九子尊。","对猶青熨眼，到必冷凝魂。","勢受重湖讓，形难七澤吞。","黑巖藏晝電，紫霧泛朝暾。","蓮墮寧唯华，玉焚堪小崑。","倒松微發罅，飞瀑远成痕。","曡见云容襯，稜收雪氣昏。","裁诗曾困謝，作賦偶無孫。","流礙星光撇，驚衝雁陣翻。","峰奇寒倚劍，泉曲旋如盆。","草短分雛雉，林明露擲猿。","秋楓紅葉散，春石谷雷奔。","月好虎溪路，煙深栗里源。","醉吟长易醒，梦去亦銷煩。","有覺南方重，無疑厚地掀。","轻揚闻旧俗，端用鎮元元。"]', '诗', 'shi', '', NULL, '廬山 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e32cb5d-fe81-4b60-b4b1-c786cc487cdf', '和吳處士題村叟壁', '和吳处士題村叟壁', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["因閱鄉居景，歸心寸火然。","吾家依碧嶂，小檻枕清川。","遠雨籠孤戍，斜陽隔斷煙。","沙虛遺虎跡，水洑聚蛟涎。","糲麴芟汀蓼，甘茶挈石泉。","霜朝巡栗樹，風夜探漁船。","戲日魚呈腹，翹灘鷺並肩。","碁尋盤石淨，酒傍野花妍。","器以鋤爲利，家惟竹直錢。","飯香同豆熟，湯暖摘松煎。","睡島鳧藏足，攀藤狖凍拳。","淺茅鳴鬬雉，曲枿嘯寒鳶。","秋果𣙁梨澀，晨羞笋蕨鮮。","衣蓑留冷閣，席草種閑田。","椎髻擔餔餉，龐眉識稔年。","嚇鷹芻戴笠，驅犢篠充鞭。","不重官於社，常尊食作天。","谷深青靄蔽，峰迥白雲纏。","每憶關魂夢，長誇表愛憐。","覽君書壁句，誘我率成篇。"]', '["因閱乡居景，归心寸火然。","吾家依碧嶂，小檻枕清川。","远雨籠孤戍，斜陽隔斷煙。","沙虛遺虎跡，水洑聚蛟涎。","糲麴芟汀蓼，甘茶挈石泉。","霜朝巡栗樹，风夜探漁船。","戲日鱼呈腹，翹灘鷺並肩。","碁尋盤石淨，酒傍野花妍。","器以鋤爲利，家惟竹直錢。","飯香同豆熟，湯暖摘松煎。","睡島鳧藏足，攀藤狖凍拳。","淺茅鳴鬬雉，曲枿嘯寒鳶。","秋果𣙁梨澀，晨羞笋蕨鲜。","衣蓑留冷閣，席草種闲田。","椎髻擔餔餉，龐眉識稔年。","嚇鷹芻戴笠，驱犢篠充鞭。","不重官於社，常尊食作天。","谷深青靄蔽，峰迥白云纏。","每憶关魂梦，长誇表愛怜。","覽君书壁句，誘我率成篇。"]', '诗', 'shi', '', NULL, '和吳處士題村叟壁 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2883592-eaf5-47a2-bd3d-7ded35fda71a', '謝友生遺端溪硯瓦', '謝友生遺端溪硯瓦', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["尋常濡翰次，恨不到端溪。","得自新知己，如逢舊解攜。","翫餘輕照乘，謝欲等懸黎。","靜對勝凡客，閑窺憶好題。","媧天補剩石，昆劍切來泥。","著指痕猶濕，停旬水未低。","呵雲潤柱礎，筆彩飲虹霓。","鵒眼工諳謬，羊肝士乍刲。","連澌光比鏡，囚墨膩於䃜。","書信成池黑，吟須到日西。","正誇憂盜竊，將隱怯攀躋。","捧受同交印，矜持過秉珪。","草顛終近旭，嬾癖必無嵇。","用合緣鸚鵡，珍應負會稽。","貞姿還落落，寒韻或淒淒。","風月情相半，煙花思豈迷。","宜從方袋挈，枉把短行批。","淺小金爲斗，泓澄玉作堤。","遇人依我惜，想爾與天齊。","□□□□□，行時秪獨齎。"]', '["尋常濡翰次，恨不到端溪。","得自新知己，如逢旧解携。","翫餘轻照乘，謝欲等懸黎。","静对勝凡客，闲窺憶好題。","媧天補剩石，昆劍切来泥。","著指痕猶濕，停旬水未低。","呵云潤柱礎，笔彩饮虹霓。","鵒眼工諳謬，羊肝士乍刲。","連澌光比镜，囚墨膩於䃜。","书信成池黑，吟須到日西。","正誇憂盜竊，將隐怯攀躋。","捧受同交印，矜持過秉珪。","草顛終近旭，嬾癖必無嵇。","用合緣鸚鵡，珍應負會稽。","貞姿還落落，寒韻或淒淒。","风月情相半，煙花思豈迷。","宜從方袋挈，枉把短行批。","淺小金爲斗，泓澄玉作堤。","遇人依我惜，想爾與天齊。","□□□□□，行时秪独齎。"]', '诗', 'shi', '', NULL, '謝友生遺端溪硯瓦 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1160324-9771-4072-aba9-2d1c31cb3e76', '和殷衙推春霖即事', '和殷衙推春霖即事', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["東風吹暖雨，潤下不能休。","古道雲橫白，移時客共愁。","綠沈莎似藻，紅泛葉爲舟。","忽起江湖興，疑鄰畎澮流。","此時無勝會，何處滯奇遊？","陣急如酣戰，點麤成亂漚。","竹因添灑落，松得長颼飀。","花慘閑庭晚，蘭深曲徑幽。","絲牽汀鳥足，線挂嶽猿頭。","天地昏同醉，寰區浩欲浮。","柳眉低帶泣，蒲劍銳初抽。","石燕飜空重，蟲羅綴滴稠。","荷傾蛟淚盡，巖拆電鞭收。","豈直望堯喜，却懷微禹憂。","樹滋堪採菌，磯沒懶垂鈎。","腥覺聞龍氣，寒宜擁豹裘。","名膏那作沴，思稔必通侯。","蚌鷸徒喧競，笙歌罷獻酬。","山川藏秀媚，草木逞調柔。","極目非吾意，行吟獨下樓。"]', '["东风吹暖雨，潤下不能休。","古道云橫白，移时客共愁。","綠沈莎似藻，紅泛葉爲舟。","忽起江湖兴，疑鄰畎澮流。","此时無勝會，何处滯奇游？","陣急如酣戰，点麤成亂漚。","竹因添灑落，松得长颼飀。","花慘闲庭晚，蘭深曲徑幽。","絲牽汀鸟足，線挂嶽猿头。","天地昏同醉，寰區浩欲浮。","柳眉低带泣，蒲劍銳初抽。","石燕飜空重，蟲羅綴滴稠。","荷傾蛟泪尽，巖拆電鞭收。","豈直望堯喜，却懷微禹憂。","樹滋堪採菌，磯沒懶垂鈎。","腥覺闻龙氣，寒宜擁豹裘。","名膏那作沴，思稔必通侯。","蚌鷸徒喧競，笙歌罷獻酬。","山川藏秀媚，草木逞調柔。","極目非吾意，行吟独下楼。"]', '诗', 'shi', '', NULL, '和殷衙推春霖即事 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1eb5b40-1b74-4c68-b5b2-769cf0826dd8', '題陳將軍別墅', '題陳將軍別墅', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["明王獵士猶疎在，巖谷安居最有才。","高虎壯言知鬼伏，葛龍閑臥待時來。","雲藏山色晴還媚，風約溪聲靜又迴。","不獨春光堪醉客，庭除長見好花開。"]', '["明王獵士猶疎在，巖谷安居最有才。","高虎壯言知鬼伏，葛龙闲臥待时来。","云藏山色晴還媚，风約溪声静又迴。","不独春光堪醉客，庭除长见好花开。"]', '诗', 'shi', '', NULL, '題陳將軍別墅 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e4e4190-3c5e-4234-a828-2c8608dfc343', '湘浦有懷', '湘浦有懷', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["鴻雁哀哀背朔方，餘霞倒影畫瀟湘。","長汀細草愁春浪，古渡寒花倚夕陽。","鬼樹夜分千炬火，漁舟朝巷一蓬霜。","儂家本是持竿者，爲愛明時入帝鄉。"]', '["鴻雁哀哀背朔方，餘霞倒影畫瀟湘。","长汀細草愁春浪，古渡寒花倚夕陽。","鬼樹夜分千炬火，漁舟朝巷一蓬霜。","儂家本是持竿者，爲愛明时入帝乡。"]', '诗', 'shi', '', NULL, '湘浦有懷 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c32eeaf-fa61-44ce-8e59-8487d19e18ea', '題陳處士山居', '題陳处士山居', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["蓮遶閑停柳遶池，蟬吟暮色一枝枝。","未逢皇澤搜遺逸，贏得青山避亂離。","花圃春風邀客醉，茅簷秋雨對僧碁。","樵童牧豎勞相問，巖穴從來出帝師。"]', '["蓮遶闲停柳遶池，蟬吟暮色一枝枝。","未逢皇澤搜遺逸，贏得青山避亂離。","花圃春风邀客醉，茅簷秋雨对僧碁。","樵童牧豎勞相问，巖穴從来出帝師。"]', '诗', 'shi', '', NULL, '題陳處士山居 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432e8516-22fb-41fa-b79c-5b3e5ce897ef', '和蔣進士秋日', '和蔣進士秋日', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["晚雨霏微思杪秋，不堪才子尚羇遊。","塵隨別騎東西急，波促年華日夜流。","涼月雲開光自遠，古松風在韻難休。","男兒但得功名立，縱是深恩亦易酬。"]', '["晚雨霏微思杪秋，不堪才子尚羇游。","塵隨別騎东西急，波促年华日夜流。","涼月云开光自远，古松风在韻难休。","男兒但得功名立，縱是深恩亦易酬。"]', '诗', 'shi', '', NULL, '和蔣進士秋日 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb17d113-a2f4-47aa-bdbd-4b4ff1cadfb6', '陳正字山居', '陳正字山居', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["一葉閑飛斜照裏，江南仲蔚在蓬蒿。","天衢雲險駑駘蹇，月桂風和夢想勞。","遶枕泉聲秋雨細，對門山色古屏高。","此中即是神仙地，引手何妨一釣鼇。"]', '["一葉闲飞斜照裏，江南仲蔚在蓬蒿。","天衢云險駑駘蹇，月桂风和梦想勞。","遶枕泉声秋雨細，对门山色古屏高。","此中即是神仙地，引手何妨一釣鼇。"]', '诗', 'shi', '', NULL, '陳正字山居 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125cba28-01d4-43f8-b9b1-acdfb4f82e0d', '與劉三禮陳孝廉言志', '與劉三禮陳孝廉言志', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["真宰無私造化均，年年分散月中春。","皆期早躡青雲路，誰肯長爲白社人。","宋國高風休斂翼，聖朝公道易酬身。","大須審固穿楊箭，莫遣參差鬢雪新。"]', '["真宰無私造化均，年年分散月中春。","皆期早躡青云路，誰肯长爲白社人。","宋国高风休斂翼，聖朝公道易酬身。","大須審固穿楊箭，莫遣參差鬢雪新。"]', '诗', 'shi', '', NULL, '與劉三禮陳孝廉言志 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91e5f4da-754c-4268-a8e3-072da60ba37f', '秋日送嚴湘侍御歸京', '秋日送嚴湘侍御归京', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["蟾影珪圓湖始波，楚人相別恨偏多。","知君有路昇霄漢，獨我無由出薜蘿。","雖道危時難進取，到逢清世又如何。","誰聽甯戚敲牛角，月落星稀一曲歌。"]', '["蟾影珪圓湖始波，楚人相別恨偏多。","知君有路昇霄漢，独我無由出薜蘿。","雖道危时难進取，到逢清世又如何。","誰听甯戚敲牛角，月落星稀一曲歌。"]', '诗', 'shi', '', NULL, '秋日送嚴湘侍御歸京 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74451b27-b85a-4856-b4fe-86f45bbe545f', '題王處士山居', '題王处士山居', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["雲木沈沈夏亦寒，此中幽隱幾經年。","無多別業供王稅，大半生涯在釣船。","蜀魄呌迴芳草色，鷺鷥飛破夕陽煙。","干戈蝟起能高臥，只箇逍遙是謫仙。"]', '["云木沈沈夏亦寒，此中幽隐幾經年。","無多別業供王稅，大半生涯在釣船。","蜀魄呌迴芳草色，鷺鷥飞破夕陽煙。","干戈蝟起能高臥，只箇逍遙是謫仙。"]', '诗', 'shi', '', NULL, '題王處士山居 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64b089aa-cb0f-401b-9aab-2067825e8b52', '謝所知', '謝所知', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["狂歌狂舞慰風塵，心下多端亦嬾言。","早是亂離輕歲月，誰能愁悴過朝昏。","聖朝公道如長在，賤子謀身自有門。","却愧此時叨厚遇，他年何以報深恩。"]', '["狂歌狂舞慰风塵，心下多端亦嬾言。","早是亂離轻歲月，誰能愁悴過朝昏。","聖朝公道如长在，賤子謀身自有门。","却愧此时叨厚遇，他年何以報深恩。"]', '诗', 'shi', '', NULL, '謝所知 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ae7f452-3573-4dac-8db4-11f0d6c266c0', '秋望', '秋望', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["雲陰慘澹柳陰稀，遊子天涯一望時。","風閃雁行疎又密，地迴江勢急還遲。","榮枯物理終難測，貴賤人生自不知。","未達誰能多歎息，塵埃爭損得男兒。"]', '["云陰慘澹柳陰稀，游子天涯一望时。","风閃雁行疎又密，地迴江勢急還遲。","榮枯物理終难測，貴賤人生自不知。","未達誰能多歎息，塵埃爭損得男兒。"]', '诗', 'shi', '', NULL, '秋望 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3d2235-89e3-44f2-bd33-78817a0663f5', '送譚孝廉赴舉', '送譚孝廉赴舉', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["鼓鼙聲裏尋詩禮，戈戟林間入鎬京。","好事盡從難處得，少年無向易中輕。","也知貴賤皆前定，未見疎慵遂有成。","吾道近來稀後進，善開金口荅公卿。"]', '["鼓鼙声裏尋诗禮，戈戟林间入鎬京。","好事尽從难处得，少年無向易中轻。","也知貴賤皆前定，未见疎慵遂有成。","吾道近来稀後進，善开金口荅公卿。"]', '诗', 'shi', '', NULL, '送譚孝廉赴舉 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d30f3cb-bc81-4c58-a337-ebf6a7a5a038', '途中逢友人', '途中逢友人', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["大道將窮阮籍哀，紅塵深翳步遲迴。","皇天有意自寒暑，白日無情空往來。","霄漢何年徵賦客，煙花隨處作愁媒。","相逢且快眼前事，莫厭狂歌酒百杯。"]', '["大道將窮阮籍哀，紅塵深翳步遲迴。","皇天有意自寒暑，白日無情空往来。","霄漢何年徵賦客，煙花隨处作愁媒。","相逢且快眼前事，莫厭狂歌酒百杯。"]', '诗', 'shi', '', NULL, '途中逢友人 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('209f6854-65c7-49b4-bd58-4abe2f99bf6f', '和人湘中作', '和人湘中作', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["湘川湘岸兩荒涼，孤雁號空動旅腸。","一棹寒波思范蠡，滿尊醇酒憶陶唐。","年華蒲柳凋衰鬢，身跡萍蓬滯別鄉。","不及東流趨廣漢，臣心日夜與天長。"]', '["湘川湘岸兩荒涼，孤雁號空动旅腸。","一棹寒波思范蠡，满尊醇酒憶陶唐。","年华蒲柳凋衰鬢，身跡萍蓬滯別乡。","不及东流趨廣漢，臣心日夜與天长。"]', '诗', 'shi', '', NULL, '和人湘中作 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c10a1168-f269-43a4-98a9-4a809cd207fc', '贈陳望堯', '贈陳望堯', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["若說精通事藝長，詞人爭及孝廉郎。","秋螢短焰難盈案，鄰燭餘光不滿行。","鵠箭親疎雖異的，桂花高下一般香。","明時公道還堪信，莫遣錐鋒久在囊。"]', '["若说精通事藝长，词人爭及孝廉郎。","秋螢短焰难盈案，鄰燭餘光不满行。","鵠箭親疎雖異的，桂花高下一般香。","明时公道還堪信，莫遣錐鋒久在囊。"]', '诗', 'shi', '', NULL, '贈陳望堯 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('052aa241-7857-4f7d-bcf4-3f1aac9f5dd4', '宿漁家', '宿漁家', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["促杼聲繁螢影多，江邊秋興獨難過。","雲遮月桂幾枝恨，煙罩漁舟一曲歌。","難世斯人雖隱遁，明時公道復如何。","陶家壁上精靈物，風雨未來終是梭。"]', '["促杼声繁螢影多，江邊秋兴独难過。","云遮月桂幾枝恨，煙罩漁舟一曲歌。","难世斯人雖隐遁，明时公道复如何。","陶家壁上精靈物，风雨未来終是梭。"]', '诗', 'shi', '', NULL, '宿漁家 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82a1a80-0ef8-4327-b909-f7e9a884364d', '旅館秋夕', '旅館秋夕', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["牢落生涯在水鄉，只思歸去泛滄浪。","秋風螢影隨高柳，夜雨蛬聲上短牆。","百歲易爲成荏苒，丹霄誰肯借梯航。","若教名路無知己，匹馬塵中是自忙。"]', '["牢落生涯在水乡，只思归去泛滄浪。","秋风螢影隨高柳，夜雨蛬声上短牆。","百歲易爲成荏苒，丹霄誰肯借梯航。","若教名路無知己，匹马塵中是自忙。"]', '诗', 'shi', '', NULL, '旅館秋夕 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3091ce-59cc-44a4-ba92-8673a114b33a', '悼范攄處士', '悼范攄处士', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["家在五雲溪畔住，身遊巫峽作閑人。","安車未至柴關外，片玉已藏墳土新。","雖有公卿聞姓字，惜無知己脫風塵。","到頭積善成何事，天地茫茫秋又春。"]', '["家在五云溪畔住，身游巫峽作闲人。","安车未至柴关外，片玉已藏墳土新。","雖有公卿闻姓字，惜無知己脫风塵。","到头積善成何事，天地茫茫秋又春。"]', '诗', 'shi', '', NULL, '悼范攄處士 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e7c6b03-f6d5-4998-b653-0fc7d31abffd', '送人', '送人', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["一軸煙花滿口香，諸侯相見肯相忘。","未聞珪璧爲人棄，莫倦江山去路長。","盈耳暮蟬催別騎，數杯浮蟻咽離腸。","眼前多少難甘事，自古男兒當自強。"]', '["一軸煙花满口香，諸侯相见肯相忘。","未闻珪璧爲人棄，莫倦江山去路长。","盈耳暮蟬催別騎，數杯浮蟻咽離腸。","眼前多少难甘事，自古男兒當自強。"]', '诗', 'shi', '', NULL, '送人 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4210c74-a311-49ed-aa4c-6a97d6553958', '春暮途中', '春暮途中', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["細雨如塵散暖空，數峰春色在雲中。","須知觸目皆成恨，縱道多文爭那窮。","飛燕有情依舊閣，垂楊無力受東風。","誰能會得乾坤意，九土枯榮自不同。"]', '["細雨如塵散暖空，數峰春色在云中。","須知觸目皆成恨，縱道多文爭那窮。","飞燕有情依旧閣，垂楊無力受东风。","誰能會得乾坤意，九土枯榮自不同。"]', '诗', 'shi', '', NULL, '春暮途中 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78793102-a478-4ae8-a447-5f4ce25f846c', '題陳正字林亭', '題陳正字林亭', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["曉煙輕翠拂簾飛，黃葉飄零弄所思。","正是低摧吾道日，不堪惆悵異鄉時。","家林蛇豕方羣起，宮沼龜龍未有期。","賴有平原憐賤子，滿亭山色借吟詩。"]', '["晓煙轻翠拂簾飞，黄葉飄零弄所思。","正是低摧吾道日，不堪惆悵異乡时。","家林蛇豕方羣起，宮沼龟龙未有期。","賴有平原怜賤子，满亭山色借吟诗。"]', '诗', 'shi', '', NULL, '題陳正字林亭 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('948c0c60-ff9d-4a6e-a175-26e45d8d1ad1', '送從兄入京', '送從兄入京', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["柳轉春心梅豔香，相看江上恨何長。","多情流水引歸思，無賴嚴風促別觴。","大抵男兒須振奮，近來時事懶思量。","雲帆高挂一揮手，目送煙霄雁斷行。"]', '["柳轉春心梅豔香，相看江上恨何长。","多情流水引归思，無賴嚴风促別觴。","大抵男兒須振奮，近来时事懶思量。","云帆高挂一揮手，目送煙霄雁斷行。"]', '诗', 'shi', '', NULL, '送從兄入京 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6de302a-f94f-49c4-9955-9259a28a3f68', '秋夕書懷寄所知', '秋夕书懷寄所知', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["秋螢一點雨中飛，獨立黃昏思所知。","三島路遙身汩沒，九天風急羽差池。","年華逐浪催霜髪，旅恨和雲拂桂知。","不向故人言此事，異鄉誰更念棲遲。"]', '["秋螢一点雨中飞，独立黄昏思所知。","三島路遙身汩沒，九天风急羽差池。","年华逐浪催霜髪，旅恨和云拂桂知。","不向故人言此事，異乡誰更念棲遲。"]', '诗', 'shi', '', NULL, '秋夕書懷寄所知 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd77f37b-09c8-4862-860c-3454f47799f7', '酬進士秦顒若', '酬進士秦顒若', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["鶯默平林燕別軒，相逢相笑話生前。","低飛旅恨看霜葉，曲寫歸情向暮川。","在野孤雲終捧日，朝宗高浪本蒙泉。","何勞悵望風雷便，且混魚龍黷武年。"]', '["鶯默平林燕別軒，相逢相笑話生前。","低飞旅恨看霜葉，曲寫归情向暮川。","在野孤云終捧日，朝宗高浪本蒙泉。","何勞悵望风雷便，且混鱼龙黷武年。"]', '诗', 'shi', '', NULL, '酬進士秦顒若 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c995598e-1fef-45bf-afce-21f495a68375', '山中夜坐寄故里友生', '山中夜坐寄故里友生', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["展轉簷前睡不成，一牀山月竹風清。","蟲聲促促催鄉夢，桂影高高挂旅情。","禍福既能知倚伏，行藏爭不要分明。","可憐任永真堅白，淨洗雙眸看太平。"]', '["展轉簷前睡不成，一牀山月竹风清。","蟲声促促催乡梦，桂影高高挂旅情。","禍福既能知倚伏，行藏爭不要分明。","可怜任永真堅白，淨洗雙眸看太平。"]', '诗', 'shi', '', NULL, '山中夜坐寄故里友生 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0666b456-7af2-4b9e-b1e4-9f5413adbd8f', '物情', '物情', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["誰分萬類二儀間，稟性高卑各自然。","野鶴不棲蔥蒨樹，流鶯長喜豔陽天。","李斯溷鼠心應動，莊叟泥龜意已堅。"]', '["誰分万類二儀间，稟性高卑各自然。","野鹤不棲蔥蒨樹，流鶯长喜豔陽天。","李斯溷鼠心應动，莊叟泥龟意已堅。"]', '诗', 'shi', '', NULL, '物情 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69d79950-c3ac-4dd4-bb8e-9faa98b49c6a', '金谷園', '金谷园', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["石家舊地聊登望，寵辱從茲信可驚。","鳥度野花迷錦障，蟬吟古樹想歌聲。","雖將玉貌同時死，却羨蒼頭此日生。","多積黃金買刑戮，千秋成得綠珠名。"]', '["石家旧地聊登望，寵辱從茲信可驚。","鸟度野花迷錦障，蟬吟古樹想歌声。","雖將玉貌同时死，却羨蒼头此日生。","多積黄金買刑戮，千秋成得綠珠名。"]', '诗', 'shi', '', NULL, '金谷園 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8e7dbb-8843-4bdd-a96b-cbcb8769342b', '投所知', '投所知', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["手欠東堂桂一枝，家書不敢便言歸。","挂簷晚雨思山閣，拂岸煙嵐憶釣磯。","公道甚平才自薄，丹霄好上力猶微。","誰能借與摶扶勢，萬里飄飄試一飛。"]', '["手欠东堂桂一枝，家书不敢便言归。","挂簷晚雨思山閣，拂岸煙嵐憶釣磯。","公道甚平才自薄，丹霄好上力猶微。","誰能借與摶扶勢，万里飄飄試一飞。"]', '诗', 'shi', '', NULL, '投所知 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad50331-066f-4bbc-bb4e-8c4e3e2ea3fe', '贈友弟', '贈友弟', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["螢焰燒心雪眼勞，未逢佳夢見三刀。","他時詎有鹽梅味，今日猶疑腹背毛。","金埒曉羇千里駿，玉輪寒養一枝高。","誰能終歲搖頳尾，唯唯洋洋向碧濤。"]', '["螢焰燒心雪眼勞，未逢佳梦见三刀。","他时詎有鹽梅味，今日猶疑腹背毛。","金埒晓羇千里駿，玉輪寒養一枝高。","誰能終歲搖頳尾，唯唯洋洋向碧濤。"]', '诗', 'shi', '', NULL, '贈友弟 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc6847e2-8cbc-4c4e-a033-6a8b5b3a1859', '春日喜逢鄉人劉松', '春日喜逢乡人劉松', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["故人不見五春風，異地相逢嶽影中。","舊業久拋耕釣侶，新聞多說戰爭功。","生民有恨將誰訴，花木無情秪自紅。","莫把少年愁過日，一尊須對夕陽空。"]', '["故人不见五春风，異地相逢嶽影中。","旧業久拋耕釣侶，新闻多说戰爭功。","生民有恨將誰訴，花木無情秪自紅。","莫把少年愁過日，一尊須对夕陽空。"]', '诗', 'shi', '', NULL, '春日喜逢鄉人劉松 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efe38507-b079-4ba5-8d9a-bcb354b8f997', '夏日別余秀才', '夏日別余秀才', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["嶽麓雲深麥雨秋，滿傾杯酒對湘流。","沙邊細柳牽行色，水面輕煙畫別愁。","敢待傅巖成好夢，任從磻石挂纖鈎。","鏡機沖漠非吾事，自要青雲識五侯。"]', '["嶽麓云深麦雨秋，满傾杯酒对湘流。","沙邊細柳牽行色，水面轻煙畫別愁。","敢待傅巖成好梦，任從磻石挂纖鈎。","镜機沖漠非吾事，自要青云識五侯。"]', '诗', 'shi', '', NULL, '夏日別余秀才 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41baaaab-186e-4e02-a509-04a280ff65ac', '廬陵九日', '廬陵九日', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["菊花山在碧江東，冷酒清吟興莫窮。","四十三年秋裏過，幾多般事亂來空。","雖驚故國音書絕，猶喜新知語笑同。","竟日開門無客至，笛聲迢逓夕陽中。"]', '["菊花山在碧江东，冷酒清吟兴莫窮。","四十三年秋裏過，幾多般事亂来空。","雖驚故国音书絕，猶喜新知語笑同。","竟日开门無客至，笛声迢逓夕陽中。"]', '诗', 'shi', '', NULL, '廬陵九日 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b12b807-49a5-40b3-9490-96ac981e87d3', '和人遊東林', '和人游东林', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["一從張野臥雲林，勝概誰人更解尋。","黃鳥不能言往事，白蓮虛發至如今。","年年上國榮華夢，世世高流水石心。","始欲共君重悵望，紫霄峰外日沈沈。"]', '["一從張野臥云林，勝概誰人更解尋。","黄鸟不能言往事，白蓮虛發至如今。","年年上国榮华梦，世世高流水石心。","始欲共君重悵望，紫霄峰外日沈沈。"]', '诗', 'shi', '', NULL, '和人遊東林 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6587eda-dc75-4044-b031-3126116ac0f6', '和彭進士秋日遊靖居山寺', '和彭進士秋日游靖居山寺', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["秋山入望已無塵，況得閑遊謝事頻。","問著盡能言祖祖，見時應不是真真。","添瓶野水遮還急，伴塔幽花落又新。","自笑未曾同逸步，終非宗炳社中人。"]', '["秋山入望已無塵，況得闲游謝事頻。","问著尽能言祖祖，见时應不是真真。","添瓶野水遮還急，伴塔幽花落又新。","自笑未曾同逸步，終非宗炳社中人。"]', '诗', 'shi', '', NULL, '和彭進士秋日遊靖居山寺 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec90340-a1fe-4c02-9fc7-bf06b5767c08', '和彭進士感懷', '和彭進士感懷', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["人生誰肯便甘休，遇酒逢花且共遊。","若向雲衢陪驥尾，直須天畔落旄頭。","三編大雅曾關興，一冊南華旋解憂。","四海英雄多獨斷，不知何者是長籌。"]', '["人生誰肯便甘休，遇酒逢花且共游。","若向云衢陪驥尾，直須天畔落旄头。","三編大雅曾关兴，一冊南华旋解憂。","四海英雄多独斷，不知何者是长籌。"]', '诗', 'shi', '', NULL, '和彭進士感懷 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d19a4463-4990-490a-bc1c-320be0d652ac', '寄題從兄坤載村居', '寄題從兄坤載村居', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["鄰並無非樵釣者，莊生物論宛然齊。","雨中寒樹愁鴟立，江上殘陽瘦馬嘶。","說與衆傭同版築，呂將羣叟共磻溪。","覆巢破卵方堪懼，取次梧桐鳳且棲。"]', '["鄰並無非樵釣者，莊生物論宛然齊。","雨中寒樹愁鴟立，江上殘陽瘦马嘶。","说與衆傭同版築，呂將羣叟共磻溪。","覆巢破卵方堪懼，取次梧桐鳳且棲。"]', '诗', 'shi', '', NULL, '寄題從兄坤載村居 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ea38b1-4bf1-4852-a60f-2e62bb278139', '送黃賓于赴舉', '送黄賓于赴舉', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["秋風昨夜滿瀟湘，衰柳殘蟬思客腸。","早是亂來無勝事，更堪江上揖離觴。","澄潭躍鯉搖輕浪，落日飛鳧趁遠檣。","漁父不須探去意，一枝春褭月中央。"]', '["秋风昨夜满瀟湘，衰柳殘蟬思客腸。","早是亂来無勝事，更堪江上揖離觴。","澄潭躍鯉搖轻浪，落日飞鳧趁远檣。","漁父不須探去意，一枝春褭月中央。"]', '诗', 'shi', '', NULL, '送黃賓于赴舉 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bcb0fee-a4f0-4119-a840-44912947fdca', '冬日喜逢吳價', '冬日喜逢吳價', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["垂楊煙薄井梧空，千里遊人駐斷蓬。","志意不因多事改，鬢毛難與別時同。","鶯遷猶待銷冰日，鵬起還思動海風。","窮達他年如賦命，且陶真性一杯中。"]', '["垂楊煙薄井梧空，千里游人駐斷蓬。","志意不因多事改，鬢毛难與別时同。","鶯遷猶待銷冰日，鵬起還思动海风。","窮達他年如賦命，且陶真性一杯中。"]', '诗', 'shi', '', NULL, '冬日喜逢吳價 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76721884-eab0-4a51-899a-619a410b0fdd', '題劉處士居', '題劉处士居', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["壓破嵐光半畝餘，竹軒蘭砌共清虛。","泉經小檻聲長急，月過修篁影旋疎。","溪鳥時時窺戶牖，山雲往往宿庭除。","干戈謾道因天意，渭水高人自釣魚。"]', '["壓破嵐光半畝餘，竹軒蘭砌共清虛。","泉經小檻声长急，月過修篁影旋疎。","溪鸟时时窺戶牖，山云往往宿庭除。","干戈謾道因天意，渭水高人自釣鱼。"]', '诗', 'shi', '', NULL, '題劉處士居 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab6d601-d98b-465f-bed6-95de6d2bfbe9', '送李尊師歸臨川', '送李尊師归臨川', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["蟠桃一別幾千春，謫下人間作至人。","塵外煙霞吟不盡，鼎中龍虎伏初馴。","除存紫府無他意，終向青冥舉此身。","辭我麻姑山畔去，蔡經蹤跡必相親。"]', '["蟠桃一別幾千春，謫下人间作至人。","塵外煙霞吟不尽，鼎中龙虎伏初馴。","除存紫府無他意，終向青冥舉此身。","辞我麻姑山畔去，蔡經蹤跡必相親。"]', '诗', 'shi', '', NULL, '送李尊師歸臨川 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90a7228c-0203-469d-a757-f79899f4a0ba', '投知', '投知', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["西望長安路幾千，遲回不爲別家難。","酌量才地心雖動，點檢囊裝意又闌。","自是遠人多蹇滯，近來仙牓半孤寒。","嘶風重訴牽鹽恥，伯樂何妨轉眼看。"]', '["西望长安路幾千，遲回不爲別家难。","酌量才地心雖动，点檢囊裝意又闌。","自是远人多蹇滯，近来仙牓半孤寒。","嘶风重訴牽鹽恥，伯乐何妨轉眼看。"]', '诗', 'shi', '', NULL, '投知 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3985cfe-ee56-4b06-bd3c-310d5ee11bb3', '吳處士寄香兼勸入道', '吳处士寄香兼勸入道', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["謝寄精專一捻香，勸予朝禮仕虛皇。","須知十極皆臣妾，豈止遺生奉混茫。","空挂黃衣寧續壽，曾聞玄教在知常。","但居平易俟天命，便是長生不死鄉。"]', '["謝寄精專一捻香，勸予朝禮仕虛皇。","須知十極皆臣妾，豈止遺生奉混茫。","空挂黄衣寧續壽，曾闻玄教在知常。","但居平易俟天命，便是长生不死乡。"]', '诗', 'shi', '', NULL, '吳處士寄香兼勸入道 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a398735-4aa0-493a-b09d-5f9f1105fe4b', '草蟲', '草蟲', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["如繰如織暮㗀㗀，應節催年使我愁。","行客語停孤店月，高人夢斷一牀秋。","風低蘚徑疑偏急，雨咽槐亭得暫休。","須付畫堂蘭燭畔，歌懷醉耳兩悠悠。"]', '["如繰如织暮㗀㗀，應節催年使我愁。","行客語停孤店月，高人梦斷一牀秋。","风低蘚徑疑偏急，雨咽槐亭得暫休。","須付畫堂蘭燭畔，歌懷醉耳兩悠悠。"]', '诗', 'shi', '', NULL, '草蟲 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da3cefc6-f2e8-4f56-ad36-7f1de6437964', '詠柳', '詠柳', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["日近煙饒還有意，東垣西掖幾千株。","牽仍別恨知難盡，誇衒春光恐更無。","解引人情長婉約，巧隨風勢強盤紆。","天應繡出繁華景，處處茸絲惹路衢。"]', '["日近煙饒還有意，东垣西掖幾千株。","牽仍別恨知难尽，誇衒春光恐更無。","解引人情长婉約，巧隨风勢強盤紆。","天應繡出繁华景，处处茸絲惹路衢。"]', '诗', 'shi', '', NULL, '詠柳 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fac2f86-3808-453b-803b-3f5d3e2722f7', '寄所知', '寄所知', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["曾將俎豆爲兒戲，爭奈干戈阻素心。","遁去不同秦客逐，病來還作越人吟。","名流古集典衣買，僻寺奇花貰酒尋。","從道趣時身計拙，如非所好肯開襟。"]', '["曾將俎豆爲兒戲，爭奈干戈阻素心。","遁去不同秦客逐，病来還作越人吟。","名流古集典衣買，僻寺奇花貰酒尋。","從道趣时身計拙，如非所好肯开襟。"]', '诗', 'shi', '', NULL, '寄所知 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b71846e-8e13-439b-b1aa-7580b8b9f9fa', '雪', '雪', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["上帝無私意甚微，欲教霖雨更光輝。","也知出處花相似，可到貧家影便稀。","雲漢風多銀浪濺，崑山火後玉灰飛。","高樓四望吟魂斂，却憶明皇月殿歸。"]', '["上帝無私意甚微，欲教霖雨更光輝。","也知出处花相似，可到貧家影便稀。","云漢风多銀浪濺，崑山火後玉灰飞。","高楼四望吟魂斂，却憶明皇月殿归。"]', '诗', 'shi', '', NULL, '雪 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36d2231e-be26-4876-b0ef-13c830e97c3b', '緋桃花', '緋桃花', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["茫茫天意爲誰留，深染夭桃備勝遊。","未醉已知醒後憶，欲開先爲落時愁。","癡蛾亂撲燈難滅，躍鯉傍驚電不收。","何事梨花空似雪，也稱春色是悠悠。"]', '["茫茫天意爲誰留，深染夭桃備勝游。","未醉已知醒後憶，欲开先爲落时愁。","癡蛾亂撲灯难滅，躍鯉傍驚電不收。","何事梨花空似雪，也稱春色是悠悠。"]', '诗', 'shi', '', NULL, '緋桃花 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6644c8b3-782a-4a91-8b9e-1eac1cb6f12c', '同友人秋日登庾樓', '同友人秋日登庾楼', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["蘭摧菊暗不勝秋，倚著高樓思莫收。","六代風光無問處，九條煙水但凝愁。","誰能百歲長閑去，秪箇孤帆豈自由。","欲學仲宣知是否，臂弓腰劍逐時流。"]', '["蘭摧菊暗不勝秋，倚著高楼思莫收。","六代风光無问处，九條煙水但凝愁。","誰能百歲长闲去，秪箇孤帆豈自由。","欲学仲宣知是否，臂弓腰劍逐时流。"]', '诗', 'shi', '', NULL, '同友人秋日登庾樓 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f48e71d-3783-4c0c-a66c-450dea55d1d4', '和人詠雪', '和人詠雪', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["輕輕玉疊向風加，襟袖誰能認六葩。","高岫人迷千尺布，平林天與一般花。","橫空絡繹雲遺屑，撲浪翩聯蝶寄槎。"]', '["轻轻玉叠向风加，襟袖誰能認六葩。","高岫人迷千尺布，平林天與一般花。","橫空絡繹云遺屑，撲浪翩聯蝶寄槎。"]', '诗', 'shi', '', NULL, '和人詠雪 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2515bdbf-6c1a-4c24-b5e3-7ff748c8637d', '和友人喜相遇十首 一', '和友人喜相遇十首 一', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["爲儒自愧已多年，文賦歌詩路不專。","肯信披沙難見寶，只憐苫草易成編。","燕昭寤寐常求駿，郭隗尋思未是賢。","且固初心希一試，箭穿正鵠豈無緣。"]', '["爲儒自愧已多年，文賦歌诗路不專。","肯信披沙难见寶，只怜苫草易成編。","燕昭寤寐常求駿，郭隗尋思未是賢。","且固初心希一試，箭穿正鵠豈無緣。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 一 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97fc5305-98c0-47b7-9f79-dc04792bd816', '和友人喜相遇十首 二', '和友人喜相遇十首 二', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["揣情摩意已無功，只把篇章助國風。","宋玉謾誇雲雨會，謝連寧許夢魂通。","愁成旅鬢千絲亂，吟得寒缸短焰終。","難世好居郊野地，出門常喜與人同。"]', '["揣情摩意已無功，只把篇章助国风。","宋玉謾誇云雨會，謝連寧許梦魂通。","愁成旅鬢千絲亂，吟得寒缸短焰終。","难世好居郊野地，出门常喜與人同。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 二 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f35ca8f-b01e-41f8-b894-b19abf0e5179', '和友人喜相遇十首 三', '和友人喜相遇十首 三', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["惠子休驚學五車，沛公方起斬長蛇。","六雄互欲吞諸國，四海終須作一家。","自古經綸成世務，暫時朱綠比朝霞。","人生心口宜相副，莫使堯階草勢斜。"]', '["惠子休驚学五车，沛公方起斬长蛇。","六雄互欲吞諸国，四海終須作一家。","自古經綸成世務，暫时朱綠比朝霞。","人生心口宜相副，莫使堯階草勢斜。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 三 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d6a37a7-f911-4c0a-b6d2-bba42aa374d8', '和友人喜相遇十首 四', '和友人喜相遇十首 四', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["不傍江煙訪所思，更應無處展愁眉。","數杯竹閣花殘酒，一局松窗日午碁。","多病却疑天與便，自愚潛喜衆相欺。","非窮非達非高尚，冷笑行藏秪獨知。"]', '["不傍江煙訪所思，更應無处展愁眉。","數杯竹閣花殘酒，一局松窗日午碁。","多病却疑天與便，自愚潛喜衆相欺。","非窮非達非高尚，冷笑行藏秪独知。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 四 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d5a26cf-e3e6-48e9-9167-8ae2e35ca957', '和友人喜相遇十首 五', '和友人喜相遇十首 五', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["閑吟閑坐道相應，遠想南華亦自矜。","拋擲家鄉輕似夢，尋常心地冷於僧。","和羹使用非胥靡，憶鱠言詞小季鷹。","唯仗十篇金玉韻，此中高旨莫階升。"]', '["闲吟闲坐道相應，远想南华亦自矜。","拋擲家乡轻似梦，尋常心地冷於僧。","和羹使用非胥靡，憶鱠言词小季鷹。","唯仗十篇金玉韻，此中高旨莫階升。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 五 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b34f8cde-a7c4-4ea5-b692-f75855cb5511', '和友人喜相遇十首 六', '和友人喜相遇十首 六', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["已向丘門老此軀，可堪空作小人儒。","吟中景象千般有，書外囊裝一物無。","潤屋必能知早散，輝山應是不輕沽。","短衣寧倦重修謁，誰識高陽舊酒徒。"]', '["已向丘门老此軀，可堪空作小人儒。","吟中景象千般有，书外囊裝一物無。","潤屋必能知早散，輝山應是不轻沽。","短衣寧倦重修謁，誰識高陽旧酒徒。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 六 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a234084-1e40-48d2-972c-da2c28c09dba', '和友人喜相遇十首 七', '和友人喜相遇十首 七', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["松桂寒多衆木分，輕浮如葉自紛紜。","韶咸古曲教誰愛，山水清音喜獨聞。","上國共知傳大寶，舊交寧復在青雲。","相逢莫厭杯中酒，同醉同醒秪有君。"]', '["松桂寒多衆木分，轻浮如葉自紛紜。","韶咸古曲教誰愛，山水清音喜独闻。","上国共知傳大寶，旧交寧复在青云。","相逢莫厭杯中酒，同醉同醒秪有君。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 七 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b0319d5-b430-485e-86f9-a959e3d01e91', '和友人喜相遇十首 八', '和友人喜相遇十首 八', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["還淳反朴已難期，依德依仁敢暫違。","寡欲自應剛正立，無私翻覺友朋稀。","旄頭影莫侵黃道，傅說星終近紫微。","年紀少他蘧伯玉，幸因多難早知非。"]', '["還淳反朴已难期，依德依仁敢暫違。","寡欲自應剛正立，無私翻覺友朋稀。","旄头影莫侵黄道，傅说星終近紫微。","年紀少他蘧伯玉，幸因多难早知非。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 八 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9205aa66-906c-48fe-8f50-c297bc508283', '和友人喜相遇十首 九', '和友人喜相遇十首 九', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["麻衣未識帝城塵，四十爲儒是病身。","有恨不關銜國恥，無愁直爲倚家貧。","齊輕東海二高士，漢重商山四老人。","一種愛閑閑不得，混時行止却應真。"]', '["麻衣未識帝城塵，四十爲儒是病身。","有恨不关銜国恥，無愁直爲倚家貧。","齊轻东海二高士，漢重商山四老人。","一種愛闲闲不得，混时行止却應真。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 九 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de117886-eef6-490e-bb04-4eb0e1d58232', '和友人喜相遇十首 十', '和友人喜相遇十首 十', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["任說天長海影沈，友朋情比未爲深。","唯應樂處無虛日，大半危時得道心。","命達夭殤同白首，價高甎瓦即黃金。","他年有要玄珠者，赤水縈紆試一尋。"]', '["任说天长海影沈，友朋情比未爲深。","唯應乐处無虛日，大半危时得道心。","命達夭殤同白首，價高甎瓦即黄金。","他年有要玄珠者，赤水縈紆試一尋。"]', '诗', 'shi', '', NULL, '和友人喜相遇十首 十 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67c7423b-14be-44f2-bddc-bfa358422cea', '依韻修睦上人山居十首 一', '依韻修睦上人山居十首 一', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["生身便在亂離間，遇柳尋花作麽看。","老去轉諳無是事，本來何處有多般。","長憐蠛蠓能隨暖，獨笑梧桐不耐寒。","覆載我徒爭會得，大鵬飛尚未知寬。"]', '["生身便在亂離间，遇柳尋花作麽看。","老去轉諳無是事，本来何处有多般。","长怜蠛蠓能隨暖，独笑梧桐不耐寒。","覆載我徒爭會得，大鵬飞尚未知寬。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 一 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee945d0-c713-442f-b914-123d6ec0dd6b', '依韻修睦上人山居十首 二', '依韻修睦上人山居十首 二', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["雲泉日日長松寺，絲管年年細柳營。","靜躁殊途知自識，榮枯一貫亦何爭。","道傍病樹人從老，溪上新苔我獨行。","若見淨名居士語，逍遙全不讓莊生。"]', '["云泉日日长松寺，絲管年年細柳營。","静躁殊途知自識，榮枯一貫亦何爭。","道傍病樹人從老，溪上新苔我独行。","若见淨名居士語，逍遙全不讓莊生。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 二 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('479b6c5c-d1f0-4d28-a6f6-772e1c275ea7', '依韻修睦上人山居十首 三', '依韻修睦上人山居十首 三', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["莫言天道終難定，須信人心盡自輕。","宣室三千雖有恨，成周八百豈無情。","栢緣執性長時瘦，梅爲多知兩番生。","不是不同明主意，嬾將脣舌與齊烹。"]', '["莫言天道終难定，須信人心尽自轻。","宣室三千雖有恨，成周八百豈無情。","栢緣執性长时瘦，梅爲多知兩番生。","不是不同明主意，嬾將脣舌與齊烹。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 三 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4843e4-1757-4ca8-a9f8-20e43aa297dc', '依韻修睦上人山居十首 四', '依韻修睦上人山居十首 四', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["不論軒冕及漁樵，性與情違漸漸遙。","季子禍從憐富貴，顏生道在樂簞瓢。","清閑自可齊三壽，忿恨還須戒一朝。","好學堯民偎舜日，短裁孤竹理雲韶。"]', '["不論軒冕及漁樵，性與情違漸漸遙。","季子禍從怜富貴，顏生道在乐簞瓢。","清闲自可齊三壽，忿恨還須戒一朝。","好学堯民偎舜日，短裁孤竹理云韶。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 四 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ad8e520-0ef3-4eca-8a5c-5792a9133a72', '依韻修睦上人山居十首 五', '依韻修睦上人山居十首 五', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["春風春雨一何頻，望極空江覺損神。","鶯有來由重入谷，柳無情緒強依人。","漢庭謁者休言事，魯國諸生莫問津。","賴是水鄉樗櫟賤，滿爐紅焰且相親。"]', '["春风春雨一何頻，望極空江覺損神。","鶯有来由重入谷，柳無情緒強依人。","漢庭謁者休言事，魯国諸生莫问津。","賴是水乡樗櫟賤，满爐紅焰且相親。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 五 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eefbb5ce-bebf-48bf-b2bb-9a9b0079e8f1', '依韻修睦上人山居十首 六', '依韻修睦上人山居十首 六', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["三十年來要自觀，履春冰恐未爲難。","自於南國同埋劍，誰向東門便挂冠。","早是人情飛絮薄，可堪時令太行寒。","多慙幸住匡山下，偷得穠嵐坐臥看。"]', '["三十年来要自观，履春冰恐未爲难。","自於南国同埋劍，誰向东门便挂冠。","早是人情飞絮薄，可堪时令太行寒。","多慙幸住匡山下，偷得穠嵐坐臥看。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 六 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38e2f261-c0dd-47f2-90d3-e24d8f8f343e', '依韻修睦上人山居十首 七', '依韻修睦上人山居十首 七', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["畹蘭未必因香折，湖象多應爲齒焚。","兼濟直饒同巨楫，自由何似學孤雲。","秋深櫟菌樵來得，木末山鼯夢斷聞。","閑凭竹軒游子過，替他愁見日西曛。"]', '["畹蘭未必因香折，湖象多應爲齒焚。","兼濟直饒同巨楫，自由何似学孤云。","秋深櫟菌樵来得，木末山鼯梦斷闻。","闲凭竹軒游子過，替他愁见日西曛。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 七 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc30e28-7c46-4501-abc6-33696c4e9501', '依韻修睦上人山居十首 八', '依韻修睦上人山居十首 八', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["何事深山嘯復歌，短弓長劍不如他。","且圖青史垂名穩，從道前賢自滯多。","𩿪鷃敢辭栖短棘，鳳凰猶解怯高羅。","人生若得逢堯舜，便是巢由亦易過。"]', '["何事深山嘯复歌，短弓长劍不如他。","且圖青史垂名穩，從道前賢自滯多。","𩿪鷃敢辞栖短棘，鳳凰猶解怯高羅。","人生若得逢堯舜，便是巢由亦易過。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 八 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa7d5892-194f-45cf-936b-2f0134466487', '依韻修睦上人山居十首 九', '依韻修睦上人山居十首 九', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["太玄太易小窗明，古義尋來醉復醒。","西伯縱逢頭已白，步兵如在眼應青。","寒猿斷後雲爲檻，宿鳥驚時月滿庭。","此景得閑閑去得，人間無事不曾經。"]', '["太玄太易小窗明，古義尋来醉复醒。","西伯縱逢头已白，步兵如在眼應青。","寒猿斷後云爲檻，宿鸟驚时月满庭。","此景得闲闲去得，人间無事不曾經。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 九 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e867cb6-829b-4db8-bf67-757197a5547b', '依韻修睦上人山居十首 十', '依韻修睦上人山居十首 十', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["壯氣雖同德不同，項王何似王江東。","鄉歌寂寂荒丘月，漁艇年年古渡風。","難世斯人猶不達，此時吾道豈能通。","吟君十首山中作，方覺多端總是空。"]', '["壯氣雖同德不同，項王何似王江东。","乡歌寂寂荒丘月，漁艇年年古渡风。","难世斯人猶不達，此时吾道豈能通。","吟君十首山中作，方覺多端總是空。"]', '诗', 'shi', '', NULL, '依韻修睦上人山居十首 十 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38d0b6eb-1aa5-48c2-9b0c-e1df8846aa61', '同友生春夜闻雨', '同友生春夜闻雨', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["春雨三更洗物華，亂和絲竹響豪家。","滴繁知在長條柳，點重愁看破朵花。","簷靜尚疑兼霧細，燈搖應是逐風斜。","此時童叟渾無夢，爲喜流膏潤穀芽。"]', '["春雨三更洗物华，亂和絲竹响豪家。","滴繁知在长條柳，点重愁看破朵花。","簷静尚疑兼霧細，灯搖應是逐风斜。","此时童叟渾無梦，爲喜流膏潤穀芽。"]', '诗', 'shi', '', NULL, '同友生春夜闻雨 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('569a716c-63e8-4db7-bb8d-dcad39b28a79', '同友生题僧院杜鹃花', '同友生题僧院杜鹃花', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["若比衆芳應有在，難同上品是中春。","牡丹爲性疎南國，朱槿操心不滿旬。","留得却緣真達者，見來寧作獨醒人。","鶴林太盛今空地，莫放枝條出四鄰。"]', '["若比衆芳應有在，难同上品是中春。","牡丹爲性疎南国，朱槿操心不满旬。","留得却緣真達者，见来寧作独醒人。","鹤林太盛今空地，莫放枝條出四鄰。"]', '诗', 'shi', '', NULL, '同友生题僧院杜鹃花 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81809a97-7b71-43d9-b357-b31cf5547b1d', '春日題陈正字林亭', '春日題陈正字林亭', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["周迴勝異似仙鄉，稍減愁人日月長。","幕繞虛簷高岫色，鏡臨危檻小池光。","絲垂楊柳當風軟，玉折含桃倚徑香。","南北近來多少事，數聲橫笛怨斜陽。"]', '["周迴勝異似仙乡，稍減愁人日月长。","幕繞虛簷高岫色，镜臨危檻小池光。","絲垂楊柳當风軟，玉折含桃倚徑香。","南北近来多少事，數声橫笛怨斜陽。"]', '诗', 'shi', '', NULL, '春日題陈正字林亭 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f05788dd-f54b-4f13-8d9c-5047582c056d', '送河南韋主簿歸京', '送河南韋主簿归京', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["巖風愛日淚闌干，去住情途各萬端。","世亂敢言離別易，時清猶道路行難。","舟維晚雨湘川暗，袖拂晴嵐峴首寒。","見說滿朝親友在，肯教憔悴出長安。"]', '["巖风愛日泪闌干，去住情途各万端。","世亂敢言離別易，时清猶道路行难。","舟維晚雨湘川暗，袖拂晴嵐峴首寒。","见说满朝親友在，肯教憔悴出长安。"]', '诗', 'shi', '', NULL, '送河南韋主簿歸京 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b32e2b62-59de-4268-99de-e4e54adc0082', '喻道', '喻道', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["漢武秦皇漫苦辛，那思俗骨本含真。","不知流水潛催老，未悟三山也是塵。","牢落沙丘終古恨，寂寥函谷萬年春。","長生客待仙桃餌，月裏嬋娟笑煞人。"]', '["漢武秦皇漫苦辛，那思俗骨本含真。","不知流水潛催老，未悟三山也是塵。","牢落沙丘終古恨，寂寥函谷万年春。","长生客待仙桃餌，月裏嬋娟笑煞人。"]', '诗', 'shi', '', NULL, '喻道 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc190344-6143-4e56-ada7-38a2fa786587', '山中', '山中', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["一簇煙霞榮辱外，秋山留得傍簷楹。","朝鐘暮鼓不到耳，明月孤雲長挂情。","世上路岐何繚繞，水邊蓑笠稱平生。","尋思阮籍當時意，豈是途窮泣利名。"]', '["一簇煙霞榮辱外，秋山留得傍簷楹。","朝鐘暮鼓不到耳，明月孤云长挂情。","世上路岐何繚繞，水邊蓑笠稱平生。","尋思阮籍當时意，豈是途窮泣利名。"]', '诗', 'shi', '', NULL, '山中 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49b15831-23fa-46b2-bf4c-3491f3cae37a', '同玄昶上人觀山榴', '同玄昶上人观山榴', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["病隨支遁偶行行，正見榴花獨滿庭。","瘦竹成林人不看，却應著得強青青。"]', '["病隨支遁偶行行，正见榴花独满庭。","瘦竹成林人不看，却應著得強青青。"]', '诗', 'shi', '', NULL, '同玄昶上人觀山榴 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60f8f9bd-f65a-41ef-a1f8-63b87bab7e5c', '別李將軍', '別李將軍', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["一拜虬髭便受恩，宮門細柳五搖春。","男兒自古多離別，嬾對英雄淚滿巾。"]', '["一拜虬髭便受恩，宮门細柳五搖春。","男兒自古多離別，嬾对英雄泪满巾。"]', '诗', 'shi', '', NULL, '別李將軍 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95cc2ecb-9577-425b-9684-c0f7295433f3', '早雞', '早雞', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["錦翅朱冠驚四鄰，稻粱恩重職司晨。","不知下土兵難戢，但報明時向國人。"]', '["錦翅朱冠驚四鄰，稻粱恩重職司晨。","不知下土兵难戢，但報明时向国人。"]', '诗', 'shi', '', NULL, '早雞 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1855f407-6e57-422e-961a-101e4afefbf3', '別友', '別友', 'f9e0f6a1-7146-4c74-a533-a0a2eeee6c6c', '唐', '["北吹微微動旅情，不堪分手在平明。","寒雞不待東方曙，喚起征人蹋月行。"]', '["北吹微微动旅情，不堪分手在平明。","寒雞不待东方曙，喚起征人蹋月行。"]', '诗', 'shi', '', NULL, '別友 李咸用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9ae0a4-2abb-464c-b83d-37cc48e06f4e', '草檄荅南蠻有詠', '草檄荅南蠻有詠', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["辭天出塞陣雲空，霧捲霞開萬里通。","親受虎符安宇宙，誓將龍劍定英雄。","殘霜敢冒高懸日，秋葉爭禁大段風。","爲報南蠻須屏跡，不同蜀將武侯功。"]', '["辞天出塞陣云空，霧捲霞开万里通。","親受虎符安宇宙，誓將龙劍定英雄。","殘霜敢冒高懸日，秋葉爭禁大段风。","爲報南蠻須屏跡，不同蜀將武侯功。"]', '诗', 'shi', '', NULL, '草檄荅南蠻有詠 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae41726-a7fd-4584-8f16-0b4e6c3b56dc', '寒食都門作', '寒食都门作', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["二年寒食住京華，寓目春風萬萬家。","金絡馬銜原上草，玉顏人折路傍花。","軒車競出紅塵合，冠蓋爭回白日斜。","誰念都門兩行淚，故園寥落在長沙。"]', '["二年寒食住京华，寓目春风万万家。","金絡马銜原上草，玉顏人折路傍花。","軒车競出紅塵合，冠蓋爭回白日斜。","誰念都门兩行泪，故园寥落在长沙。"]', '诗', 'shi', '', NULL, '寒食都門作 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc1674ca-58bd-4777-aadf-5f95fa66024d', '薄命妾', '薄命妾', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["阿嬌初失漢皇恩，舊賜羅衣亦罷薰。","倚枕夜悲金屋雨，卷簾朝泣玉樓雲。","宮前葉落鴛鴦瓦，架上塵生翡翠裙。","龍騎不巡時漸久，長門空掩綠苔紋。"]', '["阿嬌初失漢皇恩，旧賜羅衣亦罷薰。","倚枕夜悲金屋雨，卷簾朝泣玉楼云。","宮前葉落鴛鴦瓦，架上塵生翡翠裙。","龙騎不巡时漸久，长门空掩綠苔紋。"]', '诗', 'shi', '', NULL, '薄命妾 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35e79af8-d41e-4ad4-949c-83f851a13447', '獨不見', '独不见', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["玉關一自有氛埃，年少從軍竟未回。","門外塵凝張樂榭，水邊香滅按歌臺。","窗殘夜月人何處，簾卷春風燕復來。","萬里寂寥音信絕，寸心爭忍不成灰。"]', '["玉关一自有氛埃，年少從軍竟未回。","门外塵凝張乐榭，水邊香滅按歌台。","窗殘夜月人何处，簾卷春风燕复来。","万里寂寥音信絕，寸心爭忍不成灰。"]', '诗', 'shi', '', NULL, '獨不見 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0bd863f-b9ef-4cfa-bd67-f67b817fd7c4', '交河塞下曲', '交河塞下曲', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["交河冰薄日遲遲，漢將思家感別離。","塞北草生蘇武泣，隴西雲起李陵悲。","曉侵雉堞烏先覺，春入關山雁獨知。","何處疲兵心最苦，夕陽樓上笛聲時。"]', '["交河冰薄日遲遲，漢將思家感別離。","塞北草生蘇武泣，隴西云起李陵悲。","晓侵雉堞烏先覺，春入关山雁独知。","何处疲兵心最苦，夕陽楼上笛声时。"]', '诗', 'shi', '', NULL, '交河塞下曲 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45f4448e-7f26-41ff-a75f-91dfbdd58c04', '車遙遙', '车遙遙', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["自從車馬出門朝，便入空房守寂寥。","玉枕夜殘魚信絕，金鈿秋盡雁書遙。","臉邊楚雨臨風落，頭上春雲向日銷。","芳草又衰還不至，碧天霜冷轉無憀。"]', '["自從车马出门朝，便入空房守寂寥。","玉枕夜殘鱼信絕，金鈿秋尽雁书遙。","臉邊楚雨臨风落，头上春云向日銷。","芳草又衰還不至，碧天霜冷轉無憀。"]', '诗', 'shi', '', NULL, '車遙遙 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dc9c736-e1a5-45f3-acc2-159d869223c8', '早發潛水驛謁郎中員外', '早發潛水驛謁郎中員外', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["半床秋月一聲雞，萬里行人費馬蹄。","青野霧銷凝晉洞，碧山煙散避秦溪。","樓臺稍辨烏城外，更漏微聞鶴柱西。","已是大仙憐後進，不應來向武陵迷。"]', '["半床秋月一声雞，万里行人費马蹄。","青野霧銷凝晉洞，碧山煙散避秦溪。","楼台稍辨烏城外，更漏微闻鹤柱西。","已是大仙怜後進，不應来向武陵迷。"]', '诗', 'shi', '', NULL, '早發潛水驛謁郎中員外 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d7c0f89-a723-4026-bdde-23983426ad0a', '贈漁者', '贈漁者', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["不媿人間萬戶侯，子孫相繼老扁舟。","往來南越諳鮫室，生長東吳識蜃樓。","自爲釣竿能遣悶，不因萱草解銷憂。","羨君獨得逃名趣，身外無機任白頭。"]', '["不媿人间万戶侯，子孫相繼老扁舟。","往来南越諳鮫室，生长东吳識蜃楼。","自爲釣竿能遣悶，不因萱草解銷憂。","羨君独得逃名趣，身外無機任白头。"]', '诗', 'shi', '', NULL, '贈漁者 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd000a6-22f5-4b17-8fd7-7e4b2b27bc9c', '自嶺下泛鷁到清遠峽作', '自嶺下泛鷁到清远峽作', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["乘船浮鷁下韶水，絕境方知在嶺南。","薜荔雨餘山自黛，蒹葭煙盡島如藍。","旦遊蕭帝新松寺，夜宿嫦娥桂影潭。","不爲篋中書未獻，便來茲地結茅庵。"]', '["乘船浮鷁下韶水，絕境方知在嶺南。","薜荔雨餘山自黛，蒹葭煙尽島如藍。","旦游蕭帝新松寺，夜宿嫦娥桂影潭。","不爲篋中书未獻，便来茲地結茅庵。"]', '诗', 'shi', '', NULL, '自嶺下泛鷁到清遠峽作 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86a6d290-78c5-49da-afa7-0f7790b20f52', '題周瑜將軍廟', '題周瑜將軍廟', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["共說生前國步難，山川龍戰血漫漫。","交鋒魏帝旌旂退，委任君王社稷安。","庭際雨餘春草長，廟前風起晚光殘。","功勳碑碣今何在，不得當時一字看。"]', '["共说生前国步难，山川龙戰血漫漫。","交鋒魏帝旌旂退，委任君王社稷安。","庭際雨餘春草长，廟前风起晚光殘。","功勳碑碣今何在，不得當时一字看。"]', '诗', 'shi', '', NULL, '題周瑜將軍廟 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9be03bf0-0236-475b-a9ce-6d39fd2a36c3', '詠史詩 烏江', '詠史诗 烏江', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["爭帝圖王勢已傾，八千兵散楚歌聲。","烏江不是無船渡，耻向東吳再起兵。"]', '["爭帝圖王勢已傾，八千兵散楚歌声。","烏江不是無船渡，耻向东吳再起兵。"]', '诗', 'shi', '', NULL, '詠史詩 烏江 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba01bb4b-8467-47d4-889a-052a319dfa36', '詠史詩 章華臺', '詠史诗 章华台', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["茫茫衰草沒章華，因笑靈王昔好奢。","臺土未乾簫管絕，可憐身死野人家。"]', '["茫茫衰草沒章华，因笑靈王昔好奢。","台土未乾簫管絕，可怜身死野人家。"]', '诗', 'shi', '', NULL, '詠史詩 章華臺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6127d65-19b9-491b-9107-11a56b13b928', '詠史詩 細腰宮', '詠史诗 細腰宮', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["楚王辛苦戰無功，國破城荒霸業空。","唯有青春花上露，至今猶泣細腰宮。"]', '["楚王辛苦戰無功，国破城荒霸業空。","唯有青春花上露，至今猶泣細腰宮。"]', '诗', 'shi', '', NULL, '詠史詩 細腰宮 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec71d17-e6ad-4c45-b571-5134d4e7458e', '詠史詩 沙苑', '詠史诗 沙苑', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["馮翊南邊宿霧開，行人一步一裴回。","誰知此地凋殘柳，盡是高歡敗後栽。"]', '["馮翊南邊宿霧开，行人一步一裴回。","誰知此地凋殘柳，尽是高歡敗後栽。"]', '诗', 'shi', '', NULL, '詠史詩 沙苑 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c5e1c1-f4c3-4692-b44f-e5a116afdb19', '詠史詩 石城', '詠史诗 石城', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["古郢雲開白雪樓，漢江還遶石城流。","何人知道寥天月，曾向朱門送莫愁。"]', '["古郢云开白雪楼，漢江還遶石城流。","何人知道寥天月，曾向朱门送莫愁。"]', '诗', 'shi', '', NULL, '詠史詩 石城 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dd73032-2ef8-48c8-93e8-8b3326a017cc', '詠史詩 荆山', '詠史诗 荆山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["抱玉巖前桂葉稠，碧谿寒水至今流。","空山落日猨聲呌，疑是荆人哭未休。"]', '["抱玉巖前桂葉稠，碧谿寒水至今流。","空山落日猨声呌，疑是荆人哭未休。"]', '诗', 'shi', '', NULL, '詠史詩 荆山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eda8769-bf1a-4258-9ca5-99376201d334', '詠史詩 陽臺', '詠史诗 陽台', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["楚國城池颯已空，陽臺雲雨過無蹤。","何人更有襄王夢，寂寂巫山十二重。"]', '["楚国城池颯已空，陽台云雨過無蹤。","何人更有襄王梦，寂寂巫山十二重。"]', '诗', 'shi', '', NULL, '詠史詩 陽臺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('046d4c27-7171-4f85-88e7-5923a7808afa', '詠史詩 居延', '詠史诗 居延', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漠漠平沙際碧天，問人云此是居延。","停驂一顧猶魂斷，蘇武爭禁十九年。"]', '["漠漠平沙際碧天，问人云此是居延。","停驂一顧猶魂斷，蘇武爭禁十九年。"]', '诗', 'shi', '', NULL, '詠史詩 居延 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ae5a7a4-e02b-443c-b050-0ab1a7d3a7a2', '詠史詩 沛宮', '詠史诗 沛宮', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漢高辛苦事干戈，帝業興隆俊傑多。","猶恨四方無壯士，還鄉悲唱大風歌。"]', '["漢高辛苦事干戈，帝業兴隆俊傑多。","猶恨四方無壯士，還乡悲唱大风歌。"]', '诗', 'shi', '', NULL, '詠史詩 沛宮 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd524620-da2e-4fab-ba67-458663653482', '詠史詩 金谷園', '詠史诗 金谷园', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["一自佳人墜玉樓，繁華東逐洛河流。","唯餘金谷園中樹，殘日蟬聲送客愁。"]', '["一自佳人墜玉楼，繁华东逐洛河流。","唯餘金谷园中樹，殘日蟬声送客愁。"]', '诗', 'shi', '', NULL, '詠史詩 金谷園 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a0dd46d-7850-4a95-8605-1afe728da203', '詠史詩 湘川', '詠史诗 湘川', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["虞舜南捐萬乘君，靈妃揮涕竹成紋。","不知精魄遊何處，落日瀟湘空白雲。"]', '["虞舜南捐万乘君，靈妃揮涕竹成紋。","不知精魄游何处，落日瀟湘空白云。"]', '诗', 'shi', '', NULL, '詠史詩 湘川 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b5d6e31-5080-4f0c-a097-8c52005bf87c', '詠史詩 夷門', '詠史诗 夷门', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["六龍冉冉驟朝昏，魏國賢才杳不存。","唯有侯嬴在時月，夜來空自照夷門。"]', '["六龙冉冉驟朝昏，魏国賢才杳不存。","唯有侯嬴在时月，夜来空自照夷门。"]', '诗', 'shi', '', NULL, '詠史詩 夷門 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc59a6ad-308e-4feb-a73f-2bfbb85b3604', '詠史詩 黃金臺', '詠史诗 黄金台', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["北乘羸馬到燕然，此地何人復禮賢。","若問昭王無處所，黃金臺上草連天。"]', '["北乘羸马到燕然，此地何人复禮賢。","若问昭王無处所，黄金台上草連天。"]', '诗', 'shi', '', NULL, '詠史詩 黃金臺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f797a4d-cb71-443e-80c7-ab7b7e894872', '詠史詩 夷陵', '詠史诗 夷陵', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["夷陵城闕倚朝雲，戰敗秦師縱火焚。","何事三千珠履客，不能西禦武安君。"]', '["夷陵城闕倚朝云，戰敗秦師縱火焚。","何事三千珠履客，不能西禦武安君。"]', '诗', 'shi', '', NULL, '詠史詩 夷陵 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b462661-1e9a-4410-a99b-0203bb4cfef6', '詠史詩 漢江', '詠史诗 漢江', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漢江一帶碧流長，兩岸春風起綠楊。","借問膠船何處沒，欲停蘭棹祀昭王。"]', '["漢江一带碧流长，兩岸春风起綠楊。","借问膠船何处沒，欲停蘭棹祀昭王。"]', '诗', 'shi', '', NULL, '詠史詩 漢江 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e6792ae-a52f-45cd-b353-42d032fc2f8c', '詠史詩 蒼梧', '詠史诗 蒼梧', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["有虞龍駕不西還，空委簫韶洞壑間。","無計得知陵寢處，愁雲長滿九疑山。"]', '["有虞龙駕不西還，空委簫韶洞壑间。","無計得知陵寢处，愁云长满九疑山。"]', '诗', 'shi', '', NULL, '詠史詩 蒼梧 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b7679ae-244f-4bf8-b15e-eca75faf6412', '詠史詩 陳宮', '詠史诗 陳宮', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["陳國機權未可涯，如何後主恣嬌奢。","不知即入宮中井，猶自聽吹玉樹花。"]', '["陳国機權未可涯，如何後主恣嬌奢。","不知即入宮中井，猶自听吹玉樹花。"]', '诗', 'shi', '', NULL, '詠史詩 陳宮 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfda82d8-3c7d-4443-b1be-3959502a3c96', '詠史詩 南陽', '詠史诗 南陽', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["世亂英雄百戰餘，孔明方此樂耕鋤。","蜀王不自垂三顧，爭得先生出舊廬。"]', '["世亂英雄百戰餘，孔明方此乐耕鋤。","蜀王不自垂三顧，爭得先生出旧廬。"]', '诗', 'shi', '', NULL, '詠史詩 南陽 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efc4b508-61ba-43fc-a974-c41536dbf42f', '詠史詩 即墨', '詠史诗 即墨', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["即墨門開縱火牛，燕師營裏血波流。","固存不得田單術，齊國尋成一土丘。"]', '["即墨门开縱火牛，燕師營裏血波流。","固存不得田單術，齊国尋成一土丘。"]', '诗', 'shi', '', NULL, '詠史詩 即墨 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a42e6e5-775f-4fca-ae01-84839c5aa756', '詠史詩 渭濱', '詠史诗 渭濱', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["岸草青青渭水流，子牙曾此獨垂鉤。","當時未入非熊兆，幾向斜陽歎白頭。"]', '["岸草青青渭水流，子牙曾此独垂鉤。","當时未入非熊兆，幾向斜陽歎白头。"]', '诗', 'shi', '', NULL, '詠史詩 渭濱 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53cdcc4-2c29-435c-886f-6b6c7d4f644a', '詠史詩 五湖', '詠史诗 五湖', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["東上高山望五湖，雪濤煙浪起天隅。","不知范蠡乘舟後，更有功臣繼踵無。"]', '["东上高山望五湖，雪濤煙浪起天隅。","不知范蠡乘舟後，更有功臣繼踵無。"]', '诗', 'shi', '', NULL, '詠史詩 五湖 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c5e9ca-8713-46c7-9ed8-98371093cfee', '詠史詩 易水', '詠史诗 易水', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["一旦秦皇馬角生，燕丹歸北送荆卿。","行人欲識無窮恨，聽取東流易水聲。"]', '["一旦秦皇马角生，燕丹归北送荆卿。","行人欲識無窮恨，听取东流易水声。"]', '诗', 'shi', '', NULL, '詠史詩 易水 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6176dd3-1bdd-4031-99a1-0771c1baf7b4', '詠史詩 長平', '詠史诗 长平', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["長平瓦震武安初，趙卒俄成戲鼎魚。","四十萬人俱下世，元戎何用讀兵書。"]', '["长平瓦震武安初，趙卒俄成戲鼎鱼。","四十万人俱下世，元戎何用读兵书。"]', '诗', 'shi', '', NULL, '詠史詩 長平 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc265090-847e-4105-9fa3-5e40a93c715f', '詠史詩 西園', '詠史诗 西园', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["月滿西園夜未央，金風不動鄴天涼。","高情公子多秋興，更領詩人入醉鄉。"]', '["月满西园夜未央，金风不动鄴天涼。","高情公子多秋兴，更領诗人入醉乡。"]', '诗', 'shi', '', NULL, '詠史詩 西園 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3770b0be-76b9-4d44-8507-9acf8a4afdce', '詠史詩 長沙', '詠史诗 长沙', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["江上南風起白蘋，長沙城郭異咸秦。","故鄉猶自嫌卑濕，何況當時賦鵩人。"]', '["江上南风起白蘋，长沙城郭異咸秦。","故乡猶自嫌卑濕，何況當时賦鵩人。"]', '诗', 'shi', '', NULL, '詠史詩 長沙 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8731b138-40af-4c4c-9d09-89877e623c35', '詠史詩 圯橋', '詠史诗 圯橋', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["廟算張良獨有餘，少年逃難下邳初。","逡巡不進泥中履，爭得先生一卷書。"]', '["廟算張良独有餘，少年逃难下邳初。","逡巡不進泥中履，爭得先生一卷书。"]', '诗', 'shi', '', NULL, '詠史詩 圯橋 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5678df7-03fd-4d0c-a29e-5d5378e95963', '詠史詩 銅雀臺', '詠史诗 銅雀台', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["魏武龍輿逐逝波，高臺空按望陵歌。","遏雲聲絕悲風起，翻向樽前泣翠娥。"]', '["魏武龙輿逐逝波，高台空按望陵歌。","遏云声絕悲风起，翻向樽前泣翠娥。"]', '诗', 'shi', '', NULL, '詠史詩 銅雀臺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6131b4bf-3c7f-4da0-b872-e1ad4706c52c', '詠史詩 東晉', '詠史诗 东晉', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["石頭城下浪崔嵬，風起聲疑出地雷。","何事苻堅太相小，欲投鞭策過江來。"]', '["石头城下浪崔嵬，风起声疑出地雷。","何事苻堅太相小，欲投鞭策過江来。"]', '诗', 'shi', '', NULL, '詠史詩 東晉 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5870b733-feec-4089-88ff-de4492b1088b', '詠史詩 吳江', '詠史诗 吳江', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["子胥今日委東流，吳國明朝亦古丘。","大笑夫差諸將相，更無人解守蘇州。"]', '["子胥今日委东流，吳国明朝亦古丘。","大笑夫差諸將相，更無人解守蘇州。"]', '诗', 'shi', '', NULL, '詠史詩 吳江 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96465c8a-c13e-451a-bef6-3b0b06e93e7c', '詠史詩 函谷關', '詠史诗 函谷关', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["寂寂函關鎖未開，田文車馬出秦來。","朱門不養三千客，誰爲雞鳴得放回。"]', '["寂寂函关鎖未开，田文车马出秦来。","朱门不養三千客，誰爲雞鳴得放回。"]', '诗', 'shi', '', NULL, '詠史詩 函谷關 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b841e5-5d1f-4fe4-aeaf-0f2e555e5644', '詠史詩 武關', '詠史诗 武关', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["戰國相持竟不休，武關纔掩楚王憂。","出門若取靈均語，豈作咸陽一死囚。"]', '["戰国相持竟不休，武关纔掩楚王憂。","出门若取靈均語，豈作咸陽一死囚。"]', '诗', 'shi', '', NULL, '詠史詩 武關 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e45ee9d-1efb-4216-8bda-2ce832b279d8', '詠史詩 垓下', '詠史诗 垓下', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["拔山力盡霸圖隳，倚劍空歌不逝騅。","明月滿營天似水，那堪回首別虞姬。"]', '["拔山力尽霸圖隳，倚劍空歌不逝騅。","明月满營天似水，那堪回首別虞姬。"]', '诗', 'shi', '', NULL, '詠史詩 垓下 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf8552ec-60a5-4cfa-9186-4a24c110b463', '詠史詩 郴縣', '詠史诗 郴縣', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["義帝南遷路入郴，國亡身死亂山深。","不知埋恨窮泉後，幾度西陵片月沈。"]', '["義帝南遷路入郴，国亡身死亂山深。","不知埋恨窮泉後，幾度西陵片月沈。"]', '诗', 'shi', '', NULL, '詠史詩 郴縣 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae5d792a-bc45-4a29-9948-757e6c5da88b', '詠史詩 東海', '詠史诗 东海', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["東巡玉輦委泉臺，徐福樓船尚未回。","自是祖龍先下世，不關無路到蓬萊。"]', '["东巡玉輦委泉台，徐福楼船尚未回。","自是祖龙先下世，不关無路到蓬萊。"]', '诗', 'shi', '', NULL, '詠史詩 東海 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77196c7b-03cd-444d-9f20-48f34e3e9863', '詠史詩 故宜城', '詠史诗 故宜城', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["武安南伐勒秦兵，疎鑿功將夏禹幷。","誰謂長渠千載後，水流猶入故宜城。"]', '["武安南伐勒秦兵，疎鑿功將夏禹幷。","誰謂长渠千載後，水流猶入故宜城。"]', '诗', 'shi', '', NULL, '詠史詩 故宜城 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7b70a4d-ab77-4488-a60c-270e2e264161', '詠史詩 成都', '詠史诗 成都', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["杜宇曾爲蜀帝王，化禽飛去舊城荒。","年年來呌桃花月，似向春風訴國亡。"]', '["杜宇曾爲蜀帝王，化禽飞去旧城荒。","年年来呌桃花月，似向春风訴国亡。"]', '诗', 'shi', '', NULL, '詠史詩 成都 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4265ca1-3b5d-4fed-a1e6-1aad77abfc36', '詠史詩 檀溪', '詠史诗 檀溪', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["三月襄陽綠草齊，王孫相引到檀溪。","的盧何處埋龍骨，流水依前遶大堤。"]', '["三月襄陽綠草齊，王孫相引到檀溪。","的盧何处埋龙骨，流水依前遶大堤。"]', '诗', 'shi', '', NULL, '詠史詩 檀溪 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb69be8-9426-4420-94b1-b6e6e2a4b6f0', '詠史詩 青塚', '詠史诗 青塚', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["玉貌元期漢帝招，誰知西嫁怨天驕。","至今青塚愁雲起，疑是佳人恨未銷。"]', '["玉貌元期漢帝招，誰知西嫁怨天驕。","至今青塚愁云起，疑是佳人恨未銷。"]', '诗', 'shi', '', NULL, '詠史詩 青塚 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff0bff12-da29-4555-ab92-725cf9f22420', '詠史詩 李陵臺', '詠史诗 李陵台', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["北入單于萬里疆，五千兵敗滯窮荒。","英雄不伏蠻夷死，更築高臺望故鄉。"]', '["北入單于万里疆，五千兵敗滯窮荒。","英雄不伏蠻夷死，更築高台望故乡。"]', '诗', 'shi', '', NULL, '詠史詩 李陵臺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bf02c5c-abc0-41d0-a0f2-a8105a351b6e', '詠史詩 河梁', '詠史诗 河梁', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漢家英傑出皇都，攜手河梁話入胡。","不是子卿全大節，也應低首拜單于。"]', '["漢家英傑出皇都，携手河梁話入胡。","不是子卿全大節，也應低首拜單于。"]', '诗', 'shi', '', NULL, '詠史詩 河梁 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80e87c85-8917-44eb-adab-07ee0c5b11e7', '詠史詩 軹道', '詠史诗 軹道', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漢祖西來秉白旄，子嬰宗廟委波濤。","誰憐君有翻身術，解向秦宮殺趙高。"]', '["漢祖西来秉白旄，子嬰宗廟委波濤。","誰怜君有翻身術，解向秦宮殺趙高。"]', '诗', 'shi', '', NULL, '詠史詩 軹道 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('126a511f-1dfc-42f4-9e8f-1e21caf95369', '詠史詩 漢宮', '詠史诗 漢宮', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["明妃遠嫁泣西風，玉筯雙垂出漢宮。","何事將軍封萬戶，却令紅粉爲和戎。"]', '["明妃远嫁泣西风，玉筯雙垂出漢宮。","何事將軍封万戶，却令紅粉爲和戎。"]', '诗', 'shi', '', NULL, '詠史詩 漢宮 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93ecee4b-6d57-45ba-91c1-56d0bc03e8e0', '詠史詩 豫讓橋', '詠史诗 豫讓橋', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["豫讓酬恩歲已深，高名不朽到如今。","年年橋上行人過，誰有當時國士心。"]', '["豫讓酬恩歲已深，高名不朽到如今。","年年橋上行人過，誰有當时国士心。"]', '诗', 'shi', '', NULL, '詠史詩 豫讓橋 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77628860-7554-441c-b049-9120a53042a7', '詠史詩 華亭', '詠史诗 华亭', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["陸機西沒洛陽城，吳國春風草又青。","惆悵月中千歲鶴，夜來猶爲唳華亭。"]', '["陸機西沒洛陽城，吳国春风草又青。","惆悵月中千歲鹤，夜来猶爲唳华亭。"]', '诗', 'shi', '', NULL, '詠史詩 華亭 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b849fe71-5ef6-4c84-bad7-f1b68693af1b', '詠史詩 東山', '詠史诗 东山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["五馬南浮一化龍，謝安入相此山空。","不知攜妓重來日，幾樹鶯啼谷口風。"]', '["五马南浮一化龙，謝安入相此山空。","不知携妓重来日，幾樹鶯啼谷口风。"]', '诗', 'shi', '', NULL, '詠史詩 東山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a53b90-e0d1-47d5-8c43-3a35e8ae0801', '詠史詩 殺子谷', '詠史诗 殺子谷', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["舉國賢良盡淚垂，扶蘇屈死樹邊時。","至今谷口泉嗚咽，猶似秦人恨李斯。"]', '["舉国賢良尽泪垂，扶蘇屈死樹邊时。","至今谷口泉嗚咽，猶似秦人恨李斯。"]', '诗', 'shi', '', NULL, '詠史詩 殺子谷 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5219034-d722-49ca-a440-76e9a3dbd72a', '詠史詩 馬陵', '詠史诗 马陵', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["墜葉蕭蕭九月天，驅兵獨過馬陵前。","路傍古木蟲書處，記得將軍破敵年。"]', '["墜葉蕭蕭九月天，驱兵独過马陵前。","路傍古木蟲书处，記得將軍破敵年。"]', '诗', 'shi', '', NULL, '詠史詩 馬陵 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('338cb62a-f860-440f-bc06-4b0abb422e36', '詠史詩 玉門關', '詠史诗 玉门关', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["西戎不敢過天山，定遠功成白馬閑。","半夜帳中停燭坐，唯思生入玉門關。"]', '["西戎不敢過天山，定远功成白马闲。","半夜帳中停燭坐，唯思生入玉门关。"]', '诗', 'shi', '', NULL, '詠史詩 玉門關 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db4fe23-a3be-4b05-87ef-282f72f785f3', '詠史詩 滹沱河', '詠史诗 滹沱河', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["光武經營業未興，王郎兵革正憑陵。","須知後漢功臣力，不及滹沱一片冰。"]', '["光武經營業未兴，王郎兵革正憑陵。","須知後漢功臣力，不及滹沱一片冰。"]', '诗', 'shi', '', NULL, '詠史詩 滹沱河 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1874d9f-a8b1-4b2d-97fe-3a64abc1c3b4', '詠史詩 黃河', '詠史诗 黄河', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["博望沈埋不復旋，黃河依舊水茫然。","沿流欲共牛郎語，只得靈槎送上天。"]', '["博望沈埋不复旋，黄河依旧水茫然。","沿流欲共牛郎語，只得靈槎送上天。"]', '诗', 'shi', '', NULL, '詠史詩 黃河 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49928994-807b-4f9a-9f6e-accb0af20648', '詠史詩 鳳皇臺', '詠史诗 鳳皇台', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["秦娥一別鳳皇臺，東入青冥更不回。","空有玉簫千載後，遺聲時到世間來。"]', '["秦娥一別鳳皇台，东入青冥更不回。","空有玉簫千載後，遺声时到世间来。"]', '诗', 'shi', '', NULL, '詠史詩 鳳皇臺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b571905-0e31-47f1-8e5e-92e8d2bff993', '詠史詩 五丈原', '詠史诗 五丈原', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["蜀相西驅十萬來，秋風原下久裴回。","長星不爲英雄住，半夜流光落九垓。"]', '["蜀相西驱十万来，秋风原下久裴回。","长星不爲英雄住，半夜流光落九垓。"]', '诗', 'shi', '', NULL, '詠史詩 五丈原 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c3751ee-b2bc-475f-b9da-20da9a2b9d64', '詠史詩 平城', '詠史诗 平城', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漢帝西征陷虜塵，一朝圍解議和親。","當時已有吹毛劍，何事無人殺奉春。"]', '["漢帝西征陷虜塵，一朝圍解議和親。","當时已有吹毛劍，何事無人殺奉春。"]', '诗', 'shi', '', NULL, '詠史詩 平城 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28426bd8-902d-435d-887c-9ad55874c0a7', '詠史詩 汴水', '詠史诗 汴水', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["千里長河一旦開，亡隋波浪九天來。","錦帆未落干戈起，惆悵龍舟更不回。"]', '["千里长河一旦开，亡隋波浪九天来。","錦帆未落干戈起，惆悵龙舟更不回。"]', '诗', 'shi', '', NULL, '詠史詩 汴水 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b71f76d-6472-4c17-9ff1-b93d028224d8', '詠史詩 蘭臺宮', '詠史诗 蘭台宮', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["遲遲春日滿長空，亡國離宮蔓草中。","宋玉不憂人事變，從遊那賦大王風。"]', '["遲遲春日满长空，亡国離宮蔓草中。","宋玉不憂人事变，從游那賦大王风。"]', '诗', 'shi', '', NULL, '詠史詩 蘭臺宮 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b703aed4-149d-46ce-bc8f-e4c3a1409c5c', '詠史詩 金牛驛', '詠史诗 金牛驛', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["山嶺千重擁蜀門，成都別是一乾坤。","五丁不鑿金牛路，秦惠何由得併吞。"]', '["山嶺千重擁蜀门，成都別是一乾坤。","五丁不鑿金牛路，秦惠何由得併吞。"]', '诗', 'shi', '', NULL, '詠史詩 金牛驛 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0de8b5-efdb-40c0-89d1-3643acb5d3ee', '詠史詩 望思臺', '詠史诗 望思台', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["太子銜冤去不回，臨臯從築望思臺。","至今漢武銷魂處，猶有悲風木上來。"]', '["太子銜冤去不回，臨臯從築望思台。","至今漢武銷魂处，猶有悲风木上来。"]', '诗', 'shi', '', NULL, '詠史詩 望思臺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddd3edd1-33a0-45b4-af1d-feb407680462', '詠史詩 邯鄲', '詠史诗 邯鄲', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["曉入邯鄲十里春，東風吹下玉樓塵。","青娥莫怪頻含笑，記得當年失步人。"]', '["晓入邯鄲十里春，东风吹下玉楼塵。","青娥莫怪頻含笑，記得當年失步人。"]', '诗', 'shi', '', NULL, '詠史詩 邯鄲 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7b5fd63-f191-4dac-ab02-238e05175e8e', '詠史詩 箕山', '詠史诗 箕山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["寂寂箕山春復秋，更無人到此溪頭。","棄瓢巖畔中宵月，千古空聞屬許由。"]', '["寂寂箕山春复秋，更無人到此溪头。","棄瓢巖畔中宵月，千古空闻屬許由。"]', '诗', 'shi', '', NULL, '詠史詩 箕山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a87924-9f8e-4275-b941-00840794999e', '詠史詩 會稽山', '詠史诗 會稽山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["越王兵敗已山棲，豈望全生出會稽。","何事夫差無遠慮，更開羅網放鯨鯢。"]', '["越王兵敗已山棲，豈望全生出會稽。","何事夫差無远慮，更开羅網放鯨鯢。"]', '诗', 'shi', '', NULL, '詠史詩 會稽山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('553e7e40-3d8d-4167-b9e9-9ac2dbc803de', '詠史詩 不周山', '詠史诗 不周山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["共工爭帝力窮秋，因此捐生觸不周。","遂使世間多感客，至今哀怨水東流。"]', '["共工爭帝力窮秋，因此捐生觸不周。","遂使世间多感客，至今哀怨水东流。"]', '诗', 'shi', '', NULL, '詠史詩 不周山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cda7e67c-6e64-4e69-a68b-72def7dc0b0b', '詠史詩 虞坂', '詠史诗 虞坂', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["悠悠虞坂路欹斜，遲日和風簇野花。","未省孫陽身沒後，幾多騏驥困鹽車。"]', '["悠悠虞坂路欹斜，遲日和风簇野花。","未省孫陽身沒後，幾多騏驥困鹽车。"]', '诗', 'shi', '', NULL, '詠史詩 虞坂 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86e49eba-77e5-42c9-a1c2-90a2a2351936', '詠史詩 秦庭', '詠史诗 秦庭', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["楚國君臣草莽間，吳王戈甲未東還。","包胥不動咸陽哭，爭得秦兵出武關。"]', '["楚国君臣草莽间，吳王戈甲未东還。","包胥不动咸陽哭，爭得秦兵出武关。"]', '诗', 'shi', '', NULL, '詠史詩 秦庭 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5509d47c-0ee8-4fbb-be9c-299e77a90e38', '詠史詩 延平津', '詠史诗 延平津', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["延平津路水溶溶，峭壁巍岑一萬重。","昨夜七星潭底見，分明神劍化爲龍。"]', '["延平津路水溶溶，峭壁巍岑一万重。","昨夜七星潭底见，分明神劍化爲龙。"]', '诗', 'shi', '', NULL, '詠史詩 延平津 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d639934c-e35a-49a8-972f-5b1b22d0e2b9', '詠史詩 瑤池', '詠史诗 瑤池', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["阿母瑤池宴穆王，九天仙樂送瓊漿。","漫矜八駿行如電，歸到人間國已亡。"]', '["阿母瑤池宴穆王，九天仙乐送瓊漿。","漫矜八駿行如電，归到人间国已亡。"]', '诗', 'shi', '', NULL, '詠史詩 瑤池 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54405bf9-eca3-4359-8277-360a11b913cb', '詠史詩 銅柱', '詠史诗 銅柱', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["一柱高標險塞垣，南蠻不敢犯中原。","功成自合分茅土，何事翻銜薏苡冤。"]', '["一柱高標險塞垣，南蠻不敢犯中原。","功成自合分茅土，何事翻銜薏苡冤。"]', '诗', 'shi', '', NULL, '詠史詩 銅柱 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67cfe4fc-f793-472c-9cf1-6a4d826835ba', '詠史詩 關西', '詠史诗 关西', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["楊震幽魂下北邙，關西蹤跡遂荒涼。","四知美譽留人世，應與乾坤共久長。"]', '["楊震幽魂下北邙，关西蹤跡遂荒涼。","四知美譽留人世，應與乾坤共久长。"]', '诗', 'shi', '', NULL, '詠史詩 關西 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5996c466-d41a-40ec-903b-56d82b3e3ca6', '詠史詩 高陽池', '詠史诗 高陽池', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["古人未遇即銜桮，所貴愁腸得酒開。","何事山公持玉節，等閑深入醉鄉來。"]', '["古人未遇即銜桮，所貴愁腸得酒开。","何事山公持玉節，等闲深入醉乡来。"]', '诗', 'shi', '', NULL, '詠史詩 高陽池 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd6b374e-8dc8-49bd-9363-83ba767ea96e', '詠史詩 瀘水', '詠史诗 瀘水', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["五月驅兵入不毛，月明瀘水瘴煙高。","誓將雄略酬三顧，豈憚征蠻七縱勞。"]', '["五月驱兵入不毛，月明瀘水瘴煙高。","誓將雄略酬三顧，豈憚征蠻七縱勞。"]', '诗', 'shi', '', NULL, '詠史詩 瀘水 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('251e270e-c9ab-4d52-bb85-560570f12a70', '詠史詩 細柳營', '詠史诗 細柳營', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["文帝鑾輿勞北征，條侯此地整嚴兵。","轅門不峻將軍令，今日爭知細柳營。"]', '["文帝鑾輿勞北征，條侯此地整嚴兵。","轅门不峻將軍令，今日爭知細柳營。"]', '诗', 'shi', '', NULL, '詠史詩 細柳營 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12c06865-5953-478a-86df-2ae3d927be97', '詠史詩 葉縣', '詠史诗 葉縣', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["葉公丘墓已塵埃，雲矗崇墉亦半摧。","借問往年龍見日，幾多風雨送將來。"]', '["葉公丘墓已塵埃，云矗崇墉亦半摧。","借问往年龙见日，幾多风雨送將来。"]', '诗', 'shi', '', NULL, '詠史詩 葉縣 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d19a214-2fe2-4d97-8847-f2aa4e0eb652', '詠史詩 杜郵', '詠史诗 杜郵', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["自古功成禍亦侵，武安冤向杜郵深。","五湖煙月無窮水，何事遷延到陸沈。"]', '["自古功成禍亦侵，武安冤向杜郵深。","五湖煙月無窮水，何事遷延到陸沈。"]', '诗', 'shi', '', NULL, '詠史詩 杜郵 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e2305d3-6ec9-4139-b465-88758c2935ae', '詠史詩 柯亭', '詠史诗 柯亭', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["一宿柯亭月滿天，笛亡人沒事空傳。","中郎在世無甄別，爭得名垂爾許年。"]', '["一宿柯亭月满天，笛亡人沒事空傳。","中郎在世無甄別，爭得名垂爾許年。"]', '诗', 'shi', '', NULL, '詠史詩 柯亭 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('797d83fd-d95f-418b-b47b-ccdbc911200e', '詠史詩 葛陂', '詠史诗 葛陂', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["長房回到葛陂中，人已登真竹化龍。","莫道神仙難頓學，嵇生自是不遭逢。"]', '["长房回到葛陂中，人已登真竹化龙。","莫道神仙难頓学，嵇生自是不遭逢。"]', '诗', 'shi', '', NULL, '詠史詩 葛陂 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef79bf6c-806d-4b90-a97d-94a4853fa650', '詠史詩 博浪沙', '詠史诗 博浪沙', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["嬴政鯨吞六合秋，削平天下虜諸侯。","山東不是無公子，何事張良獨報讐。"]', '["嬴政鯨吞六合秋，削平天下虜諸侯。","山东不是無公子，何事張良独報讐。"]', '诗', 'shi', '', NULL, '詠史詩 博浪沙 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09c3190b-df4b-4342-ab58-4c4a981b22e5', '詠史詩 隴西', '詠史诗 隴西', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["乘春來到隴山西，隗氏城荒碧草齊。","好笑王元不量力，函關那受一丸泥。"]', '["乘春来到隴山西，隗氏城荒碧草齊。","好笑王元不量力，函关那受一丸泥。"]', '诗', 'shi', '', NULL, '詠史詩 隴西 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe911240-bb2b-46da-841f-44a66a46a399', '詠史詩 白帝城', '詠史诗 白帝城', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["蜀江一帶向東傾，江上巍峩白帝城。","自古山河歸聖主，子陽虛共漢家爭。"]', '["蜀江一带向东傾，江上巍峩白帝城。","自古山河归聖主，子陽虛共漢家爭。"]', '诗', 'shi', '', NULL, '詠史詩 白帝城 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4dcc77-2f07-4ce2-b2ce-18acf8fe4d02', '詠史詩 牛渚', '詠史诗 牛渚', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["溫嶠南歸輟棹晨，燃犀牛渚照通津。","誰知萬丈洪流下，更有朱衣躍馬人。"]', '["溫嶠南归輟棹晨，燃犀牛渚照通津。","誰知万丈洪流下，更有朱衣躍马人。"]', '诗', 'shi', '', NULL, '詠史詩 牛渚 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64840efa-cfcf-48a1-b89a-96b32d050e54', '詠史詩 朝歌', '詠史诗 朝歌', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["長嗟墨翟少風流，急管繁弦似寇讐。","若解聞韶知肉味，朝歌欲到肯回頭。"]', '["长嗟墨翟少风流，急管繁弦似寇讐。","若解闻韶知肉味，朝歌欲到肯回头。"]', '诗', 'shi', '', NULL, '詠史詩 朝歌 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da65b32-330f-4063-8691-2d91beda9ed9', '詠史詩 谷口', '詠史诗 谷口', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["一旦天真逐水流，虎爭龍戰爲諸侯。","子真獨有煙霞趣，谷口耕鋤到白頭。"]', '["一旦天真逐水流，虎爭龙戰爲諸侯。","子真独有煙霞趣，谷口耕鋤到白头。"]', '诗', 'shi', '', NULL, '詠史詩 谷口 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afe48910-1cb8-47ca-b38b-70a65e3a53bd', '詠史詩 武陵溪', '詠史诗 武陵溪', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["一溪春水徹雲根，流出桃花片片新。","若到長生是虛語，洞中爭得有秦人。"]', '["一溪春水徹云根，流出桃花片片新。","若到长生是虛語，洞中爭得有秦人。"]', '诗', 'shi', '', NULL, '詠史詩 武陵溪 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9387877-87e9-4437-96ea-a2901ad30202', '詠史詩 大澤', '詠史诗 大澤', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["白蛇初斷路人通，漢祖龍泉血刃紅。","不是咸陽將瓦解，素靈那哭月明中。"]', '["白蛇初斷路人通，漢祖龙泉血刃紅。","不是咸陽將瓦解，素靈那哭月明中。"]', '诗', 'shi', '', NULL, '詠史詩 大澤 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7c039e6-77cd-4db3-b27f-4e32c830b822', '詠史詩 澠池', '詠史诗 澠池', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["日照荒城芳草新，相如曾此挫強秦。","能令百二山河主，便作樽前擊缶人。"]', '["日照荒城芳草新，相如曾此挫強秦。","能令百二山河主，便作樽前擊缶人。"]', '诗', 'shi', '', NULL, '詠史詩 澠池 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb4c81d1-250f-4421-b195-8e83c20edf9b', '詠史詩 峴山', '詠史诗 峴山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["曉日登臨感晉臣，古碑零落峴山春。","松間殘露頻頻滴，酷似當時墮淚人。"]', '["晓日登臨感晉臣，古碑零落峴山春。","松间殘露頻頻滴，酷似當时墮泪人。"]', '诗', 'shi', '', NULL, '詠史詩 峴山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db19b3af-8153-48ee-aa9c-af85a7004e15', '詠史詩 滎陽', '詠史诗 滎陽', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漢祖東征屈未伸，滎陽失律紀生焚。","當時天下方龍戰，誰爲將軍作誄文。"]', '["漢祖东征屈未伸，滎陽失律紀生焚。","當时天下方龙戰，誰爲將軍作誄文。"]', '诗', 'shi', '', NULL, '詠史詩 滎陽 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b5b4a2-7913-46bc-86cf-fdadf2b51968', '詠史詩 長城', '詠史诗 长城', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["祖舜宗堯自太平，秦皇何事苦蒼生。","不知禍起蕭牆內，虛築防胡萬里城。"]', '["祖舜宗堯自太平，秦皇何事苦蒼生。","不知禍起蕭牆內，虛築防胡万里城。"]', '诗', 'shi', '', NULL, '詠史詩 長城 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae401595-6d59-4369-a3e6-c4709af78d2e', '詠史詩 赤壁', '詠史诗 赤壁', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["烈火西焚魏帝旗，周郎開國虎爭時。","交兵不假揮長劍，已挫英雄百萬師。"]', '["烈火西焚魏帝旗，周郎开国虎爭时。","交兵不假揮长劍，已挫英雄百万師。"]', '诗', 'shi', '', NULL, '詠史詩 赤壁 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db6b15f0-c322-4fe9-84a8-97f26a84c702', '詠史詩 田橫墓', '詠史诗 田橫墓', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["古墓崔巍約路岐，歌傳薤露到今時。","也知不去朝黃屋，祗爲曾烹酈食其。"]', '["古墓崔巍約路岐，歌傳薤露到今时。","也知不去朝黄屋，祗爲曾烹酈食其。"]', '诗', 'shi', '', NULL, '詠史詩 田橫墓 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb29898-d09b-4c3d-95ec-de16b63c3af3', '詠史詩 青門', '詠史诗 青门', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漢皇提劍滅咸秦，亡國諸侯盡是臣。","唯有東陵守高節，青門甘作種瓜人。"]', '["漢皇提劍滅咸秦，亡国諸侯尽是臣。","唯有东陵守高節，青门甘作種瓜人。"]', '诗', 'shi', '', NULL, '詠史詩 青門 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9264904f-0f2b-4532-bcdd-b2ac5414168e', '詠史詩 姑蘇臺', '詠史诗 姑蘇台', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["吳王恃霸棄雄才，貪向姑蘇醉醁醅。","不覺錢塘江上月，一宵西送越兵來。"]', '["吳王恃霸棄雄才，貪向姑蘇醉醁醅。","不覺錢塘江上月，一宵西送越兵来。"]', '诗', 'shi', '', NULL, '詠史詩 姑蘇臺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e922c90-92da-40b3-b3fc-ce2eb9f0a3be', '詠史詩 息城', '詠史诗 息城', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["息亡身入楚王家，回首春風一面花。","感舊不言長掩淚，秪應翻恨有容華。"]', '["息亡身入楚王家，回首春风一面花。","感旧不言长掩泪，秪應翻恨有容华。"]', '诗', 'shi', '', NULL, '詠史詩 息城 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec57e656-91cb-44ae-adeb-62d5aea66a40', '詠史詩 上蔡', '詠史诗 上蔡', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["上蔡東門狡兔肥，李斯何事忘南歸。","功成不解謀身退，直待雲陽血染衣。"]', '["上蔡东门狡兔肥，李斯何事忘南归。","功成不解謀身退，直待云陽血染衣。"]', '诗', 'shi', '', NULL, '詠史詩 上蔡 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b8a3515-3aa2-4bcb-b0b3-9dec1084ff4c', '詠史詩 武昌', '詠史诗 武昌', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["王濬戈鋋發上流，武昌鴻業土崩秋。","思量鐵鎖真兒戲，誰爲吳王畫此籌。"]', '["王濬戈鋋發上流，武昌鴻業土崩秋。","思量鐵鎖真兒戲，誰爲吳王畫此籌。"]', '诗', 'shi', '', NULL, '詠史詩 武昌 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4adf73b-b3d9-4ca7-bf8a-72a4aead0417', '詠史詩 鴻溝', '詠史诗 鴻溝', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["虎倦龍疲白刃秋，兩分天下指鴻溝。","項王不覺英雄挫，欲向彭門醉玉樓。"]', '["虎倦龙疲白刃秋，兩分天下指鴻溝。","項王不覺英雄挫，欲向彭门醉玉楼。"]', '诗', 'shi', '', NULL, '詠史詩 鴻溝 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e091cd20-5a86-40f1-a161-3c954dc50ce5', '詠史詩 襃城', '詠史诗 襃城', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["恃寵嬌多得自由，驪山舉火戲諸侯。","秪知一笑傾人國，不覺胡塵滿玉樓。"]', '["恃寵嬌多得自由，驪山舉火戲諸侯。","秪知一笑傾人国，不覺胡塵满玉楼。"]', '诗', 'shi', '', NULL, '詠史詩 襃城 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab19185a-59a9-4d36-870b-f5c091158e2a', '詠史詩 金陵', '詠史诗 金陵', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["侯景長驅十萬人，可憐梁武坐蒙塵。","生前不得空王力，徒向金田自捨身。"]', '["侯景长驱十万人，可怜梁武坐蒙塵。","生前不得空王力，徒向金田自捨身。"]', '诗', 'shi', '', NULL, '詠史詩 金陵 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c2a658e-428f-4c4f-b5bc-bceaae855db7', '詠史詩 洛陽', '詠史诗 洛陽', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["石勒童年有戰機，洛陽長嘯倚門時。","晉朝不是王夷甫，大智何由得預知。"]', '["石勒童年有戰機，洛陽长嘯倚门时。","晉朝不是王夷甫，大智何由得預知。"]', '诗', 'shi', '', NULL, '詠史詩 洛陽 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e464d48-4850-41a3-85ca-e8d7b94f81cc', '詠史詩 番禺', '詠史诗 番禺', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["重岡複嶺勢崔巍，一卒當關萬卒回。","不是大夫多辨說，尉他爭肯築朝臺。"]', '["重岡複嶺勢崔巍，一卒當关万卒回。","不是大夫多辨说，尉他爭肯築朝台。"]', '诗', 'shi', '', NULL, '詠史詩 番禺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85969357-32ad-45f1-98ac-13f2e63e8d81', '詠史詩 汨羅', '詠史诗 汨羅', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["襄王不用直臣籌，放逐南來澤國秋。","自向波間葬魚腹，楚人徒倚濟川舟。"]', '["襄王不用直臣籌，放逐南来澤国秋。","自向波间葬鱼腹，楚人徒倚濟川舟。"]', '诗', 'shi', '', NULL, '詠史詩 汨羅 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9589c402-2cdb-4c65-8762-6ca899cdefc9', '詠史詩 彭澤', '詠史诗 彭澤', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["英傑那堪屈下僚，便栽門柳事蕭條。","鳳皇不共雞爭食，莫怪先生懶折腰。"]', '["英傑那堪屈下僚，便栽门柳事蕭條。","鳳皇不共雞爭食，莫怪先生懶折腰。"]', '诗', 'shi', '', NULL, '詠史詩 彭澤 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f6c76bc-fa94-4363-9941-91d523bc026a', '詠史詩 涿鹿', '詠史诗 涿鹿', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["涿鹿茫茫白草秋，軒轅曾此破蚩尤。","丹霞遙映祠前水，疑是成川血尚流。"]', '["涿鹿茫茫白草秋，軒轅曾此破蚩尤。","丹霞遙映祠前水，疑是成川血尚流。"]', '诗', 'shi', '', NULL, '詠史詩 涿鹿 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce5739ad-e326-44b6-a97c-fb4550906ec9', '詠史詩 洞庭', '詠史诗 洞庭', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["五月扁舟過洞庭，魚龍吹浪水雲腥。","軒轅黃帝今何在，迴首巴山蘆葉青。"]', '["五月扁舟過洞庭，鱼龙吹浪水云腥。","軒轅黄帝今何在，迴首巴山蘆葉青。"]', '诗', 'shi', '', NULL, '詠史詩 洞庭 胡曾 shi');
